window.INEK_DATA = [{"decisionDate":"2016-07-04","publicationDate":"2016-07-27","sourcePage":"https://www.dkgev.de/","id":"AZ-01-2015","categoryLabel":"Altbeschluss vor § 19 KHG","title":"Hauptdiagnose bei Tumorerkrankungen – Beschluss des Schlichtungsausschusses Bund alter Fassung","sourceURL":"https://www.dkgev.de/fileadmin/default/Beschluss_Schlichtungsausschuss_Bund_gem.____17c_Abs._3__KHG.pdf","keywords":"Tumor Malignom Hauptdiagnose Neubildung Komplikation Tumortherapie DKR 0201","codes":{"icd":[],"ops":[],"dkr":[]},"category":"legacy"},{"decisionDate":"2020-06-24","publicationDate":"2020-08-19","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-107","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 107 Dermektomie, Gewichtsabnahme, Plastische Chirurgie.pdf (43,97 kB)","sourceURL":"https://www.g-drg.de/content/download/9666/file/Entscheidung%20KDE%20107%20Dermektomie,%20Gewichtsabnahme,%20Plastische%20Chirurgie.pdf","keywords":"Entscheidung KDE 107 Dermektomie, Gewichtsabnahme, Plastische Chirurgie.pdf (43,97 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n24.06.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des PKV-Verbandes\nwie folgt entschieden:\nEntscheidung KDE 107:\nWird ein Patient nach einer massiven Gewichtsabnahme mit Intertriginalekzem und\nausgeprägten Hautüberschüssen mit einer zirkulären Dermektomie (Fettschürzenreduktion)\nstationär behandelt, ist als Hauptdiagnose der Kode L98.7 Überschüssige und erschlaffte Haut\nund Unterhaut und als Nebendiagnose der Kode L30.4 Intertriginöses Ekzem zu kodieren.\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.09.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n21.07.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-107\nSchlagwort: Dermektomie, Gewichtsabnahme, Plastische Chirurgie\nStand: 29.08.2006\nAktualisiert: 01.01.2017\nICD: R63.4; L30.4\nProblem/Erläuterung:\nKorrekte Kodierung der Hauptdiagnose bei plastisch-chirurgischen Eingriffen nach\nGewichtsabnahme:\nEine Patientin wird wegen \"Z.n. massiver Gewichtsabnahme mit Intertriginalekzem\nund ausgeprägten Hautüberschüssen\" in einer Abteilung für Plastische Chirurgie\nbehandelt.\nTherapeutisch erfolgt eine zirkuläre Dermektomie. Wird als Hauptdiagnose R63.4 Abnorme\nGewichts abnahme angegeben mit der Nebendiagnose L30.4 Intertriginöses Ekzem oder ist\nL30.4 Hauptdiagnose?\nKodierempfehlung SEG-4:\nDie therapieresistenten Intertriginalekzeme als komplizierende Folgezustände begründen\nmedizinisch letztendlich diesen Eingriff. Somit wurde die stationäre Aufnahme zur\nOperation durch diesen komplizierenden Folgezustand der massiven Gewichtsabnahme\nveranlasst. L30.4 ist als Hauptdiagnose anzugeben.\nFür Fälle ab 2016 steht für den komplizierenden Folgezustand mit L98.7 Überschüssige und\nerschlaffte Haut und Unterhaut ein spezifischer Kode zur Verfügung.\nSiehe auch Kodierempfehlungen KDE-209 und KDE-574.\nKommentar FoKA\nDissens:\nDer \"Hautüberschuss\" ist die unmittelbare Folge der Gewichtsabnahme bei Adipositas und\nwird medizinisch auch als Fettschürze bezeichnet. Die Fettschürze ist die dem Symptom\nIntertrigo zu Grunde liegende Erkrankung. Da im Beispiel eine Fettschürzenresektion\ndurchgeführt wird, ist als Hauptdiagnose in Übereinstimmung mit DKR D002f und unter\nVerweis auf KDE-209 als Hauptdiagnose E65 zu verschlüsseln.\nDie Diagnose L30.4 ist als Nebendiagnose zu verschlüsseln.","pdfFile":"pdf/2020-06-24_KDE-107_Entscheidung-KDE-107-Dermektomie,-Gewichtsabnahme,-Plastische-Chirurgie.pdf-(43,97-kB).pdf","codes":{"icd":["L98.7","L30.4","R63.4","E65"],"ops":[],"dkr":["D002f"]},"category":"kde"},{"decisionDate":"2020-06-24","publicationDate":"2020-10-06","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-149","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 149 Nebenniere, Punktion, transgastral, endosonographisch.pdf (136,28 kB)","sourceURL":"https://www.g-drg.de/content/download/9667/file/Entscheidung%20KDE%20149%20Nebenniere,%20Punktion,%20transgastral,%20endosonographisch.pdf","keywords":"Entscheidung KDE 149 Nebenniere, Punktion, transgastral, endosonographisch.pdf (136,28 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n24.06.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des PKV-Verbandes\nwie folgt entschieden:\nEntscheidung KDE 149:\nEine endosonographisch gesteuerte transgastrale diagnostische Punktion der Nebenniere ist mit\nden folgenden Kodes\n1-631.\n- Diagnostische Ösophagogastroskopie (zutreffender Kode ist auszuwählen)\n1-408.0 ↔ Endosonographische Biopsie an endokrinen Organen, Nebenniere\n3-05a Endosonographie des Retroperitonealraumes\nzu kodieren.\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.09.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n21.07.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-149\nSchlagwort: Nebenniere, Punktion, transgastral, endosonographisch\nStand: 2007-04-25\nAktualisiert: 2014-01-15\nOPS: 1-859.x\nProblem/Erläuterung\nBei Tumorverdacht erfolgte eine endosonographisch gesteuerte, transgastrale Punktion der\nNebenniere. Welcher OPS-Kode ist für die erbrachte Leistung zu verwenden?\nKodierempfehlung SEG-4\nEinen spezifischen OPS-Kode für diese Leistung gibt es nicht. Die Prozedur kann mit 1-859.x\nAndere diagnostische Punktion und Aspiration : Sonstige verschlüsselt werden.\nKommentierung FoKA\nDissens:\nDie Kodierung sollte folgende Kodes umfassen:\n1. Gastroskopie --> 1-638.2; gemäß Hinweis unter 1-63 (endoskop. Biopsie ist gesondert\nzu kodieren - 1-40ff.) und Inkl. unter 1-40 ... 1-49 (..endosonogr. Biopsie...)\n2. Biopsie Nebenniere mit Steuerung durch bildgebende Verfahren --> 1-407.5\n3. gemäß den Hinweisen unter 1-445 bis 1-447 kann eine Endosonographie (die mit\nSicherheit vor der Biopsie erfolgte) gesondert kodiert werden --> 3-05a - Endosono\nRetroper.-Raum incl. NN\nRückmeldung SEG-4\nDie SEG 4-Empfehlung wurde 2010 der Weiterentwicklung des OPS angepasst.\nKodierempfehlung SEG-4 aktualisiert zum 31.12.2019\nBis 2009 gab es keinen spezifischen OPS-Kode für diese Leistung. Die Prozedur konnte mit\n1-859.x Andere diagnostische Punktion und Aspiration : Sonstige verschlüsselt werden.\nAb 2010 kann die Prozedur mit 1-408.0 Endosonographische Biopsie an endokrinen\nOrganen, Nebenniere kodiert werden (eine Endosonografie ist gesondert zu kodieren mit\nOPS 3-05a).","pdfFile":"pdf/2020-06-24_KDE-149_Entscheidung-KDE-149-Nebenniere,-Punktion,-transgastral,-endosonographisch.pdf-(136,28-kB).pdf","codes":{"icd":[],"ops":["1-631","1-408.0","3-05a","1-859.x","1-638.2","1-63","1-40ff","1-40","1-49","1-407.5","1-445","1-447"],"dkr":[]},"category":"kde"},{"decisionDate":"2020-06-24","publicationDate":"2020-07-21","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-150","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 150 Leistenhoden, Nierenkolik.pdf (208,95 kB)","sourceURL":"https://www.g-drg.de/content/download/9672/file/Entscheidung%20KDE%20150%20Leistenhoden,%20Nierenkolik.pdf","keywords":"Entscheidung KDE 150 Leistenhoden, Nierenkolik.pdf (208,95 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n24.06.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des PKV-Verbandes\nwie folgt entschieden:\nEntscheidung KDE 150:\nIn dem vorliegenden Fall ist für die Kodierung der Hauptdiagnose die nachfolgende Regel aus\nder DKR D002 Hauptdiagnose, Abschnitt „Zwei oder mehr Diagnosen, die gleichermaßen der\nDefinition der Hauptdiagnose entsprechen“ anzuwenden.\n„Wenn zwei oder mehrere Diagnosen in Bezug zu Aufnahme, Untersuchungsbefunden und/oder\nder durchgeführten Therapie gleichermaßen die Kriterien für die Hauptdiagnose erfüllen und\nICD-10-Verzeichnisse und Kodierrichtlinien keine Verschlüsselungsanweisungen geben, muss\nvom behandelnden Arzt entschieden werden, welche Diagnose am besten der Hauptdiagnose-\nDefinition entspricht. Nur in diesem Fall ist vom behandelnden Arzt diejenige auszuwählen, die\nfür Untersuchung und/oder Behandlung die meisten Ressourcen verbraucht hat. Hierbei ist es\nunerheblich, ob die Krankheiten verwandt sind oder nicht.“\nDie Hauptdiagnose ist danach abhängig vom Ressourcenverbrauch zu kodieren, welcher sich\njedoch an Hand der hier zum Sachverhalt vorliegenden Informationen allein nicht bestimmen\nlässt.\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.09.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n21.07.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-150\nSchlagwort: Leistenhoden, Nierenkolik\nStand: 2007-04-25\nAktualisiert: 2008-01-08\nICD: Q53.1; N20.1\nProblem/Erläuterung\nEin 32-jähiger Patient sucht aufgrund linksseitiger Flankenschmerzen eine urologische\nKlinik auf. Bei der Aufnahmeuntersuchung stellt der Urologe, neben einer leichtgradigen\nMikrohämaturie und einer sonographisch nachweisbaren linksseitigen Nierenektasie, eine\ntastbare, druckschmerzhafte Resistenz in der rechten Leiste fest. Verdacht auf\nLeistenhoden. Nach wenigen Stunden (Schmerzmedikation) ist der Patient bezüglich der\nNierenkolik beschwerdefrei. Nach Durchführung eines Ausscheidungsurogramms (kein\nAufstau des Nierenbeckens, kein Konkrementnachweis) wird die Verdachtsdiagnose eines\nspontanen Steinabgangs ausgesprochen. Aufgrund einer möglichen Entartungsgefahr wird\nder Leistenhoden im Rahmen des stationären Aufenthaltes operativ entfernt.\nWas ist Hauptdiagnose, Q53.1 Nondescensus testis , einseitig oder N20.1 Ureterstein ?\nKodierempfehlung SEG-4\nZum Zeitpunkt der Entscheidungsfindung des Krankenhausarztes bestanden zwei\nbehandlungspflichtige Krankheitsbilder.\nNach DKR D002f Zwei oder mehr Diagnosen, die gleichermaßen der Definition der\nHauptdiagnose entsprechen „muss vom behandelnden Arzt entschieden werden, welche\nDiagnose am besten der Hauptdiagnose-Definition entspricht. Nur in diesem Fall ist vom\nbehandelnden Arzt diejenige auszuwählen, die für Untersuchung und/oder Behandlung die\nmeisten Ressourcen verbraucht hat.“ Im vorliegenden Fall wäre somit die Hauptdiagnose\nQ53.1 Nondescensus testis , einseitig .\nKommentierung FoKA\nDissens:\nHier trifft das Prinzip der konkurrierenden HDs (DKR D002f) nicht zu, da der Leistenhoden\nals alleinige Erkrankung nicht zu einer stat. Krankenhausaufnahme geführt hat.\nHauptsächlich für die Veranlassung der Aufnahme ist der linksseitige Flankenschmerz.","pdfFile":"pdf/2020-06-24_KDE-150_Entscheidung-KDE-150-Leistenhoden,-Nierenkolik.pdf-(208,95-kB).pdf","codes":{"icd":["Q53.1","N20.1"],"ops":[],"dkr":["D002","D002f"]},"category":"kde"},{"decisionDate":"2020-06-24","publicationDate":"2020-10-15","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-174","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 174 Hypothermie.pdf (47,54 kB)","sourceURL":"https://www.g-drg.de/content/download/9668/file/Entscheidung%20KDE%20174%20Hypothermie.pdf","keywords":"Entscheidung KDE 174 Hypothermie.pdf (47,54 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n24.06.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des PKV-Verbandes\nwie folgt entschieden:\nEntscheidung KDE 174:\nDer OPS-Kode 8-851.4 Operativer äußerer Kreislauf (bei Anwendung der Herz-Lungen-\nMaschine) mit tiefer Hypothermie ist nur bei Vorliegen einer Temperatur innerhalb des dort\ngenannten Temperaturintervalls (zum Zeitpunkt der Schlichtung, Temperatur von 20 bis unter\n26 °C) zu kodieren.\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.09.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n21.07.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-174\nSchlagwort: Hypothermie\nStand: 2008-01-08\nAktualisiert: 22.01.2009\nOPS: 8-851.2\nProblem/Erläuterung\nWas ist eine tiefe Hypothermie im Sinne des OPS-Kodes 8-851.2 Operativer äußerer\nKreislauf (bei Anwendung der Herz-Lungen-Maschine): Mit tiefer Hypothermie ?\nKodierempfehlung SEG-4\nIn der Literatur finden sich unterschiedliche Angaben, ab welcher Absenkung der\nKörpertemperatur von einer „tiefen Hypothermie“ auszugehen ist und zwar abhängig\ndavon, zu welchem Zweck die Absenkung der Körpertemperatur erfolgt, ob zur\nBegleittherapie bei Schädelhirntraumata oder zur Hypothermie bei kardiochirurgischen\nEingriffen.\nFür die Anwendung dieses OPS-Kodes war nach Aussage des DIMDI aus dem Jahr 2008 die\nAbsenkung der Körpertemperatur auf 20 °C bis unter 26 °C gemeint gewesen.\nAb 2009 Neuregelung im OPS durch Einführung neuer Kodes und Definitionen: 8-851\nOperativer äußerer Kreislauf (bei Anwendung der Herz-Lungen- Maschine)\n• 8-851.0 Mit Normothermie (mehr als 35 °C)\n• 8-851.1 Mit milder Hypothermie (32 bis 35 °C)\n• 8-851.3 Mit moderater Hypothermie (26 bis unter 32 °C)\n• 8-851.4 Mit tiefer Hypothermie (20 bis unter 26 °C)\n• 8-851.5 Mit profunder Hypothermie (unter 20 °C)\nKommentar FoKA\nDissens:\nIn der angelsächsischen Literatur finden sich zahlreiche Zitationen, die auf den Begriff\n\"deep hypothermia with circulatory arrest\" hinweisen, wobei die Methode hauptsächlich\nbei langdauernden, komplexen Rekonstruktionen des Aortenbogens oder bei der\nVersorgung intrakranieller Aneurysmen zur Anwendung kommt. In diesen\nVeröffentlichungen finden sich dann auch wieder die angegebenen Temperaturen < 20 °C.\nIm deutschsprachigen Raum werden hier in der Literatur überwiegend die\nTemperaturabstufungen: >32°C milde Hypothermie 28 - 32 °C moderate Hypothermie <\n28°C tiefe Hypothermie angegeben.\n\nProblematisch ist, dass die \"Aussage des DIMDI\" nicht prüfbar ist, da trotz intensiver Suche\nkeine entsprechende Veröffentlichung gefunden wurde.\nBöttger P (2005) Hypothermie. In: Tschaut RT (Hrsg) Extrakorporale Zirkulation in Theorie\nund Praxis. Pabst, Lengerich, S 236 -242\nLarsen R. (2005) Anästhesie und Intensivmedizin in Herz-, Thorax- und Gefäßchirurgie.\nSpringer, Berlin Heidelberg New York Tokyo\nHinweis\nDas Problem wurde mit dem DIMDI besprochen. Der Prozedurenkode wurde entsprechend\neines Antrages der Deutschen Gesellschaft für Thorax-, Herz- und Gefäßchirurgie (DGTHG)\neingeführt.\nDas DIMDI prüft die Möglichkeit einer Präzisierung des Prozeduren-Kodes im Rahmen der\nWeiterentwicklung der Klassifikation.","pdfFile":"pdf/2020-06-24_KDE-174_Entscheidung-KDE-174-Hypothermie.pdf-(47,54-kB).pdf","codes":{"icd":[],"ops":["8-851.4","8-851.2","8-851","8-851.0","8-851.1","8-851.3","8-851.5"],"dkr":[]},"category":"kde"},{"decisionDate":"2020-06-24","publicationDate":"2020-10-15","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-262","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 262 Fr&uuml;hgeborenes, Neugeboreneninfektion, Behandlung, prophylaktische.pdf (47,11 kB)","sourceURL":"https://www.g-drg.de/content/download/9673/file/Entscheidung%20KDE%20262%20Fr%C3%BChgeborenes,%20Neugeboreneninfektion,%20Behandlung,%20prophylaktische.pdf","keywords":"Entscheidung KDE 262 Fr&uuml;hgeborenes, Neugeboreneninfektion, Behandlung, prophylaktische.pdf (47,11 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n24.06.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des PKV-Verbandes\nwie folgt entschieden:\nEntscheidung KDE 262:\nDie prophylaktische Gabe eines Antibiotikums an ein Früh- oder Neugeborenes wegen\nstöhnender Atmung und Tachypnoe sowie Zustand nach vorzeitigem Blasensprung der Mutter ist\nmit dem Kode P22.1 Transitorische Tachypnoe beim Neugeborenen und zusätzlich dem Kode\nZ29.21 Systemische prophylaktische Chemotherapie zu kodieren.\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.09.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n21.07.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-262\nSchlagwort: Frühgeborenes, Neugeboreneninfektion, Behandlung, prophylaktische\nStand: 2008-10-23\nAktualisiert:\nICD: P22.1; Z29.2\nProblem/Erläuterung\nEinem Frühgeborenen wird wegen stöhnender Atmung und Tachypnoe bei Zustand nach\nvorzeitigem Blasensprung ein Antibiotikum (Mezlocillin) verabreicht. Beendigung der Gabe\nnach fünf Tagen bei fehlenden Entzündungsparametern, da sich kein Hinweis auf eine\nNeugeboreneninfektion ergab. Kann Z29.2 Sonstige prophylaktische Chemotherapie\nzusätzlich zu P22.1 Transitorische Tachypnoe beim Neugeborenen kodiert werden?\nKodierempfehlung SEG-4\nNur P22.1 Transitorische Tachypnoe beim Neugeborenen wird als Nebendiagnose kodiert.\nDie entsprechende Beeinflussung des Patientenmanagements (Antibiotikagabe) ist durch\ndiese Nebendiagnose veranlasst worden. In der Nebendiagnosendefinition wird nicht\ngefordert, dass eine als Nebendiagnose zu kodierende Krankheit/Beschwerde auch\nursächlich oder spezifisch behandelt werden muss.\nZ29.2 Sonstige prophylaktische Chemotherapie kann nicht zusätzlich kodiert werden. Ein\nZ-Kode kann nur verwendet werden, wenn Diagnosen/Symptome bestehen, die nicht als\nKrankheit, Verletzung oder äußere Ursache unter den Kategorien A00-Y89 klassifizierbar\nsind.\nBezüglich der Verwendung von Z-Kodes sind die Hinweise am Anfang von Kapitel XXI der\nICD-10-GM zu beachten.\nKommentar FoKA\nDissens:\nZur Kodierung der Tachypnoe ist gemäß DKR 1605a P22.- oder P24.- zu verwenden.\nGemäß ICD-10 Katalog kann bei \"Fällen [...], in denen Sachverhalte als \"Diagnosen\" oder\n\"Probleme\" angegeben sind, die nicht als Krankheit, Verletzung oder äußere Ursache unter\nden Kategorien A00-Y89 klassifizierbar sind\" ein Z-Kode gewählt werden.\nDer vorzeitige Blasensprung der Mutter stellt einen Sachverhalt dar, der für das\nNeugeborene das Risiko für eine Neugeborenen-Sepsis erhöht. Dieses spezielle Problem\nwird gemäß AWMF-Leitlinie (Prophylaxe der Neugeborensepsis, Nr. 024/020) mittels\nAntibiotika-Gabe behandelt und kann am ehesten mittels Z29.2 kodiert werden.\nRückmeldung SEG-4\nRückmeldung steht noch aus.\n\nKodierempfehlung SEG-4 aktualisiert zum 31.12.2019\nNur P22.1 Transitorische Tachypnoe beim Neugeborenen wird als Nebendiagnose kodiert.\nDie entsprechende Beeinflussung des Patientenmanagements (Antibiotikagabe) ist durch\ndiese Nebendiagnose veranlasst worden. In der Nebendiagnosendefinition wird nicht\ngefordert, dass eine als Nebendiagnose zu kodierende Krankheit/Beschwerde auch\nursächlich oder spezifisch behandelt werden muss.\nZ29.21 Sonstige prophylaktische Chemotherapie , Systemische prophylaktische\nChemotherapie kann nicht zusätzlich kodiert werden. Ein Z-Kode kann nur verwendet\nwerden, wenn Diagnosen/ Symptome bestehen, die nicht als Krankheit, Verletzung oder\näußere Ursache unter den Kategorien A00-Y89 klassifizierbar sind.\nBezüglich der Verwendung von Z-Kodes sind die Hinweise am Anfang von Kapitel XXI der\nICD-10-GM zu beachten.","pdfFile":"pdf/2020-06-24_KDE-262_Entscheidung-KDE-262-Fr&uuml;hgeborenes,-Neugeboreneninfektion,-Behandlung,-prophylaktische.pdf-(47,.pdf","codes":{"icd":["P22.1","Z29.21","Z29.2","A00","Y89","P22","P24"],"ops":[],"dkr":[]},"category":"kde"},{"decisionDate":"2020-06-24","publicationDate":"2020-11-11","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-326","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 326 Rektusscheidenh&auml;matom, Antikoagulanzien, H&auml;morrhagische Diathese.pdf (49,17 kB)","sourceURL":"https://www.g-drg.de/content/download/9674/file/Entscheidung%20KDE%20326%20Rektusscheidenh%C3%A4matom,%20Antikoagulanzien,%20H%C3%A4morrhagische%20Diathese.pdf","keywords":"Entscheidung KDE 326 Rektusscheidenh&auml;matom, Antikoagulanzien, H&auml;morrhagische Diathese.pdf (49,17 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n24.06.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des PKV-Verbandes\nwie folgt entschieden:\nEntscheidung KDE 326:\nWird ein Patient wegen eines nichttraumatischen Rektusscheidenhämatoms unter\nMarcumartherapie® (INR im therapeutischen Bereich, Einnahme gemäß Verordnung) stationär\nbehandelt, ist der Kode M62.88 Sonstige näher bezeichnete Muskelkrankheiten, sonstige\nLokalisation (u.a. Rumpf) als Hauptdiagnose und der Kode D68.33 Hämorrhagische Diathese\ndurch Cumarine (Vitamin-K-Antagonisten) als Nebendiagnose, optional ergänzt um den Kode\nY57.9! Komplikationen durch Arzneimittel oder Drogen zu kodieren.\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.09.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n21.07.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-326\nSchlagworte: Rektusscheidenhämatom, Antikoagulanzien, Hämorrhagische Diathese\nStand: 20.04.2010\nAktualisiert: 15.01.2015\nICD: R58; D68.30; Y57.9!\nProblem/Erläuterung\nEin Patient wird wegen eines nichttraumatischen Rektusscheidenhämatoms unter\nMarcumar®-Einnahme (INR im therapeutischen Bereich) aufgenommen.\nWas ist die Hauptdiagnose?\nKodierempfehlung SEG-4\nGemäß DKR D014 ist für die Kodierung stets das systematische Verzeichnis maßgeblich.\nSoweit das Alphabetische Verzeichnis zu einem unspezifischen Kode führt, ist deshalb im\nsystematischen Verzeichnis zu prüfen, ob eine spezifischere Kodierung möglich ist.\nGemäß DKR 1917 werden unerwünschte Nebenwirkungen indikationsgerechter\nArzneimittel bei Einnahme gemäß Verordnung wie folgt kodiert: Ein oder mehrere Kodes\nfür den krankhaften Zustand in dem sich die Nebenwirkungen manifestieren.\nSomit ist die zur Aufnahme führende Blutung, hier das Hämatom, mit R58 Blutung,\nanderenorts nicht klassifiziert , als Hauptdiagnose zu kodieren. D68.33 Sonstige\nKoagulopathien, Hämorrhagische Diathese durch Antikoagulanzien und Antikörper,\nHämorrhagische Diathese durch Cumarine (Vitamin‐K-Antagon isten) ist als Nebendiagnose\nzu kodieren, sofern die Nebendiagnosendefinition erfüllt ist. Optional kann als\nNebendiagnose Y57.9! Komplikationen durch Arzneimittel oder Drogen verschlüsselt\nwerden. Für Fälle ab 2012 sind die Änderungen in der ICD zu berücksichtigen. Ab 2012 ist\ndas nicht traumatische Rektusscheidenhämatom mit M62.88 Sonstige Muskelkrankheiten,\nsonstige näher bezeichnete Muskelkrankheiten, sonstige zu kodieren.\nKommentar FoKA\nDissens (Stand 27.04.2015):\nIm alphabetischen ICD Verzeichnis wird der Eintrag Rektusscheidenhämatom bei\nMarcumartherapie spezifisch unter D68.33 abgebildet.\nRückmeldung SEG-4:\nRückmeldung steht noch aus.\n\nKodierempfehlung SEG-4 aktualisiert zum 31.12.2019\nFür Fälle bis einschließlich 2011 gilt:\nGemäß DKR D014 ist für die Kodierung stets das Systematische Verzeichnis maßgeblich.\nSoweit das Alphabetische Verzeichnis zu einem unspezifischen Kode führt, ist deshalb im\nsystematischen Verzeichnis zu prüfen, ob eine spezifischere Kodierung möglich ist.\nGemäß DKR 1917 werden unerwünschte Nebenwirkungen indikationsgerechter\nArzneimittel bei Einnahme gemäß Verordnung wie folgt kodiert: Ein oder mehrere Kodes\nfür den krankhaften Zustand in dem sich die Nebenwirkungen manifestieren.\nSomit ist die zur Aufnahme führende Blutung, hier das Hämatom, mit R58 Blutung,\nanderenorts nicht klassifiziert , als Hauptdiagnose zu kodieren. D68.33 Sonstige\nKoagulopathien, Hämorrhagische Diathese durch Antikoagulanzien und Antikörper,\nHämorrhagische Diathese durch Cumarine (Vitamin-K -Antagon isten) ist als Nebendiagnose\nzu kodieren, sofern die Nebendiagnosendefinition erfüllt ist. Optional kann als\nNebendiagnose Y57.9! Komplikationen durch Arzneimittel oder Drogen verschlüsselt\nwerden.\nFür Fälle ab 2012 sind die Änderungen in der ICD zu berücksichtigen. Ab 2012 ist das nicht\ntraumatische Rektusscheidenhämatom mit M62.88 Sonstige Muskelkrankheiten, sonstige\nnäher bezeichnete Muskelkrankheiten, sonstige zu kodieren.\nFür Fälle ab 2012 gilt:\nDie Änderungen in der ICD-10-GM sind zu berücksichtigen. Ab 2012 ist das nicht\ntraumatische Rektusscheidenhämatom mit M62.88 Sonstige Muskelkrankheiten, Sonstige\nnäher bezeichnete Muskelkrankheiten, Sonstige zu kodieren.\nD68.33 (ab 2015, bis einschließlich 2014 D68.30) Sonstige Koagulopathien, Hämorrhagische\nDiathese durch Antikoagulanzien und Antikörper, Hämorrhagische Diathese durch\nCumarine (Vitamin-K -Antagonisten) ist gemäß DKR 1917 als Nebendiagnose zu kodieren,\nsofern die Nebendiagnosendefinition erfüllt ist. Optional kann als sekundäre\nSchlüsselnummer Y57.9! Komplikationen durch Arzneimittel oder Drogen angegeben\nwerden.\nSiehe auch Kodierempfehlungen 73 und 316.","pdfFile":"pdf/2020-06-24_KDE-326_Entscheidung-KDE-326-Rektusscheidenh&auml;matom,-Antikoagulanzien,-H&auml;morrhagische-Diathese.pdf-.pdf","codes":{"icd":["M62.88","D68.33","Y57.9","R58","D68.30"],"ops":[],"dkr":["D014"]},"category":"kde"},{"decisionDate":"2020-06-24","publicationDate":"2020-08-19","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-344","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 344 Reanimation, operative.pdf (43,5 kB)","sourceURL":"https://www.g-drg.de/content/download/9675/file/Entscheidung%20KDE%20344%20Reanimation,%20operative.pdf","keywords":"Entscheidung KDE 344 Reanimation, operative.pdf (43,5 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n24.06.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des PKV-Verbandes\nwie folgt entschieden:\nEntscheidung KDE 344:\nDie manuelle Herzkompression zur Reanimation bei bereits im Rahmen einer anderen Operation\neröffnetem Thorax ist mit dem Kode 5-379.0 Andere Operationen an Herz und Perikard, Offene\nHerzmassage zu kodieren.\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.09.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n21.07.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-344\nSchlagworte: Reanimation, operative\nStand: 2010-10-28\nAktualisiert:\nOPS: 5-379.0; 8-772\nProblem/Erläuterung:\nAnlage eines aortokoronaren 3fach-Bypasses. Kurz nach Abgehen von der Herz-Lungen-\nMaschine (HLM) kommt es bei noch offenem Thorax zum Kreislaufzusammenbruch.\nEntschluss zum erneuten Einsatz der HLM, bis dahin überbrückend manuelle\nHerzkompression über drei Minuten. Ist die manuelle Herzkompression mit\n5-379.0 Andere Operationen an Herz und Perikard, Offene Herzmassage\nund zusätzlich\n8-772 Maßnahmen im Rahmen der Reanimation, Operative Reanimation\nzu kodieren?\nKodierempfehlung SEG-4:\nDie manuelle Herzkompression bei bereits zu operativen Zwecken eröffnetem Thorax ist\nmit 5-379.0 Andere Operationen an Herz und Perikard, Offene Herzmassage zu kodieren.\n8-772 Maßnahmen im Rahmen der Reanimation, operative Reanimation ist nur dann zu\nverwenden, wenn eine Thoraxeröffnung ausschließlich zum Zweck der Reanimation\ndurchgeführt wird.\nKommentierung FoKA:\nDissens:\nDie Lösung des geschilderten Problems erschliesst sich dem FoKA nicht auf logischem Weg:\nDie Notwendigkeit der Differenzierung zwischen operativer Reanimation als isolierter\nMassnahme im Sinne einer Thorakotomie allein zum\nZweck der Reanimation einerseits und einer Reanimation während einer sonstigen\nOperation am offenen Thorax andererseits ist nachvollziehbar. Jedoch widerspricht die\nLösung der SEG-4 der Systematik des OPS-Kataloges (Kap. 5 vs. 8)\nEine Klarstellung durch das DIMDI ist erforderlich und wurde durch den FoKA angefragt.\nRückmeldung SEG-4:\nkeine","pdfFile":"pdf/2020-06-24_KDE-344_Entscheidung-KDE-344-Reanimation,-operative.pdf-(43,5-kB).pdf","codes":{"icd":[],"ops":["5-379.0","8-772"],"dkr":[]},"category":"kde"},{"decisionDate":"2020-06-24","publicationDate":"2020-12-16","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-454","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 454 Cholestase.pdf (44,38 kB)","sourceURL":"https://www.g-drg.de/content/download/9676/file/Entscheidung%20KDE%20454%20Cholestase.pdf","keywords":"Entscheidung KDE 454 Cholestase.pdf (44,38 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n24.06.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des PKV-Verbandes\nwie folgt entschieden:\nEntscheidung KDE 454:\nDer Kode K71.0 Toxische Leberkrankheit mit Cholestase ist nur dann anzuwenden, wenn eine\ndurch Giftstoffe ausgelöste toxische Leberkrankheit mit nachfolgender, zumeist intrahepatischer\nCholestase vorliegt.\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.09.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n21.07.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-454\nSchlagwort: Cholestase\nStand: 2012-08-12\nAktualisiert: 01.01.2016\nICD: K80.51; K71.0; K83.1\nProblem/Erläuterung:\nIst bei Vorliegen einer extrahepatischen Cholestase durch ein präpapilläres Konkrement,\nwelche durch Papillotomie behandelt wurde, neben dem ICD-Kode K80.51 Gallengangsstein\nohne Cholangitis oder Cholezystitis, mit Gallenwegsobstruktion zusätzlich der ICD-Kode\nK71.0 Toxische Leberkrankheit mit C holestase anzugeben?\nKodierempfehlung SEG-4:\nDie Inklusiva zum ICD-Kode K71.0 beinhalten neben der Cholestase, die in Verbindung mit\ntoxischen Leberzellschädigungen auftritt, auch eine „reine“ Cholestase. Ätiopathogenetisch\nund klassifikatorisch sind diese Zustände von der extrahepatischen Cholestase abzugrenzen\n(siehe hierzu K83.1). Entsprechend der Bezeichnung des ICD-Kodes K71.0 Toxische\nLeberkrankheit mit Cholestase werden hiermit toxische Leberschäden erfasst, die eine\nCholestase zur Folge haben, nicht umgekehrt.\nDie Einteilung toxischer Leberschäden nach dem betroffenen Zelltyp beinhaltet u.a.\nSchäden vom hepatitischen Typ und Verfettung (Zielzelle: Hepatozyt), und Schäden vom\ncholestatischen Typ (Zielzellen: Cholangiozyt und Hepatozyt). Als so genannte „reine“\nCholestase wird eine toxisch bedingte Störung des Galleflusses ohne eine begleitende\nEntzündung bezeichnet.\nDer ICD-Kode K71.0 Toxische Leberkrankheit mit Cholestase ist somit bei Vorliegen einer\nnicht toxisch bedingten, extrahepatischen Gallen(wegs-)stauung nicht anzugeben.\nKommentierung FoKA:\nDissens:\nDer Satz \"Entsprechend der Bezeichnung des ICD-Kodes K71.0 Toxische Leberkrankheit mit\nCholestase werden hiermit toxische Leberschäden erfasst, die eine Cholestase zur Folge\nhaben, nicht umgekehrt.\" ist weder aus dem systematischen noch aus dem alphabetischen\nVerzeichnis ableitbar. Stattdessen ist im Kode auch der Begriff \"Cholestase mit\nLeberzellschädigung\" eingeschlossen,\nAus der Problembeschreibung geht darüber hinaus nicht hervor, ob eine Leberschädigung\ndurch die Cholestase verursacht wurde.\nRückmeldung SEG 4\nKeine Ätiologie-Kodierung. Kein Änderungsbedarf. (27.08.2015)","pdfFile":"pdf/2020-06-24_KDE-454_Entscheidung-KDE-454-Cholestase.pdf-(44,38-kB).pdf","codes":{"icd":["K71.0","K80.51","K83.1"],"ops":[],"dkr":[]},"category":"kde"},{"decisionDate":"2020-06-24","publicationDate":"2020-08-19","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-533","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 533 Klappenvitien, Aortenstenose, Mitralinsuffizienz.pdf (43,3 kB)","sourceURL":"https://www.g-drg.de/content/download/9677/file/Entscheidung%20KDE%20533%20Klappenvitien,%20Aortenstenose,%20Mitralinsuffizienz.pdf","keywords":"Entscheidung KDE 533 Klappenvitien, Aortenstenose, Mitralinsuffizienz.pdf (43,3 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n24.06.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des PKV-Verbandes\nwie folgt entschieden:\nEntscheidung KDE 533:\nLiegen gleichzeitig Vitien mehrerer Herzklappen vor, so ist für jede betroffene Herzklappe jeweils\nder Kode, welcher Art und Ursache des Vitiums zutreffend beschreibt, zu kodieren.\nKombinations-Schlüsselnummern dürfen nur verwendet werden, wenn sie die genannten\nInformationen klappenspezifisch genau beschreiben.\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.09.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n21.07.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-533\nSchlagworte: Klappenvitien, Aortenstenose, Mitralinsuffizienz\nErstellt: 17.12.2014\nAktualisiert: 31.08.2017\nICD: I08.‐\nProblem/Erläuterung\nBei einem Patienten liegen eine leichte Aortenstenose und eine höhergradige\nMitralinsuffizienz vor. Die Genese der Klappenvitien ist nicht bekannt.\nSind die Vitien jeweils spezifisch nach der Art des Vitiums zu kodieren oder ist eine\nSchlüsselnummer aus I08.‐Krankheiten mehrerer Herzklappen zu verwenden?\nKodierempfehlung SEG-4:\nDie Schlüsselnummer I08.0 Krankheiten der Mitral‐ und Aortenklappe, kombiniert ist zu\nverwenden. Das Inkl. beim Kode I08.0 besagt, dass hier Krankheiten der Mitralklappe und\nder Aortenklappe zu kodieren sind, unabhängig ob als rheumatisch bezeichnet oder nicht\nnäher bezeichnet. Dieser Kombinationskode ist vorrangig vor den Einzelkodes.\nSiehe auch KDE 585\nKommentierung FoKA:\nDissens: Bei der Auswahl eines ICD-Kodes sind vorrangig die DKR anzuwenden. Der Kode\nI08.0 ist eine Kombinations-Schlüsselnummer, zu berücksichtigen ist demzufolge die DKR\nD010a Kombinations-Schlüsselnummern:\nDie Kombinations-Schlüsselnummer ist nur dann zu verwenden, wenn diese\nSchlüsselnummer die betreffende diagnostische Information vollständig wiedergibt und\nwenn das Alphabetische Verzeichnis eine entsprechende Anweisung gibt.\nMehrfachkodierungen (siehe DKR D012 Mehrfachkodierung (Seite 20)) dürfen nicht\nverwendet werden, wenn die Klassifikation eine Kombinations-Schlüsselnummer\nbereitstellt, die eindeutig alle in der Diagnose dokumentierten Elemente umfasst.\nWesentliche Elemente der Diagnose \"Klappenfehler\" sind Informationen über\nStenosierungen oder Insuffizienzen, die in dem Kombinationskode nicht enthalten sind. Die\nAnwendung der übergeordneten DKR führt zu einem Widerspruch zu den\nInklusiva/Exklusiva der ICD-Kodes I08.- ; I34.- und I35.- . Im Fallbeispiel sind deshalb die\nKodes I34.0 Mitralklappeninsuffizienz und I35.0 Aortenklappenstenose zu verwenden.\n(Kein Anpassungsbedarf 15.09.2017)\nRückmeldung SEG 4\nKein Änderungsbedarf. Regelung im G-DRG-System 2016.\n(17.12.2015)","pdfFile":"pdf/2020-06-24_KDE-533_Entscheidung-KDE-533-Klappenvitien,-Aortenstenose,-Mitralinsuffizienz.pdf-(43,3-kB).pdf","codes":{"icd":["I08","I08.0","I34","I35","I34.0","I35.0"],"ops":[],"dkr":["D010a","D012"]},"category":"kde"},{"decisionDate":"2020-07-29","publicationDate":"2020-10-15","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-17","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 17 MRSA.pdf (47,8 kB)","sourceURL":"https://www.g-drg.de/content/download/9699/file/Entscheidung%20KDE%2017%20MRSA.pdf","keywords":"Entscheidung KDE 17 MRSA.pdf (47,8 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n29.07.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 17:\nDer asymptomatische Keimträger mit Erregernachweis MRSA ohne diesbezügliche Erkrankung\nist mit folgenden Kodes zu kodieren:\nZ22.3 Keimträger anderer näher bezeichneter bakterieller Krankheiten\nU80.00! Staphylococcus aureus mit Resistenz gegen Oxacillin oder Methicillin [MRSA].\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.10.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n19.08.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-17\nSchlagwort: MRSA\nErstellt: 08.08.2005\nAktualisiert: 15.01.2015\nICD: Z22.3; U80.0!; B95.6!\nProblem/Erläuterung:\nWie wird der asymptomatische Keimträger mit Erregernachweis MRSA verschlüsselt?\nKodierempfehlung SEG-4:\nZ22.3 Keimträger anderer näher bezeichneter bakterieller Krankheiten mit U80.00!\nStaphylococcus aureus mit Resistenz gegen Oxacillin oder Methicillin [MRSA] .\nB95.6! Staphylococcus aureus als Ursache von Krankheiten, die in anderen Kapiteln\nklassifiziert sind wird nicht kodiert, da keine Krankheit vorliegt.\n„Wird zurzeit überarbeitet“\nAktualisiert: 10.09.2014\nEin Screening auf MRSA nach den Empfehlungen der Kommission für Krankenhaushygiene\nund Infektionsprävention (KRINKO) dient der Vermeidung der Kontamination von\nMitpatienten, Personal und unbelebter Umgebung im Krankenhaus sowie gegebenenfalls\nder Einleitung von Sanierungsmaßnahmen beim Betroffenen und erweiterten\nHygienemaßnahmen. Bei asymptomatischen Keimträgern besteht weder eine Krankheit,\nnoch eine Beschwerde. Eine Kodierung als Nebendiagnose bei positivem MRSA-Nachweis\naufgrund des Screening-Tests allein ohne Behandlungsbedürftigkeit ist gemäß DKR D003\nebenso wie bei negativem Testergebnis zunächst nicht möglich. Es liegt allenfalls ein\nabnormer Befund vor, der nur dann kodiert werden kann, wenn sich hieraus eine\ntherapeutische Maßnahme oder eine weiterführende Diagnostik ergibt. In diesem Fall wäre\nentsprechend den Hinweisen zu Kapitel XXI der ICD-10-GM Z22.3 Keimträger anderer näher\nbezeichneter bakterieller Krankhei ten zu kodieren in Verbindung mit U80.00!\nStaphylococcus aureus mit Resistenz gegen Oxacillin oder Methicillin [MRSA] . B95.6!\nStaphylococcus aureus als Ursache von Krankheiten, die in anderen Kapiteln klassifiziert\nsind wird nicht kodiert, da keine Krankheit vorliegt.\nKommentar FoKA\nDissens (Revision am 27.04.2015):\nIm Beispiel wird der Begriff \"Krankheit\" als unbestimmter Rechtsbegriff als\nEntscheidungsmaßstab verwendet.\n\nAus juristischer Sicht wird Krankheit als \"regelwidriger körperlicher oder geistiger Zustand\n(verstanden), dessen Eintritt entweder die Notwendigkeit einer Heilbehandlung des\nVersicherten und/oder Arbeitsunfähigkeit zur Folge hat. Diesen Begriff hat der Gesetzgeber\ndes GRG § 27 zu Grunde gelegt. Behandlungsbedürftigkeit liegt vor, wenn ein\nregelwidriger Körperzustand mit ärztlicher Hilfe mit Aussicht auf Erfolg behoben,\nmindestens aber gebessert oder vor Verschlimmerung bewahrt werden kann oder wenn\närztliche Behandlung erforderlich ist, um Schmerzen oder sonstige Beschwerden zu lindern.\n(Bußmann-Weigl, 2004)\nDie Besiedlung mit MRSA ist ein regelwidriger Zustand, der das Risiko für Komplikationen\nund fatale Verläufe erheblich erhöht.\nErfolgt eine Behandlung zur Sanierung des Keimträgers oder besondere\nHygienemaßnahmen zum Schutz der Umgebung, liegt eine Krankheit mit therapeutischer\nKonsequenz vor, B95.6! ist gemäß DKR D012i, Tabelle 2 der DKR obligat zu kodieren.","pdfFile":"pdf/2020-07-29_KDE-17_Entscheidung-KDE-17-MRSA.pdf-(47,8-kB).pdf","codes":{"icd":["Z22.3","U80.00","U80.0","B95.6"],"ops":[],"dkr":["D003","D012i"]},"category":"kde"},{"decisionDate":"2020-07-29","publicationDate":"2020-08-19","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-25","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 25 An&auml;mie, Fols&auml;uremangel.pdf (42,54 kB)","sourceURL":"https://www.g-drg.de/content/download/9700/file/Entscheidung%20KDE%2025%20An%C3%A4mie,%20Fols%C3%A4uremangel.pdf","keywords":"Entscheidung KDE 25 An&auml;mie, Fols&auml;uremangel.pdf (42,54 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n29.07.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 25:\nEine Anämie infolge eines Folsäuremangels ist nur mit dem Kode D52.- Folsäure-Mangelanämie\nspezifisch zu kodieren. Der Kode E53.8 ist für die Abbildung der Folsäuremangelanämie nicht\nzusätzlich zu kodieren.\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.10.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n19.08.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-25\nSchlagwort: Anämie, Folsäuremangel\nStand:\nAktualisiert: 2012-01-16\nICD: E53.8; D52.-\nProblem/Erläuterung\nWie wird eine Anämie infolge Folsäuremangel verschlüsselt?\nDarf zusätzlich zur Anämie E53.8 Mangel an sonstigen näher bezeichneten Vitaminen des\nVitamin B -Komplexes kodiert werden?\nKodierempfehlung SEG-4\nD52.- Folsäure-Mangelanämie ist die spezifische Kodierung.\nSiehe auch Exklusivum unter E50 bis E64. Die zusätzliche Verschlüsselung mit E53.8 ist somit\nnicht möglich.\nKommentar FoKA\nDissens:\nFalls der Folsäuremangel und die Anämie behandelt wird (Folsäuresubstitution und\nBluttransfusion) kann die E53.8 neben der D52.- verschlüsselt werden, selbst wenn E53.8 als\nExkl. aufgeführt ist, denn zur Bedeutung und\nAnwendung der Exklusiva schreibt das DIMDI: \"Dürfen Kodes, die im \"Exkl.\" eines Kodes\ngenannt werden, gleichzeitig mit diesem verschlüsselt werden? Das \"Exkl.\" eines Kodes\nbesagt, dass mit dem im Exklusivum genannten Kode eine Erkrankung anderer Genese\nabgegrenzt (klassifiziert) wird. Folglich können besagte Kodes nebeneinander verwendet\nwerden, wenn die Erkrankung \"sowohl als auch\" beim Patienten vorkommen können und\ndiagnostisch voneinander abgrenzbar sind.\"\nRückmeldung SEG-4\nKein Anpassungsbedarf","pdfFile":"pdf/2020-07-29_KDE-25_Entscheidung-KDE-25-An&auml;mie,-Fols&auml;uremangel.pdf-(42,54-kB).pdf","codes":{"icd":["D52","E53.8","E50","E64"],"ops":[],"dkr":[]},"category":"kde"},{"decisionDate":"2020-07-29","publicationDate":"2020-11-25","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-67","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 67 Hyperglyk&auml;mie, Cortison.pdf (43,91 kB)","sourceURL":"https://www.g-drg.de/content/download/9701/file/Entscheidung%20KDE%2067%20Hyperglyk%C3%A4mie,%20Cortison.pdf","keywords":"Entscheidung KDE 67 Hyperglyk&auml;mie, Cortison.pdf (43,91 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n29.07.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 67:\nEine mit Altinsulin therapierte Hyperglykämie, die sich unter einer stationären Kortisontherapie\nbei einem Patienten entwickelt, bei dem kein Diabetes mellitus bekannt ist, und bei dem keine\nDiagnostik im Hinblick auf einen Diabetes mellitus erfolgt, wird mit dem Kode R73.9\nHyperglykämie, nicht näher bezeichnet, optional ergänzt um den Kode Y57.9! Komplikationen\ndurch Arzneimittel oder Drogen kodiert.\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.10.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n19.08.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-67\nSchlagwort: Hyperglykämie, Cortison\nErstellt: 28.02.2006\nAktualisiert: 08.01.2013\nICD: R73.9; Y57.9!; E11.-\nProblem/Erläuterung\nEin Patient bekommt während des stationären Aufenthaltes Cortison, entwickelt daraufhin\neine Hyperglykämie und bekommt Altinsulin. Kein Diabetes bekannt, keine weitere\nDiagnostik diesbezüglich. Wie ist die Hyperglykämie zu kodieren?\nKodierempfehlung SEG 4\nLaut DKR 1917d lautet die Diagnose R73.9 Hyperglykämie, nicht näher bezeichnet in\nKombination mit Y57.9! Komplikation durch Arzneimittel oder Drogen , kein Kode aus E11.-\nNicht primär insulinabhängiger Diabetes mellitus [Typ-2 -Diabetes] .\nKommentar FoKA\nDissens (Revision vom 28.01.2013):\nNur ein Patient mit Diabetes entgleist unter einer Steroidtherapie - der mit Cortison\nbehandelte Patient muss also mindestens einen latenten Diabetes haben, um unter\nSteroidgabe Hyperglykämien entwickeln zu können. Die Hyperglykämie ist eine diabetische\nStoffwechsellage. Daher ist folgendes Beispiel entsprechend zu verschlüsseln:\n•E13.9* Sonstiger näher bezeichneter Diabetes mellitus\nSpezifischer als *Y57.9! Komplikation durch Arzneimittel oder Drogen ist der Kode T88.7\nUnerwünschte Nebenwirkung durch ein indikationsgerechtes Arzneimittel bei\nordnungsgemäßer Verabreichung als Nebendiagnose.","pdfFile":"pdf/2020-07-29_KDE-67_Entscheidung-KDE-67-Hyperglyk&auml;mie,-Cortison.pdf-(43,91-kB).pdf","codes":{"icd":["R73.9","Y57.9","E11","E13.9","T88.7"],"ops":[],"dkr":["1917d"]},"category":"kde"},{"decisionDate":"2020-07-29","publicationDate":"2020-08-19","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-77","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 77 Fieber, postoperativ.pdf (44,7 kB)","sourceURL":"https://www.g-drg.de/content/download/9702/file/Entscheidung%20KDE%2077%20Fieber,%20postoperativ.pdf","keywords":"Entscheidung KDE 77 Fieber, postoperativ.pdf (44,7 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n29.07.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 77:\nEinmalig auftretendes postoperatives Fieber (kontrolliert oder behandelt) ohne Infektion und\nohne anatomisches Korrelat (z. B. Resorptionsfieber) ist mit dem Kode R50.9 Fieber, nicht näher\nbezeichnet zu kodieren. Der Kode T81.4 Infektion nach einem Eingriff, anderenorts nicht\nklassifiziert kann nicht kodiert werden, wenn keine Infektion vorliegt.\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.10.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n19.08.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-77\nSchlagwort: Fieber, postoperativ\nStand: 2007-01-10\nAktualisiert: 30.07.2018\nICD: T81.4; R50.9\nProblem/Erläuterung\nKann als Nebendiagnose T81.4 Infektion nach einem Eingriff, anderenorts nicht klassifiziert\nverschlüsselt werden, wenn nach der Operation kurzfristig postoperatives Fieber (einmalig\nam 3. postoperativen Tag) \"ohne anatomisches Korrelat\" bei \"prophylaktischer\" iv.-\nAntibiose auftritt?\nKodierempfehlung SEG-4\nEs lag ein Symptom (Fieber) vor. Da ein infektiöses Geschehen als Ursache für das Fieber\nnicht nachgewiesen werden konnte, kann T81.4 als postoperative Infektion nicht\nverschlüsselt werden.\nDa eine Temperaturerhöhung postoperativ nichts Ungewöhnliches ist (Resorptionsfieber),\nist sie zunächst nicht als Nebendiagnose zu verschlüsseln, wenn sie sich im üblichen Rahmen\nbewegt.\nFalls postoperatives Fieber (als Symptom) auftritt und die Kriterien einer Nebendiagose\nerfüllt, ist es als Symptom mit R50.9 Fieber, nicht näher bezeichnet zu verschlüsseln, sofern\nnicht tatsächlich eine Infektion nachgewiesen wurde.\nHinweis: Im Jahr 2012 wurde T81.4 aus der CCL-Matrix gestrichen.\nKommentar FoKA\nDissens:\nNur wenn das Fieber während einer laufenden postoperativen prophylaktischen\nAntibiotika-Therapie auftritt, es keine Hinweise auf eine lokalisierte oder generalisierte\nInfektion gibt und das Fieber nur symptomatisch behandelt wird, ist der Sachverhalt mit\ndem Kode R50.9 zu kodieren.\nIn den Fällen, in denen wegen des Fiebers eine antibiotische Behandlung begonnen oder\nmodifiziert wird, ist nach DKR D008b Verdachtsdiagnosen in Abhängigkeit von der operativ\nbehandelten Erkrankung, der Klinik und der Paraklinik die behandelte Verdachtsdiagnose\nzu verschlüsseln.\nDie Diagnose T81.4 zielt lt. Thesaurus in der Regel auf lokalisierte postoperative Infektionen\nab. Ein Erregernachweis ist nicht unabdingbare Voraussetzung.\n(Stand 30.07.2018)\n\nRückmeldung SEG-4\nStand vor 30.07.2018: T81.4 nur, wenn kein spezifischer Kode für die Erkrankung\nvorhanden.","pdfFile":"pdf/2020-07-29_KDE-77_Entscheidung-KDE-77-Fieber,-postoperativ.pdf-(44,7-kB).pdf","codes":{"icd":["R50.9","T81.4"],"ops":[],"dkr":["D008b"]},"category":"kde"},{"decisionDate":"2020-07-29","publicationDate":"2020-07-21","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-202","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 202 Lippenbiopsie.pdf (43,33 kB)","sourceURL":"https://www.g-drg.de/content/download/9703/file/Entscheidung%20KDE%20202%20Lippenbiopsie.pdf","keywords":"Entscheidung KDE 202 Lippenbiopsie.pdf (43,33 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n29.07.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 202:\nEine Lippenbiopsie ohne Inzision ist mit dem Kode 1-420.0 Biopsie ohne Inzision an Mund und\nMundhöhle, Lippe und eine Lippenbiopsie mit Inzision mit dem Kode 1-545.x Biopsie an anderen\nStrukturen des Mundes und der Mundhöhle durch Inzision, Sonstige zu kodieren. Die Inzision\nbezieht sich auf die Art des Zugangs und erfordert eine Freilegung des Biopsiegebietes durch\nInzision. Eine Stichinzision, die ausschließlich der leichteren Einführung einer Biopsienadel dient,\nstellt keine Inzision im Sinne des OPS 1-545.x dar.\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.10.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n19.08.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-202\nSchlagwort: Lippenbiopsie\nStand: 2007-12-18\nAktualisiert: 15.01.2015\nOPS: 1-420.0\nProblem/Erläuterung\nWie wird die Biopsie an der Lippe kodiert? Handelt es sich um eine Biopsie mit Inzision oder\num eine Biopsie ohne Inzision?\nKodierempfehlung SEG-4\nBei der Lippenbiopsie handelt es sich um eine Biopsie ohne Inzision, da sich die Inzision auf\ndie Art des Zuganges bezieht und hier das zu entnehmende Gewebe nicht durch Inzision\nfreigelegt werden muss (1-420.0 Biopsie ohne Inzision an Mund und Mundhöhle, Lippe ).\nKommentar FoKA\nDissens:\nBei Eingriffen, die im OR und mit Anästhesie durchgeführt werden, handelt es sich um\nBiopsien mit Inzisionen. Bei Lippenbiopsien mit Wetzstein-förmiger Umschneidung des\nLippendrüsenareals und späterem Verschluss durch Wundnaht handelt es sich um eine\nintraoperative Biopsie, die gemäß Exklusivum im OPS-Kapitel \"Biopsie ohne Inzision\"\nausgeschlossen ist.\nEs gibt auch noch eine Stellungnahme des DIMDI zu diesem Thema, zur Zeit wird noch auf\ndie Erlaubnis zur Veröffentlichung hier im Wiki gewartet.\nRückmeldung SEG 4\nKein Änderungsbedarf. Die definierten Voraussetzungen (Anästhesie, OR) lassen diese\nSchlussfolgerung nicht zu.","pdfFile":"pdf/2020-07-29_KDE-202_Entscheidung-KDE-202-Lippenbiopsie.pdf-(43,33-kB).pdf","codes":{"icd":[],"ops":["1-420.0","1-545.x"],"dkr":[]},"category":"kde"},{"decisionDate":"2020-07-29","publicationDate":"2020-07-21","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-338","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 338 Tachyarrhythmia absoluta, Vorhofflimmern.pdf (42,69 kB)","sourceURL":"https://www.g-drg.de/content/download/9705/file/Entscheidung%20KDE%20338%20Tachyarrhythmia%20absoluta,%20Vorhofflimmern.pdf","keywords":"Entscheidung KDE 338 Tachyarrhythmia absoluta, Vorhofflimmern.pdf (42,69 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n29.07.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 338:\nEine Tachyarrhythmia absoluta aufgrund von Vorhofflimmern ist mit dem zutreffenden Kode aus\nI48.- Vorhofflimmern und Vorhofflattern zu kodieren. Der Kode I47.1 Supraventrikuläre\nTachykardie ist für die Tachyarrhythmia absoluta bei Vorhofflimmern nicht zusätzlich zu kodieren.\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.10.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n19.08.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-338\nSchlagworte: Tachyarrhythmia absoluta, Vorhofflimmern\nStand: 2010-04-20\nAktualisiert: 2013-01-08\nICD: I48.10; I47.1\nProblem/Erläuterung\nEin Patient wird vom Notarzt wegen neu aufgetretener Tachyarrhythmia absoluta bei\nVorhofflimmern eingewiesen. Es erfolgt eine frequenzregulierende Therapie und der\nPatient wird antikoaguliert. Kann neben der Hauptdiagnose I48.10 Vorhofflattern und\nVorhofflimmern, Vorhofflimmern, paroxysmal I47.1 Paroxysmale Tachykardie,\nSupraventrikuläre Tachykardie zusätzlich als Nebendiagnose kodiert werden?\nKodierempfehlung SEG-4:\nI48.10 Vorhofflattern und Vorhofflimmern, Vorhofflimmern, Paroxysmal ist der spezifische\nKode für die Erkrankung, die normofrequente, tachykarde und/oder bradykarde Phasen\nbeinhaltet. Die Systematik der ICD-10-GM erlaubt auf der 5. Stelle die Differenzierung\nzwischen paroxysmal, chronisch und nicht näher bezeichnet. Die Kodierung von I47.1 als\nNebendiagnose ist nicht begründet.\nFür Fälle ab 2013 ist nach ICD-10-GM die Art des Vorhofflimmerns in paroxysmal,\npersistierend oder permanent zu differenzieren.\nKommentar FoKA:\nDissens (Revision vom 28.01.2013):\nDa die Kriterien zur Kodierung einer Nebendiagnose/eines Symptoms nach den DKR erfüllt\nsind, ist der ICD Kode I47.1 zusätzlich zu verschlüsseln, um die vorliegende normofrequente,\ntachykarde und/oder bradykarde Phase zusätzlich zu beschreiben","pdfFile":"pdf/2020-07-29_KDE-338_Entscheidung-KDE-338-Tachyarrhythmia-absoluta,-Vorhofflimmern.pdf-(42,69-kB).pdf","codes":{"icd":["I48","I47.1","I48.10"],"ops":[],"dkr":[]},"category":"kde"},{"decisionDate":"2020-07-29","publicationDate":"2020-11-11","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-392","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 392 Thrombozytopenie.pdf (44,59 kB)","sourceURL":"https://www.g-drg.de/content/download/9707/file/Entscheidung%20KDE%20392%20Thrombozytopenie.pdf","keywords":"Entscheidung KDE 392 Thrombozytopenie.pdf (44,59 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n29.07.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 392:\nWird eine heparininduzierte Thrombozytopenie bei bekannter HIT II durch prophylaktische Maß-\nnahmen verhindert, ist der Kode Z86.2 Krankheiten des Blutes und der blutbildenden Organe\nsowie bestimmte Störungen mit Beteiligung des Immunsystems in der Eigenanamnese zu kodie-\nren. Der Kode D69.53 Heparin-induzierte Thrombozytopenie Typ II ist nur dann zu kodieren,\nwenn die heparininduzierte Thrombozytopenie tatsächlich auftritt.\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.10.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n19.08.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-392\nSchlagwort: Thrombozytopenie\nStand: 16.06.2011\nAktualisiert: 01.01.2016\nICD: Z86.2; D69.53\nProblem/Erläuterung:\nEin Patient mit Heparin-induzierter Thrombozytopenie Typ II (HIT ll) in der Anamnese\nbedarf einer parenteralen antithrombotischen Prophylaxe. Das Blutbild des Patienten ist\nunauffällig und die Gerinnungsparameter liegen im Normbereich. Die Klinik verabreicht\ndeshalb Orgaran® (Danaparoid-Natrium - Heparinoid). Ist D69.53 S ekundäre\nThrombozytopenie, Heparin-induzierte Thrombozytopenie Typ II als Nebendiagnose zu\nkodieren?\nKodierempfehlung SEG-4:\nZum Zeitpunkt des stationären Aufenthaltes lag keine HIT ll, d.h. keine manifeste\nThrombozytopenie vor. Der Behandlungsaufwand begründet die Kodierung von Z86.2\nKrankheiten des Blutes und der blutbildenden Organe sowie bestimmte Störungen mit\nBeteiligung des Immunsystems in der Eigenanamnese , aber nicht die Kodierung von D69.53.\nKommentierung FoKA:\nDissens:\nWenn von einer anamnestisch gesicherten HIT-II ausgegangen werden kann, so ist diese\nauch spezifisch zu kodieren, da ein spezifischer Ressourcenverbrauch dieser Erkrankung\nzugeordnet werden kann. Die Prädisposition zur Bildung der pathologischen Antikörper\ngegen den Heparin-PF4-Antigen-Komplex ist lebenslang vorhanden, da diese Erkrankung\nwahrscheinlich auf einer genetischen Punktmutation beruht.\nHinweis\n•Eintrag im Labor-Lexikon\n•S3 Leitlinie Prophylaxe der venösen Thromboembolie (VTE)\n•Siehe auch FoKA KDE D-017\nRückmeldung SEG 4\nDie Erkrankung liegt aktuell nicht vor, auch die DKR zur Verdachtsdiagnose greift nicht.\n(27.08.2015)","pdfFile":"pdf/2020-07-29_KDE-392_Entscheidung-KDE-392-Thrombozytopenie.pdf-(44,59-kB).pdf","codes":{"icd":["Z86.2","D69.53"],"ops":[],"dkr":[]},"category":"kde"},{"decisionDate":"2020-07-29","publicationDate":"2020-11-25","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-403","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 403 Intubation, schwierige.pdf (43,34 kB)","sourceURL":"https://www.g-drg.de/content/download/9708/file/Entscheidung%20KDE%20403%20Intubation,%20schwierige.pdf","keywords":"Entscheidung KDE 403 Intubation, schwierige.pdf (43,34 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n29.07.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 403:\nErfolgt bei einer zu erwartenden schwierigen Intubation beispielsweise wegen einer\nSäbelscheidentrachea, Struma oder Adipositas per magna eine primär geplante und\nkomplikationslose fiberoptische Intubation, so ist der Kode T88.4 Misslungene oder schwierige\nIntubation nicht zu kodieren. Diejenigen Erkrankungen/Störungen, die den erschwerten\nIntubationsbedingungen zugrunde liegen, sind zusätzlich zu kodieren (hier\nSäbelscheidentrachea, Struma, Adipositas per magna).\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.10.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n19.08.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-403\nSchlagwort: Intubation, schwierige\nStand: 2011-06-16\nAktualisiert SEG 4: 01.01.2018\nAktualisiert FoKA: 30.07.2018\nICD: J39.80; T88.4\nProblem/Erläuterung:\nBei zu erwartender schwieriger Intubation wegen einer Säbelscheidentrachea mit\ninspiratorischem Stridor und begleitender Adipositas per magna wird zur Struma-Operation\nelektiv eine komplikationslose fiberoptische Intubation der wachen Patientin durchgeführt.\nIst als Nebendiagnose T88.4 Sonstige Komplikationen bei chirurgischen Eingriffen und\nmedizinischer Behandlung, anderenorts nicht klassifiziert , Misslungene oder schwierige\nIntubation zu kodieren?\nKodierempfehlung SEG-4:\nAls Nebendiagnose ist J39.80 S onstige näher bezeichnete Krankheiten der oberen\nAtemwege, Erworbene Stenose der Trachea zu kodieren, da diese Erkrankung die\nNebendiagnosendefinition erfüllt.\nT88.4 Sonstige Komplikationen bei chirurgischen Eingriffen und medizinischer Behandlung,\nandere norts nicht klassifiziert, Misslungene oder schwierige Intubation ist nicht zu\nkodieren, da eine Komplikation bei der primär gewählten fiberoptischen Intubation nicht\neingetreten ist.\nHinweis: Im Jahr 2012 wurde T88.4 aus der CCL-Matrix gestrichen. Siehe auch\nKodierempfehlung 53.\nKommentierung FoKA:\nDissens:\nWir verweisen auf die am 30.07.2018 aktualisierte Kommentierung der KDE-53. (Stand\n30.07.2018)\nRückmeldung SEG 4\nEine schwierige Intubation ist erst dann zu kodieren, wenn sie vorliegt und nicht, wenn sie\nsich durch geeignete Maßnahmen vermeiden lässt. (27.08.2015)","pdfFile":"pdf/2020-07-29_KDE-403_Entscheidung-KDE-403-Intubation,-schwierige.pdf-(43,34-kB).pdf","codes":{"icd":["T88.4","J39.80"],"ops":[],"dkr":[]},"category":"kde"},{"decisionDate":"2020-07-29","publicationDate":"2020-12-16","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-468","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 468 Karpaltunnelsyndrom, Neurolyse, Dekompression.pdf (43,2 kB)","sourceURL":"https://www.g-drg.de/content/download/9709/file/Entscheidung%20KDE%20468%20Karpaltunnelsyndrom,%20Neurolyse,%20Dekompression.pdf","keywords":"Entscheidung KDE 468 Karpaltunnelsyndrom, Neurolyse, Dekompression.pdf (43,2 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n29.07.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 468:\nDie einfache Neurolyse und Dekompression des Nervus medianus mit Durchtrennung des\nRetinaculum flexorum bei Karpaltunnelsyndrom wird mit einem Kode aus 5-056.4 Neurolyse und\nDekompression eines Nerven, Nerven Hand kodiert.\nNach proximal erweiterte Eingriffe über die Beugefalte am Handgelenk hinaus mit\nDekompression des Nervus medianus am Unterarm werden zusätzlich mit dem Kode 5-056.3\nNeurolyse und Dekompression eines Nerven, Nerven Arm kodiert.\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.10.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n19.08.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-468\nSchlagwort: Karpaltunnelsyndrom, Neurolyse, Dekompression\nStand: 2013-01-08\nAktualisiert: 12.06.2017\nOPS: 5-056.4; 5-056.3; 5-85\nProblem/Erläuterung:\nAufnahme zur Durchführung einer Neurolyse bei Karpaltunnelsyndrom. Ist zusätzlich zu\neinem OPS-Kode aus 5-056.4 Neurolyse und Dekompression eines Nerven, Nerven Hand der\nOPS Kode 5-056.3 Neurolyse und Dekompression eines Nerven, Nerven Arm kodierbar?\nKodierempfehlung SEG-4:\nNur ein OPS-Kode aus 5-056.4 Neurolyse und Dekompression eines Nerven, Nerven Hand ist\nzu verwenden. Auch das Alphabetische Verzeichnis des OPS führt unter den Suchbegriffen\n\"Karpaltunnel\", \"Dekompression und Neurolyse\" zum OPS-Kode 5-056.4. Die\nDekompression des N. medianus erfordert bei Vorliegen eines Karpaltunnelsyndroms in der\nRegel die Präparation bis in den Bereich des proximalen Handgelenks. Das Alphabetische\nVerzeichnis verweist ausschließlich auf die Operation an der Hand. Hinweise bezüglich einer\nanatomischen Grenzziehung \"Hand/proximales Handgelenk\" finden sich zu diesem Kode\nnicht, sondern nur bei anderen OPS-Kodes, z.B. bei 5-85 Operationen an Muskeln, Sehnen,\nFaszien und Schleimbeuteln .\nKommentierung FoKA:\nDissens:\nEs muss gemäß durchgeführter Operation (d.h. Lokalisation der durchgeführten Neurolyse)\ngenau verschlüsselt werden, d.h. es kann auch ein Eingriff an Hand und Arm notwendig\nsein (siehe auch \"S3-Leitlinie Diagnostik und Therapie des Karpaltunnelsyndroms \").\n(Aktualisiert: 12.06.2017)\nRückmeldung SEG 4\nAus der Kommentierung ist kein Dissens ableitbar. (27.08.2015)","pdfFile":"pdf/2020-07-29_KDE-468_Entscheidung-KDE-468-Karpaltunnelsyndrom,-Neurolyse,-Dekompression.pdf-(43,2-kB).pdf","codes":{"icd":[],"ops":["5-056.4","5-056.3","5-85"],"dkr":[]},"category":"kde"},{"decisionDate":"2020-07-29","publicationDate":"2020-08-19","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-493","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 493 Bronchialschleimhaut, Biopsie, Blutstillung.pdf (42,22 kB)","sourceURL":"https://www.g-drg.de/content/download/9710/file/Entscheidung%20KDE%20493%20Bronchialschleimhaut,%20Biopsie,%20Blutstillung.pdf","keywords":"Entscheidung KDE 493 Bronchialschleimhaut, Biopsie, Blutstillung.pdf (42,22 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n29.07.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 493:\nErfolgt in einer, im Rahmen einer Bronchoskopie durchgeführten Biopsie aus der\nBronchialschleimhaut, eine Blutstillung mittels Adrenalinlösung, so ist diese in den Kodes aus\n1-430.1- Endoskopische Biopsie an respiratorischen Organen, Bronchus enthalten.\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.10.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n19.08.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-493\nSchlagworte: Bronchialschleimhaut, Biopsie, Blutstillung\nStand: 20.08.2013\nAktualisiert: 12.06.2017\nOPS: 1.430.1\nProblem/Erläuterung\nIm Rahmen einer Bronchoskopie wird eine Biopsie aus der Bronchialschleimhaut\nentnommen. Bei der abschließenden Inspektion zeigt sich eine Sickerblutung an der\nBiopsiestelle. Diese wird mittels Adrenalinlösung gestillt. Ist in diesem Fall die Blutstillung\ngesondert zu kodieren?\nKodierempfehlung SEG-4:\nDie Biopsie der Bronchialschleimhaut ist mit dem OPS-Kode 1-430.1 Endoskopische Biopsie\nan respiratorischen Organen, Bronchus zu verschlüsseln. Dies beinhaltet gemäß DKR P001,\nAbschnitt Prozedurenkomponenten, die dabei notwendigen Maßnahmen zur Blutstillung.\nDiese ist somit nicht zusätzlich zu kodieren.\nKommentierung FoKA:\nDissens\nIm Regelfall sistieren kapillare Sickerblutungen spontan. Erfordert eine anhaltende\nSickerblutung im Sinne einer Komplikation eine Intervention, ist diese gemäß DKR P003\ngesondert zu kodieren.\nVgl. auch KDE-571\n(Aktualisiert: 12.06.2017)\nRückmeldung SEG 4\nDie Blutstillung im vorliegenden Fall ist keine Versorgung einer Komplikation, sondern\nProzedurenkomponente. (27.08.2015)","pdfFile":"pdf/2020-07-29_KDE-493_Entscheidung-KDE-493-Bronchialschleimhaut,-Biopsie,-Blutstillung.pdf-(42,22-kB).pdf","codes":{"icd":[],"ops":["1-430.1"],"dkr":["P001","P003"]},"category":"kde"},{"decisionDate":"2020-07-29","publicationDate":"2020-08-19","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-513","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 513 Reflux&ouml;sophagitis, GERD (Gastroesophageal reflux disease).pdf (44,43 kB)","sourceURL":"https://www.g-drg.de/content/download/9712/file/Entscheidung%20KDE%20513%20Reflux%C3%B6sophagitis,%20GERD%20%28Gastroesophageal%20reflux%20disease%29.pdf","keywords":"Entscheidung KDE 513 Reflux&ouml;sophagitis, GERD (Gastroesophageal reflux disease).pdf (44,43 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n29.07.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 513:\nDas Stadium IV einer Gastroösophagealen Refluxkrankheit (GERD) ist mit einem Kode aus\nK21.- Gastroösophageale Refluxkrankheit und den im Einzelfall zutreffenden Kodes für die\nKomplikationen, z. B. K22.1 Ösophagusulkus, K22.2 Ösophagusverschluss, K22.7 Barrett-\nÖsophagus, K22.81 Ösophagusblutung zu kodieren.\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.10.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n19.08.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-513\nSchlagworte: Refluxösophagitis, GERD (Gastroesophageal reflux disease)\nErstellt: 15.01.2014\nAktualisiert: 01.01.2016\nDRG: K20; K21.0\nProblem/Erläuterung\nStationäre Aufnahme wegen retrosternalem Brennen und rezidivierendem Brechreiz.\nGastroskopisch Nachweis einer Hiatusgleithernie mit ausgeprägter Refluxösophagitis\nStadium IV mit mehreren cardianahen Ulcera, jedoch ohne Blutungszeichen. Wie ist die\nRefluxösophagitis Stadium IV zu kodieren?\nKodierempfehlung SEG-4:\nK21.0 Gastroösophageale Refluxkrankheit mit Ösophagitis . Das Systematische Verzeichnis\nder ICD-10-GM unterscheidet zwischen peptischem Ulcus und refluxbedingtem Ulcus (siehe\nhierzu Exklusivum zur Schlüsselnummer K20 Ösophagitis ). Für die gastroösophageale\nRefluxkrankheit steht eine eigene Kategorie in der ICD-10-GM zur Verfügung. Über die 4.\nStelle ist hierbei eine Differenzierung der Refluxkrankheit mit oder ohne Ösophagitis\nmöglich. Das Stadium der Refluxösophagitis kann jedoch derzeit nicht über eine zusätzliche\nSchlüsselnummer abgebildet werden.\nKommentierung FoKA:\nDissens:\nDas Stadium IV der Refluxösophagitis nach Savary-Miller bezeichnet eine Vielzahl an\nKomplikationen und Folgeerkrankungen der GERD. Unter anderem sind zu nennen:\nChronische Veränderungen (Ulkus) mit Narbenbildung, Wandfibrose, Stenose, Barrett-\nÖsophagus. Leitlinie der DGVS. Nach Herold wird das Stadium IV auch als\nKomplikationsstadium bezeichnet mit Vorkommen von Ulzerationen, Strikturen/Stenosen,\nBarrett-Ösophagus (s.o.). Dabei erfolgt eine Differenzierung in IVA: Mit entzündlichen\nVeränderungen und IVB: Irreversibles Narbenstadium ohne entzündliche Veränderungen.\nEine Mehrfachkodierung ist deshalb bei dem beschriebenen Befund zur vollständigen\nAbbildung erforderlich. Die Schleimhautentzündung entspricht nicht unmittelbar einer\nUlzeration und andersherum ist das Ulkus nicht isolierte Manifestation der Ösophagitis. Die\nICD-Kodes K22.1 und K21.0 schließen sich nicht durch Exklusiva im systematischen\nVerzeichnis der ICD-10-GM gegenseitig aus. (27.01.2014)\nRückmeldung SEG 4\nGrundsätzlicher Dissens. (27.08.2015)","pdfFile":"pdf/2020-07-29_KDE-513_Entscheidung-KDE-513-Reflux&ouml;sophagitis,-GERD-(Gastroesophageal-reflux-disease).pdf-(44,43-kB).pdf","codes":{"icd":["K21","K22.1","K22.2","K22.7","K22.81","K20","K21.0"],"ops":[],"dkr":[]},"category":"kde"},{"decisionDate":"2020-07-29","publicationDate":"2020-10-15","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-545","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 545 Aufwandspunkte, Metastasen, OPS 8-980.pdf (135,01 kB)","sourceURL":"https://www.g-drg.de/content/download/9717/file/Entscheidung%20KDE%20545%20Aufwandspunkte,%20Metastasen,%20OPS%208-980.pdf","keywords":"Entscheidung KDE 545 Aufwandspunkte, Metastasen, OPS 8-980.pdf (135,01 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n29.07.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 545:\nSind Metastasen gemäß den Deutschen Kodierrichtlinien entweder als Haupt- oder als\nNebendiagnose zu kodieren, sind sie für die Ermittlung der SAPS-Punkte bei der Kodierung der\nintensivmedizinischen Komplexbehandlung unter der Kategorie „Chronische Leiden,\nmetastasierende Neoplasie“ entsprechend den „Dokumentationsvorgaben zur Erfassung der\nIntensivmedizinischen Komplexbehandlung“ des BfArM zu berücksichtigen.\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.10.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n19.08.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-545\nSchlagworte: Aufwandspunkte, Metastasen, OPS 8-980\nErstellt: 24.06.2015\nAktualisiert:\nOPS: 8-980\nProblem/Erläuterung\nFür die Berechnung der Aufwandspunkte im Rahmen der intensivmedizinischen\nKomplexbehandlung (8-980) werden für die „Neoplasie mit Metastase“ täglich Punkte\nberücksichtigt. Gilt dies auch, wenn im Einzelfall Metastasen nach den Regelungen der DKR\nnicht zu kodieren sind?\nKodierempfehlung SEG-4:\nMetastasen können für die Berechnung der Aufwandspunkte nach den TISS und SAPS II-\nScores nur berücksichtigt werden, wenn sie nach den Regelungen der DKR korrekt kodiert\nsind. Diese Feststellung ergibt sich aus dem Wortlaut der Fußnote 3 der\n„Dokumentationsvorgaben zur Erfassung der Intensivmedizinischen Komplexbehandlung“\ndes DIMDI. Hiernach \"muss ein entsprechender ICD-10-GM Kode als Haupt- oder\nNebendiagnose kodiert sein\".\nKommentierung FoKA:\nDissens (Stand 15.09.2015):\nIn den „Dokumentationsvorgaben zur Erfassung der Intensivmedizinischen\nKomplexbehandlung“ des DIMDI wird der Begriff der metastasierenden Neoplasie als\n\"selbsterklärend\" charakterisiert. Dabei entstammt dieser Ausdruck einem Scoringsystem,\ndas die Erkrankungsschwere intensivmedizinischer Patienten bewertet, ohne Bezug zu den\nKodierrichtlinien. Bei der Entwicklung des Scores wurde eine höhere Mortalität bei den\nPatienten gefunden, die Metastasen ausgebildet haben. In der Fußnote 3 wird gefordert,\nein \"Entsprechender ICD-10-GM Code (Version 2005) muss als Haupt- oder Nebendiagnose\nkodiert sein\". Somit reicht der klinische Nachweis, dass die Neubildung zu Metastasen\ngeführt hat. Die Neubildung selbst muss kodiert sein. Aus dem Wortlaut ist nicht\nabzuleiten, dass die Metastasen ebenfalls kodiert sein müssen.\n(Stand: 18.01.2016)\nRückmeldung SEG 4\nDie Dokumentationsvorgaben regeln nicht die Verschlüsselung von Primärtumor und\nMetastasen. (17.12.2015)","pdfFile":"pdf/2020-07-29_KDE-545_Entscheidung-KDE-545-Aufwandspunkte,-Metastasen,-OPS-8-980.pdf-(135,01-kB).pdf","codes":{"icd":[],"ops":["8-980"],"dkr":[]},"category":"kde"},{"decisionDate":"2020-07-29","publicationDate":"2020-11-25","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-588","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 588 Heimbeatmung, Optimierung der Beatmung, Beatmungsstunden, Intensivstation.pdf (220,2 kB)","sourceURL":"https://www.g-drg.de/content/download/9718/file/Entscheidung%20KDE%20588%20Heimbeatmung,%20Optimierung%20der%20Beatmung,%20Beatmungsstunden,%20Intensivstation.pdf","keywords":"Entscheidung KDE 588 Heimbeatmung, Optimierung der Beatmung, Beatmungsstunden, Intensivstation.pdf (220,2 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n29.07.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 588:\nBei heimbeatmeten Patienten, die ausschließlich zur Kontrolle und Optimierung einer früher\neingeleiteten noninvasiven häuslichen maschinellen Beatmung stationär behandelt werden, sind\ndie Beatmungszeiten nur dann zu erfassen, wenn es sich im Einzelfall um einen\n„intensivmedizinisch versorgten Patienten“ handelt. Die Definition der intensivmedizinischen\nVersorgung richtet sich nach der DKR 1001 Maschinelle Beatmung.\nDer intensivmedizinisch versorgte Patient ist dort wie folgt definiert:\n„Beatmungsstunden sind nur bei „intensivmedizinisch versorgten“ Patienten zu kodieren, das\nheißt bei Patienten, bei denen die für das Leben notwendigen sogenannten vitalen oder\nelementaren Funktionen von Kreislauf, Atmung, Homöostase oder Stoffwechsel lebensgefährlich\nbedroht oder gestört sind und die mit dem Ziel behandelt, überwacht und gepflegt werden, diese\nFunktionen zu erhalten, wiederherzustellen oder zu ersetzen, um Zeit für die Behandlung des\nGrundleidens zu gewinnen. Das Grundleiden, das die intensivmedizinische Behandlung bedingt\nhat, muss in diesem Zusammenhang nicht mit der Hauptdiagnose identisch sein.\nDiese intensivmedizinische Versorgung umfasst mindestens ein Monitoring von Atmung und\nKreislauf und eine akute Behandlungsbereitschaft (ärztliche und pflegerische Interventionen zur\nStabilisierung der Vitalfunktionen unmittelbar möglich).“\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.10.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n19.08.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-588\nIntensivstation\nErstellt: 04.12.2017\nStand: 22.01.2018\nSchlagwort: Heimbeatmung, Optimierung der Beatmung, Beatmungsstunden,\nProblem/Erläuterung:\nStationäre Aufnahme eines Patienten elektiv für drei Behandlungstage ausschließlich zur\nKontrolle und Optimierung einer früher eingeleiteten noninvasiven häuslichen\nmaschinellen Beatmung bei chronischer respiratorischer Insuffizienz.\nDie Anpassung der maschinellen Beatmung erfolgt auf der Intensivstation.\nSind neben dem OPS\n8-716.10 Kontrolle oder Optimierung einer früher eingeleiteten nicht invasiven h äuslichen\nmaschinellen Beatmung auch die Beatmungsstunden zu erfassen?\nKodierempfehlung SEG-4:\nDie Beatmungsstunden sind nicht auszuweisen. Gemäß DKR 1001 sind Beatmungszeiten nur\nzu erfassen, wenn es sich im Einzelfall um einen \"intensivmedizinisch versorgten Patienten\"\nhandelt. In diesem Fall war der Patient weder intensivmedizinisch behandlungsbedürftig\nnoch intensivmedizinisch versorgt.\nSiehe auch Kodierempfehlungen Nr. 75 und 146.\nKommentar FoKA\nDissens (22.01.2018):\nAus der Beschreibung, dass der Patient von zu Hause aufgenommen wurde, lässt sich nicht\nerkennen, wie der Patient zu Hause versorgt wurde und welche Versorgungsintensität im\nKrankenhaus erforderlich war.\nDer FoKA empfiehlt zur Bewertung des Einzelfalls die Nutzung etablierter Scoring-\nSysteme als Bewertungsmaßstab. Die gebräuchlichsten Scoringsysteme sind der TISS28 und\nder Frühreha-Barthelindex.\nBeim TISS28 ist ab 10 Punkten von einer Intensivüberwachung, ab 16 Punkten von einer\nIntermediate-Care Versorgung und ab 23 Punkten von einer intensivmedizinischen\nVersorgung auszugehen:\n TISS28 unter 10 Punkten - keine intensivmedizinische Versorgung\n TISS28 10 - 22 Punkte - zusätzliche Einbeziehung des FR-BI\n TISS28 mehr als 22 - unstrittige intensivmedizinische Versorgung.\nDer Frühreha-Barthel-Index ist in Fällen mit 10-22 TISS28-Punkten einzubeziehen, da\ndieser bei weniger als 30 Punkte laut Bundesarbeitsgemeinschaft Rehabilitation eine\nintensivmedizinische Struktur für die Versorgung der Patienten erforderlich macht.","pdfFile":"pdf/2020-07-29_KDE-588_Entscheidung-KDE-588-Heimbeatmung,-Optimierung-der-Beatmung,-Beatmungsstunden,-Intensivstation.pdf-(.pdf","codes":{"icd":[],"ops":["8-716.10"],"dkr":[]},"category":"kde"},{"decisionDate":"2020-07-29","publicationDate":"2020-11-25","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-598","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 598 Komplikationen nach medizinischen Ma&szlig;nahmen.pdf (46,6 kB)","sourceURL":"https://www.g-drg.de/content/download/9719/file/Entscheidung%20KDE%20598%20Komplikationen%20nach%20medizinischen%20Ma%C3%9Fnahmen.pdf","keywords":"Entscheidung KDE 598 Komplikationen nach medizinischen Ma&szlig;nahmen.pdf (46,6 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n29.07.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 598:\nEntwickelt sich bei einem Patienten mit Zustand nach Nierentransplantation eine Verschlechterung in\nBezug auf die transplantierte Niere (T86.10 Akute Funktionsverschlechterung eines Nierentransplan-\ntates) kann neben dem spezifischen Kode für die Verschlechterung der transplantierten Niere auch\nder Kode Z94.0 Zustand nach Nierentransplantation kodiert werden.\nGültigkeit:\nDie Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser, die\nKrankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.10.2020 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n19.08.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-598\nSchlagwort: Komplikationen nach medizinischen Maßnahmen\nErstellt: 26.06.2019\nStand: 10.09.2019\nProblem/Erläuterung:\nFall 1:\nAufnahme wegen einer Sepsis / SIRS, antibiotische Therapie. Im Rahmen der Sepsis kam\nes zu einem akuten oligurischen Transplantatversagen bei Z. n. Nierentransplantation.\nIntensivmedizinische Therapie und kurzfristig Einsatz von Nierenersatzverfahren. Als\nNebendiagnose wird T86.10 Akute Funktionsverschlechterung eines Nierentransplantates\nkodiert.\nDarf zusätzlich der Kode\nZ94.0 Zustand nach Nierentransplantation\nals Nebendiagnose angegeben werden?\nFall 2:\nAufnahme wegen einer Thrombose im Bereich eines intrakorporalen\nHerzunterstützungssystems. Intensivmedizinische Therapie, Antikoagulation. Als\nHauptdiagnose wird T82.8 Sonstige näher bezeichnete Komplikation durch Prothesen,\nImplantate und Transplantate im Herzen und in den Gefäßen kodiert.\nDarf zusätzlich der Kode\nZ95.80 Vorhandensein eines herzunterstützenden Systems\nals Nebendiagnose angegeben werden?\nKodierempfehlung SEG-4:\nZu Fall 1:\nDer Kode Z94.0 Zustand nach Nierentransplantation ist nicht als Nebendiagnose\nanzugeben. Die Schlüsselnummer T86.10 beinhaltet bereits den Zustand nach\nNierentransplantation. Folgerichtig weist das Exklusivum unter Z94.- auf keinen anderen\nKode hin.\nZu Fall 2:\nDie zusätzliche Kodierung von Z95.80 ist korrekt. Beide Kodes können nebeneinander\nverwendet werden, da die Erkrankungen/Zustände sowohl als auch beim Patienten\nvorliegen (siehe auch beim DIMDI Kodierfrage zu ICD-10-GM Nr. 1008) und auch das\nPatientenmanagement beeinflusst haben.\n\nKommentar FoKA\nDissens:\nDas Exklusivum bei Z94.0 besagt lediglich, dass ein Organversagen oder eine\nFunktionsverschlechterung nicht im Kode für den Zustand nach Nierentransplantation\nenthalten ist. Da ein vergleichbares Exklusivum unter dem Kode T86.10 nicht enthalten ist,\nschließt der Kode T86.10 die zusätzliche Kodierung des Kodes Z94.0 nicht aus. Der\nRessourcenverbrauch für beide Diagnosen ist voneinander abgrenzbar\n(Nierenersatzverfahren und immunsupressive Dauertherapie). Den Begriff der\nmonokausalen Verschlüsselung gibt es nicht für Diagnosen, sondern nur für Prozeduren.\nKonsens zu Fall 2.\n(Stand 10.09.2019)","pdfFile":"pdf/2020-07-29_KDE-598_Entscheidung-KDE-598-Komplikationen-nach-medizinischen-Ma&szlig;nahmen.pdf-(46,6-kB).pdf","codes":{"icd":["T86.10","Z94.0","T82.8","Z95.80","Z94"],"ops":[],"dkr":[]},"category":"kde"},{"decisionDate":"2020-09-18","publicationDate":"2020-10-15","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-39","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 39 Tachyarrhythmie, Hyperthyreose, Vorhofflimmern.pdf (143,7 kB)","sourceURL":"https://www.g-drg.de/content/download/9809/file/Entscheidung%20KDE%2039%20Tachyarrhythmie,%20Hyperthyreose,%20Vorhofflimmern.pdf","keywords":"Entscheidung KDE 39 Tachyarrhythmie, Hyperthyreose, Vorhofflimmern.pdf (143,7 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n18.09.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des PKV-Verbandes\nwie folgt entschieden:\nEntscheidung KDE 39:\nIn dem beschriebenen Fall (KDE-39), bei dem der Patient wegen einer Tachyarrhythmia absoluta\nbei neu aufgetretenem Vorhofflimmern notfallmäßig eingewiesen, medikamentös behandelt und\nkardiologisch abgeklärt wurde und zudem im Routinelabor am Aufnahmetag eine Hyperthyreose\nfestgestellt und mit Thyreostatika behandelt wurde, ist für die Auswahl der Hauptdiagnose der\nAbschnitt „Zwei oder mehr Diagnosen, die gleichermaßen der Definition der Hauptdiagnose\nentsprechen“ aus der DKR D002 Hauptdiagnose anzuwenden.\nDemnach gilt:\n„Zwei oder mehr Diagnosen, die gleichermaßen der Definition der Hauptdiagnose\nentsprechen\nWenn zwei oder mehrere Diagnosen in Bezug zu Aufnahme, Untersuchungsbefunden und/oder\nder durchgeführten Therapie gleichermaßen die Kriterien für die Hauptdiagnose erfüllen und\nICD-10-Verzeichnisse und Kodierrichtlinien keine Verschlüsselungsanweisungen geben, muss\nvom behandelnden Arzt entschieden werden, welche Diagnose am besten der Hauptdiagnose-\nDefinition entspricht. Nur in diesem Fall ist vom behandelnden Arzt diejenige auszuwählen, die\nfür Untersuchung und/oder Behandlung die meisten Ressourcen verbraucht hat. Hierbei ist es\nunerheblich, ob die Krankheiten verwandt sind oder nicht.“\nDie Hauptdiagnose ist danach abhängig vom Ressourcenverbrauch zu kodieren, welcher sich\njedoch an Hand der hier zum Sachverhalt vorliegenden Informationen allein nicht abschließend\nsicher bestimmen lässt.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n\n01.12.2020 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 06.10.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-39\nSchlagwort: Tachyarrhythmie, Hyperthyreose, Vorhofflimmern\nErstellt: 28.02.2006\nAktualisiert: 11.12.2019\nProblem/Erläuterung:\nEin Patient wird vom Notarzt wegen Tachyarrhythmia absoluta bei neu aufgetretenem\nVorhofflimmern eingewiesen. Unter Monitorkontrolle wird diese medikamentös behandelt\nund eine kardiologische Diagnostik durchgeführt. Im Routinelabor wird am Aufnahmetag\neine Hyperthyreose festgestellt und die Behandlung mit Thyreostatika begonnen. Was ist\nHauptdiagnose bzw. Nebendiagnose und warum?\nKodierempfehlung SEG 4:\nDas Vorhofflimmern ist als Hauptdiagnose zu verschlüsseln, da dies Anlass für die\nAufnahme ins Krankenhaus war. Die Hyperthyreose ist als Nebendiagnose zu verschlüsseln.\nKommentar FoKA:\nDissens:\n\"Die nach Analyse festgestellte Hauptdiagnose muss nicht der Aufnahmediagnose oder\nEinweisungsdiagnose entsprechen.\" (D002f)\nDie Tachyarrhythmie bei Vorhofflimmern ist einerseits ein eigenständiges Krankheitsbild\nund anderseits in diesem Fall das Symptom der zugrunde liegenden Erkrankung\nHyperthyreose. Beide Erkrankungen lagen zum Zeitpunkt der stationären Aufnahme vor,\nwurden diagnostiziert und therapiert.\nSomit ist es unter Beachtung der DKR bei konkurrierenden Diagnosen möglich, in\nAbhängigkeit vom Behandlungsaufwand sowohl das Vorhofflimmern als auch die\nHyperthyreose als Hauptdiagnose auszuwählen. Das Fallbeispiel erlaubt keine Rückschlüsse\nauf den gesamten Behandlungsaufwand für jede der beiden möglichen Hauptdiagnosen.\n\n\"Wenn zwei oder mehrere Diagnosen in Bezug zu Aufnahme, Untersuchungsbefunden\nund/oder der durchgeführten Therapie gleichermaßen die Kriterien für die Hauptdiagnose\nerfüllen und ICD-10-Verzeichnisse und Kodierrichtlinien keine Verschlüsselungsanweisungen\ngeben, muss vom behandelnden Arzt entschieden werden, welche Diagnose am besten der\nHauptdiagnose-Definition entspricht. Nur in diesem Fall ist vom behandelnden Arzt\ndiejenige auszuwählen, die für Untersuchung und/oder Behandlung die meisten Ressourcen\nverbraucht hat. Hierbei ist es unerheblich, ob die Krankheiten verwandt sind oder nicht.\"\n(D002f)\nFür die Festlegung der Hyperthyreose als Hauptdiagnose spricht auch die Regelung: \"Wenn\nsich ein Patient mit einem Symptom vorstellt und die zugrunde liegende Krankheit zum\nZeitpunkt der Aufnahme bekannt ist und behandelt wird bzw. während des\nKrankenhausaufenthaltes diagnostiziert wird, so ist die zugrunde liegende Krankheit als\nHauptdiagnose zu kodieren\" (D002f).","pdfFile":"pdf/2020-09-18_KDE-39_Entscheidung-KDE-39-Tachyarrhythmie,-Hyperthyreose,-Vorhofflimmern.pdf-(143,7-kB).pdf","codes":{"icd":[],"ops":[],"dkr":["D002","D002f"]},"category":"kde"},{"decisionDate":"2020-09-18","publicationDate":"2020-07-21","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-109","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 109 Antikoagulation, Thromboembolieprophylaxe, Marcumar, Heparin.pdf (222,23 kB)","sourceURL":"https://www.g-drg.de/content/download/9810/file/Entscheidung%20KDE%20109%20Antikoagulation,%20Thromboembolieprophylaxe,%20Marcumar,%20Heparin.pdf","keywords":"Entscheidung KDE 109 Antikoagulation, Thromboembolieprophylaxe, Marcumar, Heparin.pdf (222,23 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n18.09.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 109:\nEin stationärer Aufenthalt eines antikoagulierten Patienten zum Zwecke einer Vollheparinisierung\nvor einer geplanten zahnärztlichen Behandlung (KDE-109) ist unter anderem mit folgenden\nKodes zu kodieren:\n- Z51.4 Vorbereitung auf eine nachfolgende Behandlung, anderenorts nicht klassifiziert\n(Hauptdiagnose)\n- Z29.9 Prophylaktische Maßnahme, nicht näher bezeichnet (Nebendiagnose)\n- Z92.1 Dauertherapie (gegenwärtig) mit Antikoagulanzien in der Eigenanamnese\n(Nebendiagnose)\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.12.2020 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 06.10.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-109\nSchlagwort: Antikoagulation, Thromboembolieprophylaxe, Marcumar, Heparin\nStand: 2007-01-10\nAktualisiert: 01.01.2019\nICD: Z51.88\nProblem/Erläuterung:\nDer Versicherte stellte sich planmäßig in der gefäßchirurgischen Sprechstunde zur Kontrolle\nnach Bypass-Operation bei pAVK rechts vor. Zudem Z.n. Mitral- und Aortenklappenersatz\n(mechanisch). Im Hinblick auf eine geplante zahnärztliche Behandlung war ambulant\nMarcumar abgesetzt und durch Gabe eines niedermolekularen Heparins ersetzt worden.\nAktuell kritischer Abfall der INR. Notfallmäßige stationäre Einweisung zur\nVollheparinisierung. Was ist Hauptdiagnose?\nKodierempfehlung SEG-4:\nHauptdiagnose ist Z51.88 Sonstige näher bezeichnete medizinische Behandlung . Grund der\nAufnahme ist die Thromboembolieprophylaxe im Hinblick auf das Risiko\nthromboembolischer Komplikationen bei mechanischem Herzklappenersatz\nKommentar FoKA:\nDissens:\nGemäß einer möglichst spezifischen Kodierung ist T88.8 Sonstige Komplikationen bei\nchirurgischen Eingriffen und medizinischer Behandlung, anderenorts nicht klassifiziert zu\nbenutzen.\nRückmeldung SEG-4:\nEs handelt sich nicht um eine Komplikation, sondern um die Umstellung der Prophylaxe.","pdfFile":"pdf/2020-09-18_KDE-109_Entscheidung-KDE-109-Antikoagulation,-Thromboembolieprophylaxe,-Marcumar,-Heparin.pdf-(222,23-kB).pdf","codes":{"icd":["Z51.4","Z29.9","Z92.1","Z51.88","T88.8"],"ops":[],"dkr":[]},"category":"kde"},{"decisionDate":"2020-09-18","publicationDate":"2020-12-16","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-134","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 134 Rektumkarzinom, Enterokolitis, Malignom, Hauptdiagnose.pdf (217,53 kB)","sourceURL":"https://www.g-drg.de/content/download/9811/file/Entscheidung%20KDE%20134%20Rektumkarzinom,%20Enterokolitis,%20Malignom,%20Hauptdiagnose.pdf","keywords":"Entscheidung KDE 134 Rektumkarzinom, Enterokolitis, Malignom, Hauptdiagnose.pdf (217,53 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n18.09.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des PKV-Verbandes\nwie folgt entschieden:\nEntscheidung KDE 134:\nIn dem beschriebenen Fall des Patienten (KDE-134) mit Rektumkarzinom, Z.n. Operation und\nRadiochemotherapie, ambulanter Durchführung einer palliativen Chemotherapie mit FUFOX (5\nFU, Folinsäure und Oxaliplatin), der drei Tage nach der Chemotherapie mit einer massiven\nEnterokolitis als Nebenwirkung auf die Chemotherapie aufgenommen und symptomatisch mit\nparenteraler Ernährung, prophylaktischer Antibiotika- und Antiemetikagabe sowie\nSchmerzmedikation bei Hüftschmerzen und Transfusion von zwei Erythrozytenkonzentraten bei\nTumoranämie behandelt wird und bei dem zusätzlich ein MRT der Hüfte bei Verdacht auf\nMetastase durchgeführt wird, welche sich nicht bestätigte, ist für die Auswahl der Hauptdiagnose\nder Beschluss des Schlichtungsausschusses Bund alter Fassung vom 04.07.2016 anzuwenden.\nDemnach gilt:\n„Wird bei einem Patienten – mit zum Zeitpunkt der Aufnahme bekanntem Malignom und bevor\ndie Malignom-Behandlung endgültig abgeschlossen ist – während des stationären Aufenthaltes\nausschließlich eine einzelne Erkrankung (oder Komplikation) als Folge einer Tumortherapie oder\neines Tumors behandelt, wird in diesem Fall die behandelte Erkrankung als Hauptdiagnose\nangegeben und der Tumor als Nebendiagnose.\nHiervon ausgenommen sind solche Fälle, bei denen weitere diagnostische oder therapeutische\nMaßnahmen in direktem Zusammenhang mit der Tumorerkrankung durchgeführt werden.“\nIn dem beschriebenen Fall ist das Rektumkarzinom mit dem Kode C20 Bösartige Neubildung des\nRektums als Hauptdiagnose zu kodieren.\n\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.12.2020 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 06.10.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-134\nSchlagwort: Rektumkarzinom, Enterokolitis, Malignom, Hauptdiagnose\nStand: 26.06.2007\nAktualisiert: 01.01.2019\nICD: K52.1; Y57.9!\nProblem/Erläuterung:\nPatient mit einem Rektumkarzinom, Z.n. Operation und Radiochemotherapie. Ambulante\nDurchführung einer palliativen Chemotherapie mit FUFOX (5 FU, Folinsäure und\nOxaliplatin). Aufnahme drei Tage nach der Chemotherapie mit einer massiven Enterokolitis\nals Nebenwirkung der Chemotherapie. Symptomatische Therapie mit parenteraler\nErnährung, prophylaktisch Antibiotika und Antiemetika. Schmerzmedikation wegen\nSchmerzen in der Hüfte. Transfusion von zwei Erythrozytenkonzentraten bei Tumoranämie.\nMRT der Hüfte bei Verdacht auf Metastase, die sich nicht bestätigte. Was ist\nHauptdiagnose?\nKodierempfehlung SEG-4:\nBis zum Beschluss des Schlichtungsausschusses Bund gemäß § 17c Abs. 3 KHG\n– Aktenzeichen 01/2015 – gilt:\nDie stationäre Aufnahme erfolgte wegen der Enterokolitis nach Chemotherapie und wird\nnach DKR 0211d (\"War der Aufnahmegrund weder die maligne Erkrankung noch die\nChemotherapie, so ist die Hauptdiagnose gemäß DKR D002 Hauptdiagnose zu wählen\") mit\nK52.1 Toxische Gastroenteritis und Kolitis angegeben. Zur weiteren Spezifizierung kann als\n\nNebendiagnose Y57.9! Komplikationen durch Arzneimittel oder Drogen hinzu kodiert\nwerden.\nAb dem Beschluss des Schlichtungsausschusses Bund gemäß § 17c Abs. 3 KHG\n– Aktenzeichen 01/2015 – gilt:\nDie stationäre Aufnahme erfolgte wegen der Enterokolitis nach Chemotherapie, die\nbehandelt wurde. Da weitere diagnostische und therapeutische Maßnahmen in direktem\nZusammenhang mit der Tumorerkrankung durchgeführt wurden, ist in diesem Fall C20\nBösartige Neubildung des Rektums als Hauptdiagnose anzugeben.\nSiehe auch KDE-476.\nKommentar FoKA:\nAktualisiert am 11.02.2009:\nDissens:\nEin T-Kode ist bezüglich der genaueren Kodierung dem Y-Kode vorzuziehen. Die DKR\n0211d war nur bis zum Jahr 2007 gültig.\nAktuell verweisen wir auf unseren Kommentar zur KDE-273.\nRückmeldung SEG-4:\nKein Änderungsbedarf. Zur DKR 0211d: Die SEG 4-Empfehlung wurde der\nWeiterentwicklung der DKR angepasst. Zur Kodierung von Y57.9! siehe DKR 1917.\nHinweis:\nSiehe auch KDE-476","pdfFile":"pdf/2020-09-18_KDE-134_Entscheidung-KDE-134-Rektumkarzinom,-Enterokolitis,-Malignom,-Hauptdiagnose.pdf-(217,53-kB).pdf","codes":{"icd":["C20","K52.1","Y57.9"],"ops":[],"dkr":["0211d","D002"]},"category":"kde"},{"decisionDate":"2020-09-18","publicationDate":"2020-10-15","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-275","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 275 Rechtsherzkatheter, Monitoring, Pulmonaliskatheter.pdf (57,93 kB)","sourceURL":"https://www.g-drg.de/content/download/9812/file/Entscheidung%20KDE%20275%20Rechtsherzkatheter,%20Monitoring,%20Pulmonaliskatheter.pdf","keywords":"Entscheidung KDE 275 Rechtsherzkatheter, Monitoring, Pulmonaliskatheter.pdf (57,93 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n18.09.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des PKV-Verbandes\nwie folgt entschieden:\nEntscheidung KDE 275:\nDas in diesem Fall (KDE-275) zur Steuerung einer Katecholamintherapie durchgeführte prä- und\npostoperative Monitoring des Herzzeitvolumens über einen Pulmonalis-Einschwemmkatheter ist\nbei dem intensivmedizinisch behandelten Patienten als Patientenmonitoring einmal mit dem\nOPS-Kode 8-932 Monitoring von Atmung, Herz und Kreislauf mit Messung des\nPulmonalarteriendruckes zu kodieren (siehe Hinweis zum Kode 8-93 und DKR P005, Tabelle 1).\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.12.2020 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 06.10.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-275\nSchlagworte: Rechtsherzkatheter, Monitoring, Pulmonaliskatheter\nStand: 2009-02-02\nAktualisiert: 01.01.2019\nOPS: 1-273; 8-932\nProblem/Erläuterung:\nBei einem Patienten wird im Rahmen einer Herzoperation ein\nPulmonaliseinschwemmkatheter gelegt. Präoperativ wie auch postoperativ werden\nhierüber zur besseren Steuerung der Katecholamintherapie verschiedene hämodynamische\nParameter gemessen. Ein Parameter ist hierbei das Herzzeitvolumen, das mindestens 3 mal\ntäglich gemessen wird.\nIst für die Messung des Herzzeitvolumens einmalig der OPS-Kode 8-932 Monitoring von\nAtmung, Herz und Kreislauf mit Messung des Pulmonalarteriendruckes zu verwenden oder\nist jeweils ein Kode aus 1-273 Rechtsherz- Katheteruntersuchung zu verwenden?\nKodierempfehlung SEG-4:\n8-932 Monitoring von Atmung, Herz und Kreislauf mit Messung des\nPulmonalarteriendruckes ist zu kodieren.\nDie über den Pulmonaliskatheter erfolgten Messungen sind als Patientenmonitoring zu\nwerten.\nDieser Kode ist nur anzugeben, wenn es sich um einen intensivmedizinisch versorgten\nPatienten handelt und kann nur einmal pro stationären Aufenthalt angegeben werden\n(siehe Hinweis zum Kode 8-93 und DKR P005, Tabelle 1).\nKommentierung FoKA:\nDissens:\nFindet über das reine Monitoring hinaus eine weitere Leistung mit Hilfe des RH-Katheters\nstatt, wie z.B. Messung des Shuntvolumens, so ist der Kode 1-273.- zusätzlich zum 8-932\nKode zu kodieren:\n 1-273.1 Oxymetrie\n 1-273.2 Druckmessung mit Messung des Shuntvolumens\n 1-273.5 Messung der pulmonalen Flussreserve\n 1-273.6 Messung des Lungenwassers\nHinweis:\nSiehe auch FoKA 1-005 Rechtsherzkatheter, Herz-Kreislaufmonitoring","pdfFile":"pdf/2020-09-18_KDE-275_Entscheidung-KDE-275-Rechtsherzkatheter,-Monitoring,-Pulmonaliskatheter.pdf-(57,93-kB).pdf","codes":{"icd":[],"ops":["8-932","8-93","1-273","1-273.1","1-273.2","1-273.5","1-273.6","1-005"],"dkr":["P005"]},"category":"kde"},{"decisionDate":"2020-09-18","publicationDate":"2020-10-06","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-294","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 294 Thrombose, Plasmozytom.pdf (143,27 kB)","sourceURL":"https://www.g-drg.de/content/download/9813/file/Entscheidung%20KDE%20294%20Thrombose,%20Plasmozytom.pdf","keywords":"Entscheidung KDE 294 Thrombose, Plasmozytom.pdf (143,27 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n18.09.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des PKV-Verbandes\nwie folgt entschieden:\nEntscheidung KDE 294:\nIn dem beschriebenen Fall (KDE-294), bei dem der Patient wegen einer ambulant bereits\ndiagnostizierten Becken-Beinvenenthrombose ins Krankenhaus aufgenommen sowie\nheparinisiert wurde und die weitere Diagnostik u. a. eine Paraproteinämie bei Plasmozytom\nergab, die mittels Chemotherapie behandelt wurde, richtet sich die Auswahl der Hauptdiagnose\nnach dem Abschnitt „Zwei oder mehr Diagnosen, die gleichermaßen der Definition der\nHauptdiagnose entsprechen“ der DKR D002 Hauptdiagnose.\nDemnach gilt:\n„Zwei oder mehr Diagnosen, die gleichermaßen der Definition der Hauptdiagnose\nentsprechen\nWenn zwei oder mehrere Diagnosen in Bezug zu Aufnahme, Untersuchungsbefunden und/oder\nder durchgeführten Therapie gleichermaßen die Kriterien für die Hauptdiagnose erfüllen und\nICD-10-Verzeichnisse und Kodierrichtlinien keine Verschlüsselungsanweisungen geben, muss\nvom behandelnden Arzt entschieden werden, welche Diagnose am besten der Hauptdiagnose-\nDefinition entspricht. Nur in diesem Fall ist vom behandelnden Arzt diejenige auszuwählen, die\nfür Untersuchung und/oder Behandlung die meisten Ressourcen verbraucht hat. Hierbei ist es\nunerheblich, ob die Krankheiten verwandt sind oder nicht.“\nDie Hauptdiagnose ist danach abhängig vom Ressourcenverbrauch zu kodieren, welcher sich\njedoch an Hand der hier zum Sachverhalt vorliegenden Informationen allein nicht abschließend\nsicher bestimmen lässt.\n\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.12.2020 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 06.10.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-294\nSchlagwort: Thrombose, Plasmozytom\nStand: 2009-06-04\nAktualisiert: 01.01.2019\nProblem/Erläuterung:\nEin Patient wurde wegen einer ambulant bereits diagnostizierten Becken-\nBeinvenenthrombose ins Krankenhaus aufgenommen und heparinisiert. Die weitere\nDiagnostik ergab u.a. eine Paraproteinämie, aus der das Vorliegen eines Plasmozytoms\nabgeleitet wurde. Es erfolgte daraufhin eine Chemotherapie. Was ist als Hauptdiagnose,\nwas als Nebendiagnose anzugeben?\nKodierempfehlung SEG-4:\nDie Aufnahme wurde durch die tiefe Beinvenenthrombose hauptsächlich veranlasst, die\nsomit Hauptdiagnose ist. Selbst wenn möglicherweise ein Zusammenhang zwischen\nThrombose und Plasmozytom – im Sinne eines paraneoplastischen Geschehens -\nherzustellen ist, stellt die Thrombose eine eigenständige Krankheit dar, kein Symptom. Die\nReihenfolge für die Ätiologie-/ Manifestationsverschlüsselung gilt nur für das Kreuz-Stern-\nSystem. Die Hauptdiagnosen-Regelung der DKR D002 erfährt somit außerhalb der Kreuz-\nStern-Systematik in Bezug auf die Reihenfolge von Ätiologie-/ Manifestationskodes keine\nEinschränkung.\nDer Verdacht auf das Vorliegen eines Plasmozytoms ergab sich erst im Verlauf der stationär\ndurchgeführten Diagnostik und nach Aufnahme des Patienten und veranlasste die\nAufnahme ins Krankenhaus nicht. Das Plasmozytom ist als Nebendiagnose zu kodieren.\nSiehe auch Kodierempfehlungen 27 und 82.\n\nKommentierung FoKA:\nDissens:\nDKR D002f Zuweisung der zugrunde liegenden Krankheit als Hauptdiagnose: \"Wenn sich\nein Patient mit einem Symptom vorstellt und die zugrunde liegende Krankheit zum\nZeitpunkt der Aufnahme bekannt ist und behandelt wird bzw. während des\nKrankenhausaufenthaltes diagnostiziert wird, so ist die zugrunde liegende Krankheit als\nHauptdiagnose zu kodieren.\"\nDies gilt analog dem Ätiologie- und Manifestationsprinzip auch für Krankheitsbilder, die\nunmittelbare Folge einer anderen zugrunde liegenden Erkrankung sind. Die Ätiologie- und\nManifestationsverschlüsselung ist gemäß DKR nicht nur auf das Kreuz-/Stern-System\nbegrenzt, sondern kann mit allen ICD-10 Kodes benutzt werden.\nDaher ist in diesem Fall das Plasmozytom die Hauptdiagnose und die Thrombose\nNebendiagnose.\nDer Bezug auf die Reihenfolge für die Ätiologie-/Manifestationsverschlüsselung gemäß DKR\nD012f Mehrfachkodierung ist in diesem Fall ungeeignet.\nSiehe auch KDE-82, KDE-296.\n(Stand 01.02.2019)\nRückmeldung SEG-4:\nRückmeldung steht noch aus.","pdfFile":"pdf/2020-09-18_KDE-294_Entscheidung-KDE-294-Thrombose,-Plasmozytom.pdf-(143,27-kB).pdf","codes":{"icd":[],"ops":[],"dkr":["D002","D002f","D012f"]},"category":"kde"},{"decisionDate":"2020-09-18","publicationDate":"2020-10-15","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-359","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 359 Pneumothorax, Lungenkollaps.pdf (43,21 kB)","sourceURL":"https://www.g-drg.de/content/download/9814/file/Entscheidung%20KDE%20359%20Pneumothorax,%20Lungenkollaps.pdf","keywords":"Entscheidung KDE 359 Pneumothorax, Lungenkollaps.pdf (43,21 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n18.09.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des PKV-Verbandes\nwie folgt entschieden:\nEntscheidung KDE 359:\nEin Lungenkollaps in Verbindung mit einem Pneumothorax darf nur dann mit dem Kode J98.1\nLungenkollaps zusätzlich zu dem zutreffenden Kode aus J93.- Pneumothorax kodiert werden,\nwenn es sich um einen vollständigen Lungenkollaps mindestens eines Lungenlappens handelt.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.12.2020 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 06.10.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-359\nSchlagworte: Pneumothorax, Lungenkollaps\nStand: 2010-10-28\nAktualisiert: 01.01.2019\nICD: J93.1; J98.1\nProblem/Erläuterung:\nEin 45-jähriger Patient wird mit einem spontan aufgetretenen Thoraxschmerz rechts\nstationär aufgenommen. Im Röntgen-Thorax wird ein Pneumothorax rechts nachgewiesen\n(mantelförmiger Pneuspalt von max. 2 cm). Im CT-Thorax Beschreibung von kollaptischen\nLungenbezirken rechts ohne Hinweis auf einen Spannungspneumothorax. Anlage einer\nThoraxdrainage rechts. Im Verlauf des stationären Aufenthaltes wird zusätzlich eine flexible\nBronchoskopie mit unauffälligem Befund durchgeführt. Kann neben der Hauptdiagnose\nJ93.1 Pneumothorax, Sonstiger Spontanpneumothorax als Nebendiagnose zusätzlich J98.1\nSonstige Krankheiten der Atemwege, Lungenkollaps kodiert werden?\nKodierempfehlung SEG-4:\nEin Pneumothorax ist definiert als eine Ansammlung von Luft im Pleuraraum mit\nAufhebung des negativen intrapleuralen Drucks und dadurch bedingtem Kollaps der\nbetroffenen Lunge unterschiedlicher Ausprägung. Die zusätzliche Kodierung von J98.1\nSonstige Krankheiten der Atemwege, Lungenkollaps als Nebendiagnose ist daher nicht\nbegründet. J93.1 Pneumothorax, Sonstiger Spontanpneumothorax ist der spezifische Kode\nfür die Erkrankung.\nKommentierung FoKA:\nDissens:\nWenn es einen (spezifischen) Mehraufwand für die Diagnostik/Behandlung der Atelektase\ngibt, so ist eine Kodierung gemäß DKR D003i statthaft. Auch die gleichzeitige Behandlung\nvon zwei Erkrankungen durch eine Maßnahme rechtfertigt die Kodierung, siehe DKR D003i:\n\"Bei Patienten, bei denen einer dieser erbrachten Faktoren auf mehrere Diagnosen\nausgerichtet ist, können alle betroffenen Diagnosen kodiert werden.\" (27.10.2016)\nRückmeldung SEG-4:\nKein Änderungsbedarf. (27.08.2015)","pdfFile":"pdf/2020-09-18_KDE-359_Entscheidung-KDE-359-Pneumothorax,-Lungenkollaps.pdf-(43,21-kB).pdf","codes":{"icd":["J98.1","J93","J93.1"],"ops":[],"dkr":["D003i"]},"category":"kde"},{"decisionDate":"2020-09-18","publicationDate":"2020-07-21","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-463","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 463 Rektumresektion, tubul&auml;re.pdf (142,65 kB)","sourceURL":"https://www.g-drg.de/content/download/9815/file/Entscheidung%20KDE%20463%20Rektumresektion,%20tubul%C3%A4re.pdf","keywords":"Entscheidung KDE 463 Rektumresektion, tubul&auml;re.pdf (142,65 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n18.09.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des PKV-Verbandes\nwie folgt entschieden:\nEntscheidung KDE 463:\nBei einer zirkulären Vollwandexzision von überschüssiger Rektumwand bei einem inneren\nRektumprolaps mit Sphinktererhaltung unter Anwendung eines Staplers (peranale tubuläre\nResektion) ist für die Auswahl des entsprechenden OPS-Kodes (in diesem Fall (KDE-463)\nentweder OPS 5-484.27 oder OPS 5-482.b0) die Länge der resezierten Rektummanschette\nausschlaggebend.\nBeträgt die Länge der resezierten Rektummanschette ≥ 4 cm, so ist der OPS-Kode 5-484.27\nRektumresektion unter Sphinktererhaltung: Tubuläre Resektion unter Belassen des\nParaproktiums: Peranal anzuwenden.\nBeträgt die Länge der resezierten Rektummanschette hingegen < 4 cm so ist der OPS-Kode\n5-482.b0 Peranale lokale Exzision und Destruktion von erkranktem Gewebe des Rektums:\nVollwandexzision, mit Stapler, peranal: Zirkulär [Manschettenresektion] zu kodieren.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.12.2020 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 06.10.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-463\nSchlagwort: Rektumresektion, tubuläre\nErstellt: 08.01.2013\nAktualisiert: 01.01.2019\nOPS: 5-484.27; 5-482.b0\nProblem/Erläuterung:\nBei Vorliegen eines inneren Rektumprolaps’ wird eine zirkuläre Stapler-Vollwandexzision\nder überschüssigen Rektumwand mittels Contour® Transtar™ vorgenommen. Ist hierfür der\nOPS-Kode 5-484.27 Rektumresektion unter Sphinktererhaltung, Tubuläre Resektion unter\nBelassen des Paraproktiums, Peranal zutreffend?\nKodierempfehlung SEG-4:\nIm vorliegenden Fall erfolgte die Exzision der zirkulär überschüssigen, gefalteten\nRektumwand entsprechend dem OPS-Kode 5-482.b0 Peranale lokale Exzision und\nDestruktion von erkranktem Gewebe des Rektums,Vollwandexzision, mit Stapler, peranal,\nZirkulär [Manschettenresektion] .Eine tubuläre Resektion setzt das zirkuläre, wandnahe\nFreipräparieren des Rektums (unter Belassen des paraproktischen Gewebes) mit\nanschließender Entfernung des schlauchförmigen Abschnittes und Reanastomosierung\nvoraus. Ab 2015 sind die Hinweise zu den Kodes 5-482.b0 und 5-484.2 zu beachten:\nDemnach wird bei einer peranalen zirkulären Vollwandexzision mittels Stapler\nentsprechend dem OPS-Kode 5-482.b0 eine Rektummanschette von weniger als 4 cm Länge\nreseziert beziehungsweise ist eine peranale tubuläre Resektion einer Rektummanschette\nvon weniger als 4 cm Länge als peranale lokale Exzision zu kodieren (5-482.90, 5-482.a, 5-\n482.b0).Siehe auch Kodierempfehlung 117.\nKommentierung FoKA:\nDissens:\nDer alleinige Einsatz eines Staplers begründet in diesem Fall nicht einen anderen OPS-Kode,\nda als Unterschiedsmerkmal das Ausmaß der Resektion heranzuziehen ist. Außerdem ist der\nGebrauch eines Staplers ausdrücklich im Hinweistext des OPS-Kodes 5-484.27 vorgesehen.\nRückmeldung SEG 4:\nIn unserer Fallkonstellation ist das Ausmaß der Resektion nicht angegeben, deshalb ist\nunsere KE nicht falsch, wird aber zur Abgrenzbarkeit überarbeitet. (17.12.2015)","pdfFile":"pdf/2020-09-18_KDE-463_Entscheidung-KDE-463-Rektumresektion,-tubul&auml;re.pdf-(142,65-kB).pdf","codes":{"icd":[],"ops":["5-484.27","5-482.b0","5-484.2","5-482.90","5-482.a"],"dkr":[]},"category":"kde"},{"decisionDate":"2020-09-18","publicationDate":"2020-11-25","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-561","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 561 Mastektomie, prophylaktische, Familienanamnese.pdf (218,28 kB)","sourceURL":"https://www.g-drg.de/content/download/9816/file/Entscheidung%20KDE%20561%20Mastektomie,%20prophylaktische,%20Familienanamnese.pdf","keywords":"Entscheidung KDE 561 Mastektomie, prophylaktische, Familienanamnese.pdf (218,28 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n18.09.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des PKV-Verbandes\nwie folgt entschieden:\nEntscheidung KDE 561:\nErfolgt die Aufnahme zur prophylaktischen Operation der Brust bei nachgewiesener BRCA1-\nMutation und positiver Familienanamnese und findet sich im Resektat keine maligne Neubildung\nist Z80.3 Bösartige Neubildung der Brustdrüse [Mamma] in der Familienanamnese als\nHauptdiagnose anzugeben. Der Kode Q99.8 Sonstige näher bezeichnete\nChromosomenanomalien kann im vorliegenden Fall nicht als Nebendiagnose angegeben\nwerden.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.12.2020 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 06.10.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-561\nSchlagworte: Mastektomie, prophylaktische, Familienanamnese\nErstellt: 20.06.2016\nAktualisiert: 01.01.2019\nProblem/Erläuterung:\nDer stationäre Aufenthalt einer 35-jährigen Frau mit nachgewiesener BRCA1- Mutation und\npositiver Familienanamnese erfolgt zur prophylaktischen Mastektomie.\nWas ist die Hauptdiagnose?\nKann Q99.8 Sonstige näher bezeichnete Chromosomenanomalien als Nebendiagnose\nangegeben werden?\nKodierempfehlung SEG-4:\nHauptdiagnose ist gemäß DKR 1205 der „Zustand“ Brustkrebs in der Familienanamnese,\nalso Z80.3 Bösartige Neubildung der Brustdrüse [Mamma] in der Familienanamnese.\nQ99.8 Sonstige näher bezeichnete Chromosomenanomalien als Nebendiagnose ist nicht\nkorrekt, da eine Genmutation und keine Chromosomenanomalie vorliegt.\nKommentierung FoKA:\nDissens (04.07.2016)\nBei nachgewiesener Genmutation und einem dadurch auch familienanamnestisch erhöhten\nBrustkrebsrisiko ist als Hauptdiagnose Z40.00 Prophylaktische Operation an der Brustdrüse\n[Mamma] zu verschlüsseln.\nDie Genmutation selbst ist nicht verschlüsselbar.","pdfFile":"pdf/2020-09-18_KDE-561_Entscheidung-KDE-561-Mastektomie,-prophylaktische,-Familienanamnese.pdf-(218,28-kB).pdf","codes":{"icd":["Z80.3","Q99.8","Z40.00"],"ops":[],"dkr":[]},"category":"kde"},{"decisionDate":"2020-09-18","publicationDate":"2020-11-11","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-571","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 571 Diagnostische Bronchoskopie, H&auml;moptysen, Blutstillung.pdf (212,58 kB)","sourceURL":"https://www.g-drg.de/content/download/9817/file/Entscheidung%20KDE%20571%20Diagnostische%20Bronchoskopie,%20H%C3%A4moptysen,%20Blutstillung.pdf","keywords":"Entscheidung KDE 571 Diagnostische Bronchoskopie, H&auml;moptysen, Blutstillung.pdf (212,58 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n18.09.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des PKV-Verbandes\nwie folgt entschieden:\nEntscheidung KDE 571:\nWird im Rahmen einer flexiblen diagnostischen Tracheobronchoskopie eine leichte Sickerblutung\nnachgewiesen und wird diese Blutung durch Einlage eines resorbierbaren Hämostyptikums\ngestillt, so ist dies nicht zusätzlich zu kodieren.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.12.2020 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 06.10.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-571:\nSchlagworte: Diagnostische Bronchoskopie, Hämoptysen, Blutstillung\nErstellt: 13.10.2016\nAktualisiert: 01.01.2019\nProblem/Erläuterung:\nStationäre Aufnahme wegen leichten, rezidivierenden Hämoptysen zur Abklärung. Im\nRahmen der flexiblen Tracheobronchoskopie konnte eine leichte Sickerblutung im\nUnterlappenbronchus nachgewiesen werden. Zur Blutstillung erfolgte die Einlage eines\nresorbierbaren Hämostyptikums in den Unterlappenbronchus.\nWie ist die bronchoskopische Blutstillung zu kodieren?\nKodierempfehlung SEG-4:\nDer OPS‐Kode 1‐620.0x Diagnostische Tracheobronchoskopie, m it flexiblem Instrument,\nSonstige ist zu verwenden.\nBei einer diagnostischen Tracheobronchoskopie kann die bronchoskopische Blutstillung\nnicht zusätzlich verschlüsselt werden. Die Verwendung eines Kodes aus dem Kodebereich\n5‐320 Exzision und Destruktion von erkranktem Gewebe eines Bronchus ist nicht korrekt.\nDas Inklusivum \"Bronchoskopische Blutstillung\" zum Kode 5‐320 bezieht sich auf die\nbronchoskopische Blutstillung nach erfolgter Exzision und Destruktion von erkranktem\nGewebe eines Bronchus.\nSiehe auch Kodierempfehlung Nr. KDE-493.\nKommentierung FoKA:\nDissens (16.02.2017):\nDas Inklusivum \"Bronchoskopische Blutstillung\" zum OPS-Kode 5-320.0 wurde im Katalog\n2013 auf Antrag der Fachgesellschaft ergänzt. Gemäß des Antrages soll durch das\nInklusivum zum Ausdruck gebracht werden, dass sämtliche bronchoskopische\nBlutstillungsverfahren mit dem genannten Kode abzubilden sind.\nEin Kode aus dem Kapitel 1 des OPS ist nicht geeignet, therapeutische Verfahren zu\nverschlüsseln.","pdfFile":"pdf/2020-09-18_KDE-571_Entscheidung-KDE-571-Diagnostische-Bronchoskopie,-H&auml;moptysen,-Blutstillung.pdf-(212,58-kB).pdf","codes":{"icd":[],"ops":["5-320.0"],"dkr":[]},"category":"kde"},{"decisionDate":"2020-09-30","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-16","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 16 Kachexie.pdf (142,13 kB)","sourceURL":"https://www.g-drg.de/content/download/9921/file/Entscheidung%20KDE%2016%20Kachexie.pdf","keywords":"Entscheidung KDE 16 Kachexie.pdf (142,13 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n30.09.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 16:\nDer Kode R64 Kachexie kann kodiert werden, wenn der Gewichtsverlust ≥ 5%* in ≤ 12 Monaten\nbei Vorliegen einer Erkrankung beträgt, PLUS DREI der folgenden Kriterien vorliegen:\n• Verringerte Muskelkraft (z. B. Handgriffstärke)\n• Erschöpfung\n• Appetitlosigkeit\n• Niedriger Fettfreie-Masse-Index (fettfreie Masse [kg]/Körpergröße2 [m2])\n• Abnormale Biochemie\n- erhöhte Entzündungsmarker (CRP > 5,0 mg/L, IL-6 > 4,0 pg/mL), oder\n- Anämie (Hb < 12 g/dL), oder\n- niedriges Serumalbumin (< 32 g/L)\n* ohne Ödem; falls Gewichtsverlust nicht eruierbar, ist ein BMI <20,0 kg/m2 für die Diagnose der\nKachexie ausreichend.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.12.2020 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 15.10.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-16\nSchlagwort: Kachexie\nStand:\nAktualisiert: 2019-06-26\nProblem/Erläuterung:\nWann darf R64 Kachexie verschlüsselt werden?\nKodierempfehlung SEG 4:\nMindestvoraussetzungen: Dokumentation von Körpergröße und -gewicht und\nBeeinflussung des Patientenmanagements.\nNeben der allgemeinen Definition (schwere Form der Abmagerung mit\nAtrophie/körperliche Auszehrung) unter Berücksichtigung des klinischen Gesamtzustandes\nist ein BMI unter 18,5 kg/m2 (Definition Untergewicht WHO) zu fordern. Siehe auch\nKodierempfehlung 599.\nKommentar FoKA:\nDissens (Revision vom 03.12.2010):\nDer BMI ist zwar richtungsweisend aber nicht alleinige Bedingung. Bei Unterschreitung der\nBMI-Norm oder entsprechendem klinischen Habitus und durchgeführter Therapie (z.B.\nhochkalorische Therapie, pflegerische Unterstützung bei Nahrungsaufnahme, etc.) ist die\nKodierung sachgerecht.\nHinweis: abnorme Gewichtsabnahme (R63.4) ist abzugrenzen.\nRückmeldung SEG 4:\nNach Prüfung weiterhin kein Anpassungsbedarf. Klinischer Gesamtzustand und BMI sind\nVoraussetzungen für eine Kachexie.","pdfFile":"pdf/2020-09-30_KDE-16_Entscheidung-KDE-16-Kachexie.pdf-(142,13-kB).pdf","codes":{"icd":["R64","R63.4"],"ops":[],"dkr":[]},"category":"kde"},{"decisionDate":"2020-09-30","publicationDate":"2020-08-19","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-37","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 37 Insuffizienz, respiratorische .pdf (138,97 kB)","sourceURL":"https://www.g-drg.de/content/download/9922/file/Entscheidung%20KDE%2037%20Insuffizienz,%20respiratorische%20.pdf","keywords":"Entscheidung KDE 37 Insuffizienz, respiratorische .pdf (138,97 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n30.09.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 37:\nEine respiratorische Insuffizienz (J96.-) kann kodiert werden, wenn bei Vorliegen diesbezüglich\nbestehender klinischer Zeichen (ein oder mehrere) unter Raumluft (sofern der Zustand des\nPatienten eine Messung unter Raumluft zulässt):\n• eine pathologisch veränderte arterielle oder kapilläre Blutgasanalyse (z. B. Sauerstoffsättigung\noder eine Hyperkapnie oder Hypoxämie (gemäß den Normwerten des verwendeten\nAnalysegerätes) vorliegt oder\n• eine erniedrigte Sauerstoffsättigung ≤ 92% (nur bei Messung durch eine periphere\nPulsoxymetrie) gemessen wurde.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.12.2020 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 15.10.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-37\nSchlagwort: Insuffizienz, respiratorische\nStand: 2007-01-10\nAktualisiert: 2012-01-16\nICD: J96.-\nProblem/Erläuterung:\nWann ist respiratorische Insuffizienz zu kodieren?\nKodierempfehlung SEG 4:\nRespiratorische Insuffizienz liegt vor, wenn pathologische Blutgasveränderungen im Sinne\neiner respiratorischen Partial- oder Globalinsuffizienz nachweisbar sind. Eine Dyspnoe ohne\nBGA Veränderung ist keine respiratorische Insuffizienz. J96.- Respiratorische Insuffizienz,\nanderenorts nicht klassifiziert , kann bei Aufwand (z.B. Sauerstoff-Gabe) zusätzlich zur\nGrundkrankheit verschlüsselt werden.\nKommentar FoKA:\nDissens:\nDas Vorhandensein einer respiratorischen Insuffizienz definiert sich nicht ausschließlich an\npathologischen BGA-Veränderungen, sondern liegt immer dann vor, wenn ein Patient die\nklinischen und/oder paraklinischen Zeichen einer Gasaustauschstörung erfüllt und ein\nentsprechender Ressourcenverbrauch nachweisbar dokumentiert ist. Evtl. BGA-\nVeränderungen unterstützen lediglich die Diagnose einer respiratorischen Insuffizienz.\nRückmeldung SEG 4:\nKein Anpassungsbedarf\nAktualisierung Kodierempfehlung SEG 4 vom 11.12.2019:\nRespiratorische Insuffizienz liegt vor, wenn pathologische Blutgasveränderungen im Sinne\neiner respiratorischen Partial- oder Globalinsuffizienz nachweisbar sind. Eine Dyspnoe ohne\nBGA-Veränderung (arterielle oder kapilläre) ist keine respiratorische Insuffizienz.\nJ96.- Respiratorische Insuffizienz, anderenorts nicht klassifiziert kann bei Aufwand (z. B.\nSauerstoff-Gabe) zusätzlich zur Grundkrankheit verschlüsselt werden, wenn pathologische\nBlutgasveränderungen im Sinne einer respiratorischen Partial- oder Globalinsuffizienz\nnachgewiesen sind.\nFür Fälle ab 2010 sind die Änderungen der DKR D003 zu Symptomen als Nebendiagnosen zu\nberücksichtigen.","pdfFile":"pdf/2020-09-30_KDE-37_Entscheidung-KDE-37-Insuffizienz,-respiratorische-.pdf-(138,97-kB).pdf","codes":{"icd":["J96"],"ops":[],"dkr":["D003"]},"category":"kde"},{"decisionDate":"2020-09-30","publicationDate":"2020-07-21","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-168","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 168 Lumboischialgie, Osteochondrose, R&uuml;ckenschmerzen .pdf (42,14 kB)","sourceURL":"https://www.g-drg.de/content/download/9923/file/Entscheidung%20KDE%20168%20Lumboischialgie,%20Osteochondrose,%20R%C3%BCckenschmerzen%20.pdf","keywords":"Entscheidung KDE 168 Lumboischialgie, Osteochondrose, R&uuml;ckenschmerzen .pdf (42,14 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n30.09.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 168:\nIn dem beschriebenen Fall (KDE-168), bei dem der Patient mit in das Bein ausstrahlenden\nheftigen Rückenschmerzen im Sinne einer Lumboischialgie aufgenommen wird und sich\nradiologisch eine leicht ausgeprägte Osteochondrose im LWS-Bereich findet, worauf der Patient\ninsgesamt mit einer intensiven Physiotherapie, Analgetika und Infiltrationen behandelt wird, ist\ndie Lumboischialgie als Hauptdiagnose zu kodieren.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.12.2020 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 15.10.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-168\nSchlagwort: Lumboischialgie, Osteochondrose, Rückenschmerzen\nStand: 2008-01-08\nAktualisiert: 2014-01-15\nICD: M54.4\nProblem/Erläuterung:\nEs wird ein Patient mit in das Bein ausstrahlenden heftigsten Rückenschmerzen im Sinne\neiner Lumboischialgie aufgenommen. Radiologisch findet sich eine Osteochondrose im\nLWS-Bereich. Es werden eine intensive Physiotherapie durchgeführt sowie Analgetika\nverabreicht. Ferner kommen Infiltrationen zur Anwendung. Was ist Hauptdiagnose?\nKodierempfehlung SEG 4:\nAls Hauptdiagnose ergibt sich M54.4 Lumboischialgie . Die Lumboischialgie wurde als\neigenständiges Krankheitsbild behandelt und war Aufnahmegrund.\nKommentar FoKA:\nDissens\nDas vorliegende Fallbeispiel ist aufgrund fehlender weiterer klinischer Informationen nicht\ngeeignet, um eine Kodierempfehlung abzuleiten.\nIst die Osteochondrose die der Lumboischialgie zugrundeliegende Erkrankung, so ist sie\ngemäß DKR D002f die Hauptdiagnose, wenn diese im aktuellen Fall diagnostiziert wird.\nIst ein Kausalzusammenhang zwischen Osteochondrose und Lumboischialgie bereits bei\nAufnahme bekannt, so wird bei alleiniger Therapie der Lumboischialgie diese als\nHauptdiagnose und die Osteochondrose als Nebendiagnose kodiert.\nRückmeldung SEG 4:\nKein Änderungsbedarf.","pdfFile":"pdf/2020-09-30_KDE-168_Entscheidung-KDE-168-Lumboischialgie,-Osteochondrose,-R&uuml;ckenschmerzen-.pdf-(42,14-kB).pdf","codes":{"icd":["M54.4"],"ops":[],"dkr":["D002f"]},"category":"kde"},{"decisionDate":"2020-09-30","publicationDate":"2020-08-19","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-206","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 206 Wundverschluss, Narbenexzision, Dehnungsplastik .pdf (47,31 kB)","sourceURL":"https://www.g-drg.de/content/download/9924/file/Entscheidung%20KDE%20206%20Wundverschluss,%20Narbenexzision,%20Dehnungsplastik%20.pdf","keywords":"Entscheidung KDE 206 Wundverschluss, Narbenexzision, Dehnungsplastik .pdf (47,31 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n30.09.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 206:\nErfolgt die Aufnahme eines Patienten zur Exzision einer schmerzhaften breiten Narbe am\nUnterschenkel und werden zum Wundverschluss die Wundränder durch Spreizen des\nSubcutangewebes mobilisiert und Burow-Dreiecke reseziert (kleine Hautdreiecke, die zum\nLängenausgleich an ungleich langen Wundrändern aus dem Endbereich des kürzeren Randes\nzu dessen Verlängerung herausgeschnitten werden), um ein kosmetisch gutes Ergebnis zu\nerzielen, ist dies bei einer lokalen Exzision (Fläche von bis zu 4 cm2 oder Raum von bis zu\n1 cm3) nicht zusätzlich mit einem OPS-Kode aus 5-903.- Lokale Lappenplastik an Haut und\nUnterhaut zu dem zutreffenden OPS-Kode aus 5-894.- Lokale Exzision von erkranktem Gewebe\nan Haut und Unterhaut zu kodieren.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.12.2020 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 15.10.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-206\nSchlagwort: Wundverschluss, Narbenexzision, Dehnungsplastik\nStand: 2007-12-18\nAktualisiert SEG 4: 15.01.2015\nAktualisiert FoKA: 15.09.2010\nOPS: 5-894; 5-903\nProblem/Erläuterung:\nAufnahme eines Patienten zur Exzision einer schmerzhaften breiten Narbe am\nUnterschenkel. Zum Wundverschluss wurden die Wundränder durch Spreizen des\nSubcutangewebes mobilisiert und Burow-Dreiecke reseziert (kleine Hautdreiecke, die zum\nLängenausgleich an ungleich langen Wundrändern aus dem Endbereich des kürzeren\nRandes zu dessen Verlängerung herausgeschnitten werden), um ein kosmetisch gutes\nErgebnis zu erzielen. Ist die zusätzliche Kodierung einer Dehnungsplastik mit einem OPS-\nKode aus 5-903 Lokale Lappe nplastik an Haut und Unterhaut korrekt?\nKodierempfehlung SEG 4:\nBei jedem Wundverschluss im Rahmen einer Narbenexzision wird ein kosmetisch gutes\nErgebnis angestrebt. Die im Einzelfall erforderliche Wundrandmobilisation, einschließlich\nder Entfernung kleiner Hautareale, um eine spannungsfreie Wundadaptation zu erzielen,\nist als integraler Bestandteil einer Narbenexzision (5-894 Lokale Exzision von erkranktem\nGewebe an Haut und Unterhaut ) zu bewerten. Der Leistungsinhalt einer lokalen\nLappenplastik (OPS 5-903 Lokale Lappenplastik an Haut und Unterhaut ) kann aus den\nvorliegenden Informationen nicht abgeleitet werden.\nSiehe auch Kodierempfehlung 264.\nKommentar FoKA:\nDissens (Revision 15.09.2010):\nIn dem Kode 5-894 ist eine einfache Exzision ggf. mit Mobilisation der unmittelbaren\nWundränder dargestellt. Darüber hinaus gehende Maßnahmen zum Wundverschluss sind in\ndiesem Kode nicht enthalten.\nBei einer lokalen Lappenplastik wird Hautgewebe durch zusätzliche Entlastungsschnitte\n(z.B. auch Burow-Dreiecke) oder den Einsatz von Expandern mobilisiert, um Wundränder\nspannungsfrei zu adaptieren oder Defekte zu decken. Dazu sind unterschiedliche Verfahren\ngebräuchlich, die in der 5. Stelle differenziert werden.\nEin Kode aus 5-903 ist zusätzlich zu verwenden, um den Aufwand einer plastischen\nKorrektur abzubilden.\nHinweis\nSiehe auch KDE-6 und KDE-264.\n\nRückmeldung SEG 4:\nKein Änderungsbedarf, weil hier keine Lappenplastik erfolgte, sondern der Wundverschluss.\nAktualisierung SEG 4 vom 11.12.2019:\nBei jedem Wundverschluss im Rahmen einer Narbenexzision wird ein kosmetisch gutes\nErgebnis angestrebt. Die im Einzelfall erforderliche Wundrandmobilisation, einschließlich\nder Entfernung kleiner Hautareale, um eine spannungsfreie Wundadaptation zu erzielen,\nist als integraler Bestandteil einer Narbenexzision (5-894 Lokale Exzision von erkranktem\nGewebe an Haut und Unterhaut ) zu bewerten. Der Leistungsinhalt einer lokalen\nLappenplastik (OPS 5-903 Lokale Lappenplastik an Haut und Unterhaut ) kann aus den\nvorliegenden Informationen nicht abgeleitet werden.\nDa es für die lokale Exzision eine klare Definition gibt, sind alle größeren Exzisionen (größer\nals 4 cm2 oder über 1 cm3) mit einem Kode aus 5-895 Radikale und ausgedehnte Exzision\nvon erkranktem Gewebe an H aut und Unterhaut zu verschlüsseln.\nSiehe auch Kodierempfehlungen 6 und 264.","pdfFile":"pdf/2020-09-30_KDE-206_Entscheidung-KDE-206-Wundverschluss,-Narbenexzision,-Dehnungsplastik-.pdf-(47,31-kB).pdf","codes":{"icd":[],"ops":["5-903","5-894","5-895"],"dkr":[]},"category":"kde"},{"decisionDate":"2020-09-30","publicationDate":"2020-10-15","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-231","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 231 Karzinom, Metastase, Fistelresektion, Hauptdiagnose .pdf (132,16 kB)","sourceURL":"https://www.g-drg.de/content/download/9925/file/Entscheidung%20KDE%20231%20Karzinom,%20Metastase,%20Fistelresektion,%20Hauptdiagnose%20.pdf","keywords":"Entscheidung KDE 231 Karzinom, Metastase, Fistelresektion, Hauptdiagnose .pdf (132,16 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n30.09.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 231:\nIn dem beschriebenen Fall (KDE-231) des Patienten, bei dem ein Karzinom des Mittelgesichtes\nmit Operation und postoperativer Nachbestrahlung behandelt wurde, eine Unterkieferteilresektion\nbei Knochenmetastase erfolgte und anschließend eine persistierende intra- und extraorale Fistel\nauftrat und aktuell eine Fistelresektion und ansonsten keine diagnostischen oder therapeutischen\nMaßnahmen in direktem Zusammenhang mit der Tumorerkrankung durchgeführt werden, ist für\ndie Auswahl der Hauptdiagnose der Beschluss des Schlichtungsausschusses Bund alter\nFassung vom 04.07.2016 anzuwenden.\nDemnach gilt:\n„Wird bei einem Patienten – mit zum Zeitpunkt der Aufnahme bekanntem Malignom und bevor\ndie Malignom-Behandlung endgültig abgeschlossen ist – während des stationären Aufenthaltes\nausschließlich eine einzelne Erkrankung (oder Komplikation) als Folge einer Tumortherapie oder\neines Tumors behandelt, wird in diesem Fall die behandelte Erkrankung als Hauptdiagnose\nangegeben und der Tumor als Nebendiagnose.\nHiervon ausgenommen sind solche Fälle, bei denen weitere diagnostische oder therapeutische\nMaßnahmen in direktem Zusammenhang mit der Tumorerkrankung durchgeführt werden. In\ndiesem Fall ist die Tumorerkrankung als Hauptdiagnose zu kodieren.“\nIn dem beschriebenen Fall ist die Fistel mit dem Kode K12.28 Sonstige Phlegmone und Abszess\ndes Mundes als Hauptdiagnose zu kodieren.\n\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.12.2020 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 15.10.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-231\nSchlagwort: Karzinom, Metastase, Fistelresektion, Hauptdiagnose\nStand: 17.06.2008\nAktualisiert SEG 4: 01.01.2018\nAktualisiert FoKA: 01.01.2019\nICD: T81.8\nProblem/Erläuterung:\nMit Operation und postoperativer Nachbestrahlung behandeltes Karzinom des\nMittelgesichtes; ferner Unterkieferteilresektion bei Knochenmetastase. Anschließend\npersistierende intra- und extraorale Fistel. Aktuell: Fistelresektion; sonst keine weiteren\ndiagnostischen oder therapeutischen Maßnahmen in direktem Zusammenhang mit der\nTumorerkrankung. Was ist die Hauptdiagnose?\nKodierempfehlung SEG 4:\nHauptdiagnose ist T81.8 Sonstige Komplikationen bei Eingriffen, anderenorts nicht\nklassifizi ert (darunter auch Persistierende postoperative Fistel; ein organspezifischer Kode\nexistiert nicht). Aufnahmegrund war weder die maligne Erkrankung noch eine Chemo-\n/Strahlentherapie, so dass die Hauptdiagnose gemäß Hauptdiagnosendefinition zu wählen\nist (siehe DKR 0201).\nKommentar FoKA:\nDissens:\nErworbene Fisteln gehören in der ICD 10 in vielen Fällen zu den abszedierenden\nEntzündungen. So wurde in 2017 die ösophagotracheale Fistel explizit dem Kode J86.0\nPyothorax mit Fistel als Klarstellung zugeordnet.\n\nEin spezifischer Kode für das im Beispiel beschriebene Krankheitsbild ist entsprechend des\nalphabetischen Verzeichnisses ein Eintrag aus K12.28:\n Mundantrumfistel\n Mundbodenfistel\n Mundfistel\n Mundhöhlenfistel\n Orale Fistel\nHat die Fistel ihren Ursprung in der Region der Metastase des Unterkiefers, ist ein Kode aus\nK10.2- Entzündliche Zustände der Kiefer zu wählen.\nDer Kode T81.8 ist gemäß DKR D015 nur dann auszuwählen, wenn kein spezifischerer Kode\nexistiert. (Stand 30.07.2018)\nRückmeldung SEG 4:\nEin organspezifischer Fistelkode ist uns für diesen Fall nicht bekannt.","pdfFile":"pdf/2020-09-30_KDE-231_Entscheidung-KDE-231-Karzinom,-Metastase,-Fistelresektion,-Hauptdiagnose-.pdf-(132,16-kB).pdf","codes":{"icd":["K12.28","T81.8","J86.0","K10.2"],"ops":[],"dkr":["D015"]},"category":"kde"},{"decisionDate":"2020-09-30","publicationDate":"2020-07-21","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-268","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 268 Nierenversagen, akut, pr&auml;renal, Niereninsuffizienz, chronisch .pdf (145,38 kB)","sourceURL":"https://www.g-drg.de/content/download/9926/file/Entscheidung%20KDE%20268%20Nierenversagen,%20akut,%20pr%C3%A4renal,%20Niereninsuffizienz,%20chronisch%20.pdf","keywords":"Entscheidung KDE 268 Nierenversagen, akut, pr&auml;renal, Niereninsuffizienz, chronisch .pdf (145,38 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n30.09.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 268:\nDie Kodierung des akuten und chronischen Nierenversagens richtet sich nach dem Wortlaut des\nICD-10-GM. Die chronische Niereninsuffizienz ist eine strukturelle oder funktionelle Auffälligkeit\nder Niere über mehr als 3 Monate mit Auswirkung auf die Gesundheit.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.12.2020 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 15.10.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-268\nSchlagwort: Nierenversagen, akut, prärenal, Niereninsuffizienz, chronisch\nErstellt: 04.06.2009\nAktualisiert: 03.04.2017\nICD: N19; N17.9\nProblem/Erläuterung:\n1. Nach welchen Kriterien wird ein akutes Nierenversagen (ohne Histologiebefund)\nverschlüsselt?\n2. Wie wird ein prärenales Nierenversagen z.B. bei Exsikkose kodiert?\n3. Wann wird von einer chronischen Niereninsuffizienz gesprochen?\n4. Kann eine chronische Niereninsuffizienz als Nebendiagnose kodiert werden, wenn die\nglomeruläre Filtrationsrate (GFR) nur unter Verwendung der MDRD (Modification of Diet in\nRenal Disease)- oder Cockroft-Gault-Formel bestimmt wird ohne sonstige Maßnahmen?\nKodierempfehlung SEG 4:\n1. Das Akute Nierenversagen (ANV) ist eine schnell eintretende, prinzipiell reversible\nVerschlechterung der exkretorischen Nierenfunktion. Die Diagnose orientiert sich an den\nRifle-Kriterien (Risk-Injury-Failure-Loss-ESRD; internationale Konsensuskonferenz 2004) -\nDefinition ANV (RIFLE-Stadium Failure):\n• Anstieg des Serumkreatinins um das 3-fache des Ausgangswertes oder\n• Serum-Kreatinin > 4 mg/dl mit einem akuten Anstieg von mindestens 0,5 mg/dl oder\n• Abfall der GFR > 75 % oder\n• Rückgang der Urin-Ausscheidung auf < 0,3ml/kg/h für 24 h oder\n• Anurie für mindestens 12 Stunden.\n2007 wurde auf einer internationalen Konsensuskonferenz des Acute Kidney Injury\nNetwork (AKIN) der Begriff acute kidney injury geprägt. Dabei entsprechen die AKIN-\nStadien 1 und 2 einem drohenden akuten Nierenversagen. Erst Stadium 3 beschreibt das\nKrankheitsbild des akuten Nierenversagens und entspricht dem Stadium Failure nach RIFLE.\n2012 wurde durch die KDIGO-Foundation (Kidney Disease: Improving Global Outcomes)\neine Leitlinie zur stadiengerechten Prävention und Therapie der akuten Nierenschädigung\nveröffentlicht, die auf den RIFLE und AKIN-Kriterien basiert und das Konzept der AKI (Acute\nKidney Injury) weiterentwickelt.\nKDIGO definiert die akute Nierenschädigung (AKI) als einen abrupten Rückgang der\nNierenfunktion, der auch – aber nicht nur – das akute Nierenversagen umfasst.\nEntsprechend sind die Schwellenwerte, ab denen von einer AKI gesprochen wird, niedriger\nangesetzt. Die KDIGO-Leitlinien weisen explizit darauf hin, dass die akute Nierenschädigung\n(AKI: Acute Kidney Injury) nicht mit einem Akuten Nierenversagen (ARF: Acute Renal\n\nFailure) gleichzusetzen ist. Dies wird leider in manchen deutschsprachigen Publikationen\ndurch eine ungenaue Übersetzung bzw. Gleichsetzung der Begriffe suggeriert.\nEin Patient kann ein akutes Nierenversagen und eine chronische Niereninsuffizienz /\nNierenkrankheit zugleich aufweisen. Sofern weder eindeutig ein akutes noch ein\nchronisches Nierenversagen vorliegt, ist die Niereninsuffizienz mit N19 Nicht näher\nbezeichnet e Niereninsuffizienz zu verschlüsseln, wenn eine Beeinflussung des\nPatientenmanagements vorgelegen hat.\n2015 wurden in die Kategorie N17.‐ Akutes Nierenversagen der ICD‐10‐GM fünfte Stellen\nzur differenzierten, stadiengerechten Kodierung des akuten Nierenversagens gemäß den\nKDIGO‐Leitlinien aufgenommen. Damit ist zwar eine stadiengerechte Abbildung auf der\n5.Stelle möglich, allerdings finden sich damit auch die Stadien 1 und 2 unter der\nBezeichnung „akutes Nierenversagen“. Zur klinischen Abgrenzung der akuten\nNierenschädigung (AKI)/des akuten Nierenversagens von einem lediglich durch Exsikkose\nbedingten Anstieg der Retentionswerte ist allerdings bei den Stadien 1‐3 der Hinweis\n„adäquate Flüssigkeitszufuhr vorausgesetzt“ eingefügt worden.\n2. Liegt nach den unter Punkt 1 genannten Kriterien ein prärenales akutes Nierenversagen\nvor (Stadium Failure nach RIFLE bzw. Stadium 3 nach AKIN), ist dies mit N17.9 Akutes\nNierenversagen, nicht näher bezeichnet zu verschlüsseln.\n3. Die Definition der chronischen Nierenkrankheit nach den KDIGO Guidelines 2012 lautet\nwie folgt:\nDie Chronische Nierenkrankheit ist definiert als strukturelle oder funktionelle Auffälligkeit\nder Niere über mehr als 3 Monate mit Auswirkungen auf die Gesundheit.\nKriterien hierfür sind:\nZeichen einer Nierenschädigung über mindestens 3 Monate (ein oder mehrere Kriterien):\n::*- Albuminurie (Albuminurie ≥ 30 mg/24 h, Albumin/Kreatinin, Quotient > 30 mg/g bzw. ≥\n3 mg/mmol) ::*- Abnormes Urinsediment ::*- Elektrolytstörungen oder andere abnorme\nBefunde infolge tubulärer Erkrankung ::*- Abnormer histologischer Befund ::*- Abnorme\nBefunde in bildgebenden Verfahren ::*- Nierentransplantation in der Anamnese oder ::*-\nGFR < 60 ml/min/1,73 m2 über mindestens 3 Monate\n4. Die chronische Niereninsuffizienz / Nierenkrankheit hat bei der in Frage 4 genannten\nKonstellation das Patientenmanagement nicht beeinflusst. Der abnorme Befund hat keine\nklinische Bedeutung im Sinne einer therapeutischen Konsequenz oder einer\nweiterführenden Diagnostik gehabt. In diesem Fall ist die chronische Niereninsuffizienz/-\nkrankheit nicht als Nebendiagnose anzugeben.\nGrundsätzlich gilt auch für diese Kodierempfehlung, dass bei der Kodierung als\nNebendiagnose das Patientenmanagement beeinflusst sein muss.\nKommentierung FoKA\nDissens (Stand 27.04.2015):\nzu 1: Bei der Stadieneinteilung der akuten Nierenschädigung nach AKIN und RIFLE handelt\nes sich um Einteilungen des akuten Nierenversagens (ANV) nach Schweregraden. Nach DKR\nkann somit ein ANV jeglicher Schwere kodiert werden, sobald ein Ressourcenverbrauch zu\nverzeichnen war.\nzu 2: Auch beim prärenalen akutem Nierenversagen Beachtung der Schweregradeinteilung\ngemäß AKIN/RIFLE, d.h. Stadien 1-3 des ANV.\n\nzu 3: Bei anamnestischem Bestehen einer Niereninsuffizienz über mindestens 3 Monate\nkann eine chronische NI gemäß der GFR-Einteilung des ICD-Kataloges und gleichzeitigem\nRessourcenverbrauch kodiert werden.\nzu 4: Eine Ermittlung der GFR mittels MDRD und/oder Cockroft/Gault-Formel ist statthaft.\nOhne einen Ressourcenaufwand (nur die Ermittlung der GFR selber) ist keine Kodierung\nmöglich, die Definition der ND gemäß DKR muss erfüllt sein.\nGrundsätzlich: Bei Vorliegen eines akuten Nierenversagen (N17.-) auf Basis einer bereits\nbestehenden chronischen Niereninsuffienz (N18.8-) sind beide Kodes gemäß DKR D006e zu\nverwenden.\nErgänzung (27.04.2015): Kein Anpassungsbedarf, die Ausdifferenzierung der ICD-Schlüssel\nab 01.01.2015 ist zu beachten.\nRückmeldung SEG 4:\nRückmeldung steht noch aus.\nAktualisierung Kodierempfehlung SEG 4 vom 11.12.2019:\n1. Das akute Nierenversagen (ANV) ist eine schnell eintretende, prinzipiell reversible\nVerschlechterung der exkretorischen Nierenfunktion.\nDie Diagnose orientiert sich an den Rifle-Kriterien (Risk-Injury-Failure-Loss-ESRD;\ninternationale Konsensuskonferenz 2004) – Definition ANV (RIFLE-Stadium Failure):\n Anstieg des Serumkreatinins um das 3-fache des Ausgangswertes oder\n Serum-Kreatinin ≥ 4 mg/dl mit einem akuten Anstieg von mindestens\n 0,5 mg/dl oder\n Abfall der GFR > 75 % oder\n Rückgang der Urin-Ausscheidung auf < 0,3 ml/kg/h für 24 h oder\n Anurie für mindestens 12 Stunden.\n2007 wurde auf einer internationalen Konsensuskonferenz des Acute Kidney Injury\nNetwork (AKIN) der Begriff acute kidney injury geprägt. Dabei entsprechen die AKIN-\nStadien 1 und 2 einem drohenden akuten Nierenversagen. Erst Stadium 3 beschreibt das\nKrankheitsbild des akuten Nierenversagens und entspricht dem Stadium Failure nach RIFLE.\n2012 wurde durch die KDIGO-Foundation (Kidney Disease: Improving Global Outcomes)\neine Leitlinie zur stadiengerechten Prävention und Therapie der akuten Nierenschädigung\nveröffentlicht, die auf den RIFLE und AKIN-Kriterien basiert und das Konzept der AKI (Acute\nKidney Injury) weiterentwickelt.\nKDIGO definiert die akute Nierenschädigung (AKI) als einen abrupten Rückgang der\nNierenfunktion, der auch – aber nicht nur – das akute Nierenversagen umfasst.\nEntsprechend sind die Schwellenwerte, ab denen von einer AKI gesprochen wird, niedriger\nangesetzt.\nDie KDIGO-Leitlinien weisen explizit darauf hin, dass die akute Nierenschädigung (AKI:\nAcute Kidney Injury) nicht mit einem akuten Nierenversagen (ARF: Acute Renal Failure)\ngleichzusetzen ist. Dies wird leider in manchen deutschsprachigen Publikationen durch eine\nungenaue Übersetzung bzw. Gleichsetzung der Begriffe suggeriert.\n\nEin Patient kann ein akutes Nierenversagen und eine chronische\nNiereninsuffizienz/Nierenkrankheit zugleich aufweisen. Sofern weder eindeutig ein akutes\nnoch ein chronisches Nierenversagen vorliegt, ist die Niereninsuffizienz mit N19 Nicht näher\nbezeichnete Niereninsuffizienz zu verschlüsseln, wenn eine Beeinflussung des\nPatientenmanagements vorgelegen hat.\n2015 wurden in die Kategorie N17.- Akutes Nierenversagen der ICD-10-GM fünfte Stellen\nzur differenzierten, stadiengerechten Kodierung des akuten Nierenversagens gemäß den\nKDIGO-Leitlinien aufgenommen. Damit ist zwar eine stadiengerechte Abbildung auf der 5.\nStelle möglich, allerdings finden sich damit auch die Stadien 1 und 2 unter der Bezeichnung\n„akutes Nierenversagen“. Zur klinischen Abgrenzung der akuten Nierenschädigung\n(AKI)/des akuten Nierenversagens von einem lediglich durch Exsikkose bedingten Anstieg\nder Retentionswerte ist allerdings bei den Stadien 1-3 der Hinweis „adäquate\nFlüssigkeitszufuhr vorausgesetzt“ eingefügt worden.\nFür Fälle ab 2017 wird in der ICD-10 GM der adäquate Hydratationszustand nur noch für\nStadium 1 gefordert.\n2. Liegt nach den unter Punkt 1 genannten Kriterien ein prärenales akutes Nierenversagen\nvor (Stadium Failure nach RIFLE bzw. Stadium 3 nach AKIN), ist dies mit N17.9- Akutes\nNierenversagen, nicht näher bezeichnet zu verschlüsseln.\nAb 2017 ist das akute prärenale Nierenversagen unter N17.- inkludiert. Damit gelten auch\nfür die Verschlüsselung des akuten prärenalen Nierenversagens die Vorgaben dieser\nKodegruppe, d. h. ab Stadium 2 ist das akute prärenale Nierenversagen auch unabhängig\nvom Hydratationszustand zum Zeitpunkt der Messungen stadiengerecht verschlüsselbar.\nUmgekehrt schließt jedoch ein nicht-adäquater Hydratationszustand zum Zeitpunkt der\nMessung die Kodierung eines Stadium 1 auch beim akuten prärenalen Nierenversagen aus.\nIn dieser Fallkonstellation wäre beispielsweise die E86 Volumenmangel zu kodieren.\n3. Die Definition der chronischen Nierenkrankheit nach den KDIGO Guidelines 2012 lautet\nwie folgt:\nDie Chronische Nierenkrankheit ist definiert als strukturelle oder funktionelle Auffälligkeit\nder Niere über mehr als 3 Monate mit Auswirkungen auf die Gesundheit.\nKriterien hierfür sind:\nZeichen einer Nierenschädigung über mindestens 3 Monate (ein oder mehrere Kriterien):\n- Albuminurie (Albuminurie ≥ 30 mg/24 h, Albumin/Kreatinin, Quotient > 30 mg/g bzw. ≥ 3\nmg/mmol)\n- Abnormes Urinsediment\n- Elektrolytstörungen oder andere abnorme Befunde infolge tubulärer Erkrankung\n- Abnormer histologischer Befund\n- Abnorme Befunde in bildgebenden Verfahren\n- Nierentransplantation in der Anamnese\noder\n\n- GFR < 60 ml/min/1,73 m2 über mindestens 3 Monate\n4. Die chronische Niereninsuffizienz/Nierenkrankheit hat bei der in Frage 4 genannten\nKonstellation das Patientenmanagement nicht beeinflusst. Der abnorme Befund hat keine\nklinische Bedeutung im Sinne einer therapeutischen Konsequenz oder einer\nweiterführenden Diagnostik gehabt. In diesem Fall ist die chronische Niereninsuffizienz/-\nkrankheit nicht als Nebendiagnose anzugeben.\nGrundsätzlich gilt auch für diese Kodierempfehlung, dass bei der Kodierung als\nNebendiagnose das Patientenmanagement beeinflusst sein muss.\nSiehe auch Kodierempfehlungen 296 und 577.","pdfFile":"pdf/2020-09-30_KDE-268_Entscheidung-KDE-268-Nierenversagen,-akut,-pr&auml;renal,-Niereninsuffizienz,-chronisch-.pdf-(145,38.pdf","codes":{"icd":["N19","N17.9","N17","N18.8","E86"],"ops":[],"dkr":["D006e"]},"category":"kde"},{"decisionDate":"2020-09-30","publicationDate":"2020-10-06","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-296","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 296 Nierenversagen, akut, Morbus Wegener.pdf (219,06 kB)","sourceURL":"https://www.g-drg.de/content/download/9927/file/Entscheidung%20KDE%20296%20Nierenversagen,%20akut,%20Morbus%20Wegener.pdf","keywords":"Entscheidung KDE 296 Nierenversagen, akut, Morbus Wegener.pdf (219,06 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n30.09.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 296:\nIn dem beschriebenen Fall (KDE-296), beim dem der Patient wegen einer akuten\nVerschlechterung der Nierenfunktion aufgenommen und aufgrund eines akuten Nierenversagens\nhämodialysiert wurde, eine Nierenbiopsie eine RPGN – rapide progressive Glomerulonephritis –\nzeigte und als zugrunde liegende Erkrankung ein M. Wegener (Granulomatose mit Polyangiitis)\nerstmals diagnostiziert und eine Plasmapherese und Endoxan®\n-Stoß-Therapie erfolgte, ist für die\nAuswahl der Hauptdiagnose der Abschnitt „Zuweisung der zugrunde liegenden Krankheit als\nHauptdiagnose“ der DKR D002 Hauptdiagnose anzuwenden.\nDemnach gilt:\n„Zuweisung der zugrunde liegenden Krankheit als Hauptdiagnose\nWenn sich ein Patient mit einem Symptom vorstellt und die zugrunde liegende Krankheit zum\nZeitpunkt der Aufnahme bekannt ist und behandelt wird bzw. während des\nKrankenhausaufenthaltes diagnostiziert wird, so ist die zugrunde liegende Krankheit als\nHauptdiagnose zu kodieren.“\nDemnach ist die Granulomatose mit Polyangiitis (Wegener-Granulomatose) mit\nNierenbeteiligung mit den beiden Kodes M31.3† Wegener-Granulomatose und N08.5*\nGlomeruläre Krankheiten bei Systemkrankheiten des Bindegewebes als Hauptdiagnose zu\nkodieren.\n\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.12.2020 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 15.10.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-296\nSchlagwort: Nierenversagen, akut, Morbus Wegener\nStand: 04.06.2009\nAktualisiert: 15.01.2015\nICD: N17.8; N08.5*; M31.3\nProblem/Erläuterung:\nAufnahme bei akuter Verschlechterung der Nierenfunktion. Aufgrund eines akuten\nNierenversagens (Nierenbiopsie RPGN – rapide progressive Glomerulonephritis)\nDurchführung von Hämodialysen. Als Grunderkrankung wird ein M. Wegener diagnostiziert\n(Erstdiagnose), eine Plasmapherese und Endoxan®-Stoß-Therapie erfolgen. Die Patientin\nbleibt dialysepflichtig. Was ist Hauptdiagnose?\nKodierempfehlung SEG 4:\nEin Kode aus N17.8 Sonstiges akutes Nierenversagen ist als Hauptdiagnose zuzuweisen, da\nes den stationären Aufenthalt hauptsächlich veranlasst hat. Der Morbus Wegener war\nbisher nicht bekannt. Auch wenn im Rahmen des Aufenthaltes die Erstdiagnose gestellt\nwurde, so er hat dennoch den stationären Aufenthalt nicht hauptsächlich veranlasst. Die\nGlomerulonephritis ist - zusammen mit dem Befall des oberen und unteren\nRespirationstraktes - eine Manifestation der granulomatösen Vaskulitis bei Wegener'scher\nGranulomatose. Die Nierenbeteiligung des M. Wegener (M31.3) ist im Kreuz-Stern-System\ndurch die spezifische Schlüsselnummer N08.5* Glomeruläre Krankheiten bei\nSystemerkrankungen des Bindegewebes zu kodieren. Der glomeruläre Befall bei Wegener-\nGranulomatose ist nicht gleichzusetzen mit einem akuten Nierenversagen.\n\nDas akute Nierenversagen stellt medizinisch und nach der Systematik der ICD-10-GM eine\neigenständige Diagnose dar, auch wenn ein ursächlicher Zusammenhang mit der\nGrunderkrankung besteht.\nDas beschriebene akute Nierenversagen ist über die Schlüsselnummer N17.8 Sonstiges\nakutes Nierenversagen spezifisch zu kodieren, da ein histologischer Befund vorliegt.\nSiehe auch Kodierempfehlung 268.\nKommentierung FoKA:\nDissens (Stand 27.04.2015):\nDKR D002f Zuweisung der zugrunde liegenden Krankheit als Hauptdiagnose :\nWenn sich ein Patient mit einem Symptom vorstellt und die zugrunde liegende Krankheit\nzum Zeitpunkt der Aufnahme bekannt ist und behandelt wird bzw. während des\nKrankenhausaufenthaltes diagnostiziert wird, so ist die zugrunde liegende Krankheit als\nHauptdiagnose zu kodieren.\nDies gilt analog dem Ätiologie- und Manifestationsprinzip auch für Krankheitsbilder, die\nunmittelbare Folge einer anderen zugrunde liegenden Erkrankung sind. Die Ätiologie- und\nManifestationsverschlüsselung ist gemäß DKR nicht nur auf das Kreuz-/Stern-System\nbegrenzt, sondern kann mit allen ICD-10 Kodes benutzt werden.\nDaher ist in diesem Fall die Wegener-Granulomatose die Hauptdiagnose und das akute\nNierenversagen Nebendiagnose.\nSiehe auch KDE-82, KDE-294.\nRückmeldung SEG 4:\nRückmeldung steht noch aus.","pdfFile":"pdf/2020-09-30_KDE-296_Entscheidung-KDE-296-Nierenversagen,-akut,-Morbus-Wegener.pdf-(219,06-kB).pdf","codes":{"icd":["M31.3","N08.5","N17.8"],"ops":[],"dkr":["D002","D002f"]},"category":"kde"},{"decisionDate":"2020-09-30","publicationDate":"2020-11-11","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-357","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 357 Lungenmetastase, Metastasen, Tumorkonferenz .pdf (42,37 kB)","sourceURL":"https://www.g-drg.de/content/download/9928/file/Entscheidung%20KDE%20357%20Lungenmetastase,%20Metastasen,%20Tumorkonferenz%20.pdf","keywords":"Entscheidung KDE 357 Lungenmetastase, Metastasen, Tumorkonferenz .pdf (42,37 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n30.09.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 357:\nIn dem vorliegenden Fall (KDE 357) ist die Metastase mit dem Kode C78.0 Sekundäre bösartige\nNeubildung der Lunge auch dann als Nebendiagnose zu kodieren, wenn ausschließlich eine\nBesprechung in einer Tumorkonferenz stattgefunden hat und dort das weitere Vorgehen in\nHinblick auf die Metastase beraten wurde.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.12.2020 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 15.10.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-357\nSchlagworte: Lungenmetastase, Metastasen, Tumorkonferenz\nStand: 2010-08-17\nAktualisiert: 01.01.2016\nICD: C78.0\nProblem/Erläuterung:\nEine Patientin wird mit einer dekompensierten Herzinsuffizienz stationär aufgenommen.\nSechs Jahre zuvor war bei Patientin ein Mammakarzinom brusterhaltend operiert worden,\nLymphknoten waren nicht befallen, eine Behandlung des Mammakarzinoms erfolgt derzeit\nnicht. Bei der Röntgenuntersuchung des Thorax wird eine Lungenmetastase festgestellt.\nWeiterführende Diagnostik (CT, Biopsie) erfolgt während dieses Aufenthaltes nicht,\nallerdings wird der Fall der Patientin in der Tumorkonferenz vorgestellt. Darf C78.0\nSekundäre bösartige Neubildung der Lunge kodiert werden?\nKodierempfehlung SEG 4:\nC78.0 wird nicht kodiert, da die Nebendiagnosendefinition nicht erfüllt ist.\nKommentierung FoKA:\nDissens:\nDie Vorstellung eines Patienten in einer Tumorkonferenz ist ein Mehraufwand in der\nBehandlung. Somit ist die Definition der Nebendiagnose erfüllt und erfordert zwingend die\nKodierung. (27.10.206)\nRückmeldung SEG 4:\nDie Fallbesprechung in einer Tumorkonferenz stellt keinen Aufwand im Sinne der\nNebendiagnosendefinition dar. (27.08.2015)","pdfFile":"pdf/2020-09-30_KDE-357_Entscheidung-KDE-357-Lungenmetastase,-Metastasen,-Tumorkonferenz-.pdf-(42,37-kB).pdf","codes":{"icd":["C78.0"],"ops":[],"dkr":[]},"category":"kde"},{"decisionDate":"2020-09-30","publicationDate":"2020-11-25","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-537","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 537 Transmissionsprophylaxe, HIV, Neugeborenes .pdf (44,01 kB)","sourceURL":"https://www.g-drg.de/content/download/9929/file/Entscheidung%20KDE%20537%20Transmissionsprophylaxe,%20HIV,%20Neugeborenes%20.pdf","keywords":"Entscheidung KDE 537 Transmissionsprophylaxe, HIV, Neugeborenes .pdf (44,01 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n30.09.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 537:\nKann eine HIV-Infektion bei einem klinisch gesunden Neugeborenen, dass unmittelbar nach\ngeplanter Schnittentbindung eine antiretrovirale Transmissionsprophylaxe erhalten hat (HIV-\npositive Mutter mit erfolgter ausreichender antiretroviraler Behandlung in der Schwangerschaft),\nnicht nachgewiesen werden, ist für das Neugeborene der Kode Z20.6 Kontakt mit und Exposition\ngegenüber HIV als Hauptdiagnose zu kodieren.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.12.2020 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 15.10.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-537\nSchlagworte: Transmissionsprophylaxe, HIV, Neugeborenes\nErstellt: 24.06.2015\nAktualisiert: 01.01.2016\nProblem/Erläuterung:\nUnmittelbar nach geplanter Schnittentbindung wird bei einem klinisch gesunden\nReifgeborenen einer HIV-positiven Mutter, welche in der Schwangerschaft eine\nantiretrovirale Behandlung erhalten hat, eine antiretrovirale Transmissionsprophylaxe oral\nbegonnen. Was ist die Hauptdiagnose?\nKodierempfehlung SEG 4:\nAls Hauptdiagnose ist Z20.6 Kontakt mit und Exposition gegenüber HIV [Humanes\nImmundefizienz-Virus] zu kodieren.\n25.08.2016 Eine Schädigung des Neugeborenen liegt nicht vor. Kein Änderungsbedarf.\nKommentierung FoKA:\nDissens (04.07.2016)\nDie korrekte Kodierung lautet bei Beachtung der Hinweistexte in der Klassifikation:\nP00.2 Schädigung des Fetus und Neugeborenen durch infektiöse und parasitäre\nKrankheiten der Mutter\nSchädigung des Fetus oder Neugeborenen durch eine Infektionskrankheit der Mutter, die\nunter A00-B99 und J09-J11 klassifizierbar ist, aber ohne Manifestation dieser Krankheit\nbeim Fetus oder Neugeborenen\nExkl.:\nInfektionen des Genitaltraktes der Mutter und mütterliche Infektionen an sonstigen\nLokalisationen (P00.8)\nInfektionen, die für die Perinatalperiode spezifisch sind (P35-P39)\nDer Begriff Schädigung des Neugeborenen ist nicht mit dem Begriff einer manifesten\nErkrankung gleichzusetzen.\nDer Kode Z20.6 Kontakt mit und Exposition g egenüber HIV [Humanes Immundefizienz-\nVirus] ist zusätzlich als Nebendiagnose zu kodieren.\nAktualisierung Kodierempfehlung SEG 4 vom 11.12.2019:\nAls Hauptdiagnose ist Z20.6 Kontakt mit und Exposition gegenüber HIV [Humanes\nImmundefizienz-Virus] zu kodieren.","pdfFile":"pdf/2020-09-30_KDE-537_Entscheidung-KDE-537-Transmissionsprophylaxe,-HIV,-Neugeborenes-.pdf-(44,01-kB).pdf","codes":{"icd":["Z20.6","P00.2","A00","B99","J09","J11","P00.8","P35","P39"],"ops":[],"dkr":[]},"category":"kde"},{"decisionDate":"2020-09-30","publicationDate":"2020-10-15","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-541","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 541 Hyperkali&auml;mie, Nierenkrankheit .pdf (120,24 kB)","sourceURL":"https://www.g-drg.de/content/download/9930/file/Entscheidung%20KDE%20541%20Hyperkali%C3%A4mie,%20Nierenkrankheit%20.pdf","keywords":"Entscheidung KDE 541 Hyperkali&auml;mie, Nierenkrankheit .pdf (120,24 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n30.09.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 541:\nIn dem beschriebenen Fall (KDE-541), bei dem die Patientin wegen starker Überwässerung und\nHyperkaliämie bei bekannter terminaler Nierenkrankheit mit Dialysepflichtigkeit aufgenommen\nwird, eine Nierenersatztherapie (CVVH) mit Flüssigkeitsentzug und Ausgleich der Elektrolyte bei\nakuter respiratorischer Insuffizienz erfolgt und noch am Aufnahmetag die Intubation und invasive\nBeatmung begonnen und im Verlauf die Patientin tracheotomiert wird, multiple Komplikationen\n(Pneumonie, Sepsis, Multiorganversagen) auftreten, intensivmedizinische und antibiotische\nTherapie und Beatmung bis zum Tod der Patientin nach 28 Behandlungstagen erfolgen, ist für\ndie Auswahl der Hauptdiagnose der Abschnitt „Zwei oder mehr Diagnosen, die gleichermaßen\nder Definition der Hauptdiagnose entsprechen“ der DKR D002 Hauptdiagnose anzuwenden.\nDemnach gilt:\n„Zwei oder mehr Diagnosen, die gleichermaßen der Definition der Hauptdiagnose entsprechen\nWenn zwei oder mehrere Diagnosen in Bezug zu Aufnahme, Untersuchungsbefunden und/oder\nder durchgeführten Therapie gleichermaßen die Kriterien für die Hauptdiagnose erfüllen und ICD\n10-Verzeichnisse und Kodierrichtlinien keine Verschlüsselungsanweisungen geben, muss vom\nbehandelnden Arzt entschieden werden, welche Diagnose am besten der Hauptdiagnose-\nDefinition entspricht. Nur in diesem Fall ist vom behandelnden Arzt diejenige auszuwählen, die\nfür Untersuchung und/oder Behandlung die meisten Ressourcen verbraucht hat. Hierbei ist es\nunerheblich, ob die Krankheiten verwandt sind oder nicht.“\nDie Hauptdiagnose ist danach abhängig vom Ressourcenverbrauch zu kodieren, welcher sich\njedoch an Hand der hier zum Sachverhalt vorliegenden Informationen allein nicht abschließend\nsicher bestimmen lässt.\n\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.12.2020 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 15.10.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-541\nSchlagworte: Hyperkaliämie, Nierenkrankheit\nErstellt: 04.05.2015\nAktualisiert: 01.01.2019\nICD: N18.5; N18.89\nProblem/Erläuterung:\nAufnahme wegen starker Überwässerung und Hyperkaliämie bei bekannter terminaler\nNierenkrankheit mit Dialysepflichtigkeit. Es erfolgt eine Nierenersatztherapie (CVVH) mit\nFlüssigkeitsentzug und Ausgleich der Elektrolyte. Bei akuter respiratorischer Insuffizienz\nerfolgt noch am Aufnahmetag die Intubation und invasive Beatmung. Im Verlauf\nTracheotomie. Multiple Komplikationen (Pneumonie, Sepsis, Multiorganversagen),\nintensivmedizinische und antibiotische Therapie. Beatmung bis zum Tod der Patientin nach\n28 Behandlungstagen. Was ist die Hauptdiagnose?\nKodierempfehlung SEG 4:\nN18.5 Chronische Nierenkrankheit, Stadium 5 ist die korrekte Hauptdiagnose.\nAufnahmeanlass ist die dekompensierte chronische Niereninsuffizienz/Nierenkrankheit, die\nsowohl die Überwässerung als auch die Hyperkaliämie beinhaltet. Das Alphabetische\nVerzeichnis führt unter dem Suchbegriff „Niere, Insuffizienz, dekompensiert“ zur\nSchlüsselnummer N18.89 Sonstige chronische Nierenkrankheit, Stadium nicht näher\nbezeichnet . Da aber in diesem Fallbeispiel das Stadium bekannt ist, ist N18.5 der spezifische\nKode.\n\nKommentierung FoKA:\nDissens (Stand 15.09.2015):\nDer Sachverhalt der Überwässerung und Hyperkaliämie bei terminaler Nierenkrankheit ist\nmit dem Kode N18.5 abzubilden.\nDissens besteht bei der Festlegung der Hauptdiagnose. Im Beispiel fehlen Aussagen zu\nKomorbiditäten und Aufnahmebefunden. Die akute Dekompensation kann auch\nmultifaktoriell bedingt sein. Die kausalen Zusammenhänge, die zum Auftreten des akuten\nklinischen Zustandes geführt haben, können wegen fehlender Informationen nicht beurteilt\nwerden. (Kein Anpassungsbedarf 18.01.2016)\nRückmeldung SEG 4:\nDie beschriebene Fallkonstellation ist mit N18.5 korrekt abgebildet. Aus unserer Sicht also\nKonsens. (17.12.2015)","pdfFile":"pdf/2020-09-30_KDE-541_Entscheidung-KDE-541-Hyperkali&auml;mie,-Nierenkrankheit-.pdf-(120,24-kB).pdf","codes":{"icd":["N18.5","N18.89"],"ops":[],"dkr":["D002"]},"category":"kde"},{"decisionDate":"2020-09-30","publicationDate":"2020-08-19","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-589","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 589 Schmetterlingsfraktur, Beckenfraktur, Mehrfachverletzung .pdf (49,92 kB)","sourceURL":"https://www.g-drg.de/content/download/9931/file/Entscheidung%20KDE%20589%20Schmetterlingsfraktur,%20Beckenfraktur,%20Mehrfachverletzung%20.pdf","keywords":"Entscheidung KDE 589 Schmetterlingsfraktur, Beckenfraktur, Mehrfachverletzung .pdf (49,92 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n30.09.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 589:\nEs gelten die Regelungen der DKR 1911 Beispiel 1 und die Hinweise im Anhang B der DKR\nVersion 2020.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.12.2020 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 15.10.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-589\nSchlagworte: Schmetterlingsfraktur, Beckenfraktur, Mehrfachverletzung\nErstellt: 21.02.2018\nStand: 04.06.2018\nProblem/Erläuterung:\nAufnahme eines Patienten ins Krankenhaus nach schwerem Sturz. Nachweis einer\nSchmetterlingsfraktur des Beckens (nicht dislozierte Beckenringfraktur bds., d. h. Fraktur\ndes Os ischii und des Os pubis, AO Klassifikation: A2).\nWie sind die Frakturen zu kodieren?\nS32.89 Fraktur der Lendenwirbelsäule und des Beckens, Sonstige und multiple Teile des\nBeckens\noder\nS32.81 Fraktur der Lendenwirbelsäule und des Beckens, Os ischium i.V.m.\nS32.5 Fraktur der Lendenwirbelsäule und des Beckens, Fraktur des Os pubis\nKodierempfehlung SEG 4:\nDie Schlüsselnummer S32.89 ist zu verwenden. Es handelt sich um einen Kode, mit dem die\nFraktur spezifisch abbildbar ist, siehe hierzu Inklusiva zum Kode (u.a. Schmetterlingsbruch).\nDie Regelung der DKR 1911 Mehrfachverletzunge n ist nicht anzuwenden. Unter einer\nMehrfachverletzung versteht man gleichzeitig entstandene Verletzungen mehrerer\nKörperregionen oder Organsysteme. Bei vorliegender Schmetterlingsfraktur handelt es sich\nnicht um unterschiedliche Verletzungen mehrerer Körperregionen, sondern um die\nVerletzung verschiedener Teile des Beckens. Das Becken ist als eine Körperregion zu\nverstehen. Dies ist aus der Regelung der DKR 1911 in Verbindung mit der Binnensystematik\nder ICD-10-GM ableitbar. Unterschiedliche Verletzungen einer Körperregion, die eine\ngetrennte Kodierung einzelner Verletzungen begründen, liegen bei einer\nSchmetterlingsfraktur nicht vor. Die mehrfachen Frakturen als Form der Verletzung ist mit\ndem Kode S32.89 umfassend abgebildet, siehe hierzu Einleitung zum Kapitel S00-T98 der\nICD-10-GM.\nDer Begriff „Körperregion“ im Sinne der DKR wird durch die Klammererläuterung (T00-T07\nVerletzungen mit Beteiligung mehrerer Körperregionen ) konkretisiert. Aus dem Wortlaut\ndes Titels der Schlüsselnummer T02.1- Frakturen mit Beteiligung mehrerer Körperregionen,\nFrakturen mit Beteiligung von Thorax und Lumbosakralgegend oder von Thorax und\nBecken ist eindeutig ableitbar, was unter einer Körperregion im Sinne der ICD-10-GM zu\nverstehen ist.\n\nKommentierung FoKA:\nDissens (04.06.2018):\nIm Wortlaut der DKR 1911 steht: \"Die einzelnen Verletzungen werden, wann immer\nmöglich, entsprechend ihrer Lokalisation und ihrer Art so genau wie möglich kodiert.\"\nDer Begriff der Körperregion wird in der DKR dahingehend interpretiert, dass\nentsprechende Kodes nur zu verwenden sind, wenn die Zahl der maximal kodierbaren\nKodes überschritten würde.\nSomit sind bei einer Schmetterlingsfraktur die Kodes\nS32.81 Fraktur der Lendenwirbelsäule und des Beckens, Os ischium i.V.m.\nS32.5 Fraktur der Lenden wirbelsäule und des Beckens, Fraktur des Os pubis\nzur Abbildung der Verletzung zu nutzen.\nBei Widersprüchen zwischen der DKR und der ICD-10 hat die DKR Vorrang.\nDer Kode S32.89 ist für die Beschreibung einer Schmetterlingsfraktur etc. zudem weniger\nspezifisch als die Kodierung der einzelnen Frakturen, da der Begriff nicht im Klassentitel\nenthalten ist und der Kode auch wenig aufwendige sonstige Beckenfrakturen subsummiert.\nAktualisierung Kodierempfehlung SEG 4 vom 11.12.2019:\nDie Schlüsselnummer S32.89 ist zu verwenden. Es handelt sich um einen Kode, mit dem die\nFraktur spezifisch abbildbar ist, siehe hierzu Inklusiva zum Kode (u. a. Schmetterlingsbruch).\nDie Regelung der DKR 1911 Mehrfachverletzungen ist nicht anzuwenden. Unter einer\nMehrfachverletzung versteht man gleichzeitig entstandene Verletzungen mehrerer\nKörperregionen oder Organsysteme. Bei vorliegender Schmetterlingsfraktur handelt es sich\nnicht um unterschiedliche Verletzungen mehrerer Körperregionen, sondern um die\nVerletzung verschiedener Teile des Beckens. Das Becken ist als eine Körperregion zu\nverstehen. Dies ist aus der Regelung der DKR 1911 in Verbindung mit der Binnensystematik\nder ICD-10-GM ableitbar. Unterschiedliche Verletzungen einer Körperregion, die eine\ngetrennte Kodierung einzelner Verletzungen begründen, liegen bei einer\nSchmetterlingsfraktur nicht vor. Die mehrfachen Frakturen als Form der Verletzung ist mit\ndem Kode S32.89 umfassend abgebildet, siehe hierzu Einleitung zum Kapitel S00-T98 der\nICD-10-GM.\nDer Begriff „Körperregion“ im Sinne der DKR wird durch die Klammererläuterung (T00-T07\nVerletzungen mit Beteiligung mehrerer Körperregionen ) konkretisiert. Aus dem Wortlaut\ndes Titels der Schlüsselnummer T02.1- Frakturen mit Beteiligung mehrerer Körperregionen,\nFrakturen mit Beteiligung von Thorax und Lumbosakralgegend oder von Thorax und\nBecken ist eindeutig ableitbar, was unter einer Körperregion im Sinne der ICD-10-GM zu\nverstehen ist.\n\nFür Fälle ab 2019 gilt:\nDer Schmetterlingsbruch wurde in der ICD-10-GM, Version 2019, unter den Kode S32.7\nMultiple Frakturen mit Beteiligung der Lendenwirbelsäule und des Beckens verschoben. Die\nIntention dieser Änderung in Verbindung mit der Änderung in der DKR 1911 war, die\nKodierung der einzelnen Frakturen im Beckenbereich entsprechend ihrer Lokalisation und\nArt so genau wie möglich vorzunehmen, auch wenn es sich dabei sowohl nach der\nmedizinischen Definition als auch klassifikatorisch nur um eine Körperregion handelt.","pdfFile":"pdf/2020-09-30_KDE-589_Entscheidung-KDE-589-Schmetterlingsfraktur,-Beckenfraktur,-Mehrfachverletzung-.pdf-(49,92-kB).pdf","codes":{"icd":["S32.89","S32.81","S32.5","S00","T98","T00","T07","T02.1","S32.7"],"ops":[],"dkr":[]},"category":"kde"},{"decisionDate":"2020-10-28","publicationDate":"2020-10-06","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-47","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung und Begr&uuml;ndung KDE 47 Angina pectoris, Brustschmerz, Thoraxschmerz.pdf (151,2 kB)","sourceURL":"https://www.g-drg.de/content/download/10054/file/Entscheidung%20und%20Begr%C3%BCndung%20KDE%2047%20Angina%20pectoris,%20Brustschmerz,%20Thoraxschmerz.pdf","keywords":"Entscheidung und Begr&uuml;ndung KDE 47 Angina pectoris, Brustschmerz, Thoraxschmerz.pdf (151,2 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n28.10.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellte\nKodierempfehlung 47 (KDE) wie folgt mehrheitlich entschieden:\nEntscheidung KDE 47:\nDie Angina pectoris (I20- Angina pectoris ) ist unter der Gruppe Ischämische\nHerzkrankheiten (I20-I25) eingeordnet und ist ein Missverhältnis zwischen Sauerstoffbedarf\nund-Angebot im Herzen (Ischämie). Die Diagnose kann basierend auf den Kriterien der ESC\nLeitlinie¹ klinisch gestellt werden bei Vorliegen von mindestens 2 der folgenden Kriterien:\n-Retrosternale Schmerzen oder Schmerzen im Bereich von Hals, Kiefer, Schulter oder Arm;\nVoraussetzung ist, dass die Schmerzsymptomatik nicht auf andere in Frage kommende\nUrsachen zurückzuführen ist\n-Hervorgerufen durch körperliche Anstrengung\n-Besserung innerhalb von fünf Minuten durch Ruhe und/oder Nitrate.\n¹ ESC Guidelines for the diagnosis and management of chronic coronary syndromes\nBegründung:\nIn der Verhandlung vom 28.10.2020 ist der Schlichtungsausschuss mehrheitlich zu dem\nBeschluss gekommen, dass die Diagnose einer Angina pectoris auch klinisch getroffen\nwerden kann, da eine apparative Bestätigung der Diagnose nicht in allen\nFallkonstellationen möglich bzw. indiziert ist. Bezüglich der Anforderungen an eine\nklinische Diagnosestellung wird Bezug genommen auf die Leitlinie¹ der Europäischen\nGesellschaft für Kardiologie. Um eine konsistente Anwendung für den Kliniker zu\nermöglichen, wurde auch der Begriff der atypischen Angina für die Anforderungen zur\nKodierung berücksichtigt. Da es sich bei den im Beschluss aufgeführten Spiegelstrichen um\neine Nennung außerhalb des Zusammenhangs der Leitlinie handelt, wurde beim ersten\nSpiegelstrich als Voraussetzung ergänzt, dass die bei einem Fall konkret zu bewertende\nSymptomatik anhand der klinischen Anamnese und/oder durchgeführter Untersuchungen\nnicht auf andere Ursachen zurückzuführen ist.\n¹ ESC Guidelines for the diagnosis and management of chronic coronary syndromes\n\neingereichte Anträge für das Schlichtungsverfahren:\nAntrag des GKV-Spitzenverbandes:\nDie in der KDE 47 beschriebenen pectanginösen Beschwerden (Schmerz bzw. „Enge der\nBrust“) dürfen nur mit einem Kode aus I20.- (Angina pectoris ) kodiert werden, wenn als\nUrsache dafür ein Missverhältnis zwischen myokardialem Sauerstoffangebot und\nSauerstoffverbrauch (Ischämie) nachgewiesen ist.\nGegenantrag der Deutschen Krankenhausgesellschaft:\nDie Angina pectoris (120.- Angina pectoris ) (bzw. die pectanginösen Beschwerden) sind\nunter der Gruppe lschämische Herzkrankheiten (I20-I25) eingeordnet und stehen für ein\nMissverhältnis zwischen Sauerstoffbedarf und -angebot im Herzen.\nWird, wie in dem vorliegenden Fall (KDE-47), ein Patient aufgrund pectanginöser\nBeschwerden unter dem Verdacht auf eine koronare Herzkrankheit stationär behandelt\nund ergibt die kardiologische Diagnostik einschließlich Linksherzkatheteruntersuchung\nkeinen Hinweis auf eine kardiale Ursache kann die Angina pectoris als Hauptdiagnose\nkodiert werden, wenn mindestens 2 der folgenden Kriterien erfüllt sind¹:\n- Retrosternale Schmerzen oder im Bereich von Hals, Kiefer, Schulter oder Arm\n- hervorgerufen durch körperliche Anstrengung\n- Besserung innerhalb von fünf Minuten durch Ruhe und/oder Nitrate.\nSofern im Einzelfall die Diagnose Angina pectoris am Ende ei nes stationären Aufenthaltes\nweder sicher bestätigt noch sicher aus geschlossen werden kann, ist zusätzlich die DKR D008\nVerdachtsdiagnosen anzuwenden. lm Hinblick auf die dort geforderte, einzuleitende\nBehandlung, ist auch die Empfehlung einer bedarfsabhängigen Medikation für die\nKodierung der Verdachtsdiagnose ausreichend.\n1 Entsprechend der ESC Guidelines for the diagnosis and management of chronic coronary syndromes\n\nGültigkeit der Entscheidung:\nDiese Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser,\ndie Krankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.01.2021 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n25.11.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nRechtsbehelfsbelehrung:\nGegen diese Entscheidung des Schlichtungsausschusses kann innerhalb eines Monats nach\nBekanntgabe Klage beim Sozialgericht Berlin, Invalidenstr. 52, 10557 Berlin, schriftlich oder\nzu Protokoll des Urkundsbeamten der Geschäftsstelle erhoben werden.\nSiegburg, 25.11.2020\nDr. Franz Metzger\nVorsitzender des Schlichtungsausschusses nach § 19 KHG\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-47\nSchlagwort: Angina pectoris, Brustschmerz, Thoraxschmerz\nStand: 2007-01-10\nAktualisiert: 2008-01-08\nICD: R07.- R07.2\nProblem/Erläuterung:\nEin Patient wird mit pectanginösen Beschwerden unter Verdacht auf koronare\nHerzkrankheit aufgenommen. Die kardiologische Diagnostik einschließlich\nLinksherzkatheteruntersuchung ergibt keinen Hinweis auf eine kardiale Ursache\nRechtfertigt diese Symptomatik alleine die Kodierung der Angina pectoris als\nHauptdiagnose?\nKodierempfehlung SEG 4:\nNein. Die Definition der Angina pectoris umfasst nicht nur die Symptomatik (Schmerz bzw.\n„Enge der Brust“), sondern auch deren Genese (Missverhältnis zwischen myokardialem\nSauerstoffbedarf und Sauerstoffangebot: Ischämie). Entsprechend findet sich auch der ICD-\nKode im Kapitel I20 bis I25 Ischämische Herzkrankheiten .\nDie reine Symptomatik ohne Hinweis auf eine Ischämie ist entsprechend mit einem Kode\naus R07.- Hals- und Brustschmerzen (z.B. R07.2 Präkordiale Schmerzen ) zu verschlüsseln.\nKommentar FoKA:\nDissens:\nWir stimmen mit der Empfehlung der SEG 4 nicht überein, da:\n1. Angina pectoris ist eine klinische Diagnose. Sofern sie behandelt wurde, kann sie als\nHD kodiert werden (DKR D008b Verdachtsdiagnose )\n2. Auch eine kardiologische Diagnostik inkl. Linksherzkatheteruntersuchung kann eine\nischämische Ursache nicht ausschließen (z.B. Koronarspasmus)\nVerweis: siehe auch KDE-Nr. 65 und Nr. 172\nRückmeldung SEG 4:\nKein Anpassungsbedarf\nAktualisierung Kodierempfehlung SEG 4 vom 01.01.2019:\nNein. Die Definition der Angina pectoris umfasst nicht nur die Symptomatik (Schmerz bzw.\n„Enge der Brust“), sondern auch deren Genese (Missverhältnis zwischen myokardialem\n\nSauerstoffbedarf und Sauerstoffangebot: Ischämie). Entsprechend findet sich auch der ICD-\nKode im Kapitel I20 bis I25 Ischämische Herzkrankheiten .\nDie reine Symptomatik ohne Hinweis auf eine Ischämie ist entsprechend mit einem Kode\naus R07.- Hals- und Brustschmerzen (z.B. R07.2 Präkordiale Schmerzen ) zu verschlüsseln.\nSiehe auch Kodierempfehlung 172.","pdfFile":"pdf/2020-10-28_KDE-47_Entscheidung-und-Begr&uuml;ndung-KDE-47-Angina-pectoris,-Brustschmerz,-Thoraxschmerz.pdf-(151,2-kB).pdf","codes":{"icd":["I20","I25","R07","R07.2"],"ops":[],"dkr":["D008","D008b"]},"category":"kde"},{"decisionDate":"2020-10-28","publicationDate":"2020-10-15","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-309","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 309 Bandscheibenvorfall, Spinalkanalstenose, L&auml;hmung.pdf (47,08 kB)","sourceURL":"https://www.g-drg.de/content/download/9964/file/Entscheidung%20KDE%20309%20Bandscheibenvorfall,%20Spinalkanalstenose,%20L%C3%A4hmung.pdf","keywords":"Entscheidung KDE 309 Bandscheibenvorfall, Spinalkanalstenose, L&auml;hmung.pdf (47,08 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n28.10.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 309:\nWird ein Patient wegen Bandscheibenvorfällen und Spinalkanalstenose mit Radikulopathie\nC6/C7 und Parese des M. trizeps brachii im Krankenhaus operiert (Bandscheibenexzision,\nSpondylodese, Dekompression), kann die Trizepsparese mit dem Kode G83.2 Monoparese und\nMonoplegie einer oberen Extremität als Nebendiagnose kodiert werden.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.01.2021 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 11.11.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-309\nSchlagworte: Bandscheibenvorfall, Spinalkanalstenose, Lähmung\nStand: 22.10.2009\nAktualisiert: 01.01.2016\nICD: G83.88; M50.1; G55.1*\nProblem/Erläuterung:\nEin Patient wird wegen Bandscheibenvorfällen und Spinalkanalstenose mit Radikulopathie\nC6/C7 und Parese des M. trizeps brachii im Krankenhaus operiert (Bandscheibenexzision,\nSpondylodese, Dekompression). Kann als Nebendiagnose aufgrund der Trizepsparese auch\nG83.88 (ab 2016 G83.8) Sonstige näher bezeichnete Lähmungssyndrome angegeben\nwerden?\nKodierempfehlung SEG 4:\nBei der Versicherten lag ein mit dem ICD-Kode G83.88 (ab 2016 mit dem ICD-Kode G83.8) zu\nverschlüsselndes \"sonstiges Lähmungssyndrom\" nicht vor, sondern eine motorische und\nsensible radikuläre Symptomatik C6/C7 infolge von Bandscheibenvorfällen und\nSpinalkanalstenose in dieser Höhe entsprechend dem ICD-Kode M50.1 Zervikale\nBandscheibenschäden, Zervikaler Bandscheibenschaden mit Radikulopathie in Verbindung\nmit G55.1* Kompression von Nervenwurze ln und Nervenplexus bei Bandscheibenschäden .\nMit diesen beiden ICD-Kodes, ggf. in Verbindung mit dem Kode M48.02 Sonstige\nSpondylopathien, Spinal(kanal)stenose, Zervikalbereich ist das Krankheitsbild spezifisch\nbeschrieben.\nAbgesehen davon erfüllt die - von der Hauptdiagnose erfasste - Trizepsparese nicht die\nKriterien für die Kodierung als Nebendiagnose nach DKR D003.\nKommentierung FoKA:\nDissens (aktualisiert am 27.01.2014):\nEine Radikulopathie infolge eines Bandscheibenvorfalls kann unterschiedliche Symptome\nwie Schmerzen, Sensibilitätsstörungen und motorische Lähmungen verursachen. Sowohl zur\nvollständigen Abbildung des Krankheitsbildes als auch angesichts des zusätzlichen\nRessourcenverbrauchs (z.B. EMG, Physiotherapie, Schmerztherapie etc.) entspricht die\nMehrfachkodierung den Vorgaben in den DKR D003i und D012i, Beispiel 7.\nEine spezifische Kodierung der M. trizeps-Parese kann mit dem Kode G83.2 Monoparese\nund Monoplegie einer oberen Extremität erfolgen. In den Hinweisen zum ICD-Dreisteller\nG83 ist vermerkt: \"Diese Kategorie dient auch zur multiplen Verschlüsselung, um diese\ndurch eine beliebige Ursache hervorgerufenen Krankheitszustände zu kennzeichnen.\"\n\nRückmeldung SEG 4:\nRückmeldung steht noch aus.\nAktualisierung Kodierempfehlung SEG 4 vom 01.01.2019:\nBei dem Patienten lag ein mit dem ICD-Kode G83.88 (ab 2016 mit dem ICD-Kode G83.8) zu\nverschlüsselndes \"sonstiges Lähmungssyndrom\" nicht vor, sondern eine motorische und\nsensible radikuläre Symptomatik C6/C7 infolge von Bandscheibenvorfällen und\nSpinalkanalstenose in dieser Höhe entsprechend dem ICD-Kode M50.1 Zervikale\nBandscheibenschäden, Zervikaler Bandscheibenschaden mit Radikulopathie in Verbindung\nmit G55.1* Kompression von Nervenwurzeln und Nervenplexus bei Bandscheibenschäden\n(M50-M51†). Mit diesen beiden ICD-Kodes, ggf. in Verbindung mit dem Kode M48.02\nSonstige Spondylopathien, Spinal(kanal)stenose, Zervikalbereich ist das Krankheitsbild\nspezifisch beschrieben. Abgesehen davon erfüllt die – von der Hauptdiagnose erfasste –\nTrizepsparese nicht die Kriterien für die Kodierung als Nebendiagnose nach DKR D003.","pdfFile":"pdf/2020-10-28_KDE-309_Entscheidung-KDE-309-Bandscheibenvorfall,-Spinalkanalstenose,-L&auml;hmung.pdf-(47,08-kB).pdf","codes":{"icd":["G83.2","G83.88","M50.1","G55.1","G83.8","M48.02","G83","M50","M51"],"ops":[],"dkr":["D003","D003i","D012i"]},"category":"kde"},{"decisionDate":"2020-10-28","publicationDate":"2020-07-21","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-354","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 354 Stent, Einlage, fehlgeschlagen.pdf (46 kB)","sourceURL":"https://www.g-drg.de/content/download/9965/file/Entscheidung%20KDE%20354%20Stent,%20Einlage,%20fehlgeschlagen.pdf","keywords":"Entscheidung KDE 354 Stent, Einlage, fehlgeschlagen.pdf (46 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n28.10.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 354:\nWird bei einem Patienten während einer Koronarangiographie bei Drei-Gefäßerkrankung eine\nRIVA-Stenose aufgedehnt und dann ein medikamentenfreisetzender Stent eingelegt,\nanschließend versucht eine weitere Einengung distal des Stents mit einem zweiten\nmedikamentenfreisetzenden Stent zu versorgen, dies jedoch nicht gelingt, weil sich der Stent an\neiner Gefäßbiegung verhakt, so dass der Stent verworfen wird, ist gemäß Ziffer 4 der DKR P004\nNicht vollendete oder unterbrochene Prozedur auch der verworfene Stent bei der Kodierung der\nzutreffenden Kodes aus 8-837.m- Einlegen eines medikamentenfreisetzenden Stents und aus 8-\n83b.0- Zusatzinformationen zu Materialien, Art der medikamentenfreisetzenden Stents oder\nOPD-Systeme zu berücksichtigen. In dem Fall (KDE-354) ist das Einlegen der Stents daher mit\ndem Kode 8-837.m1 Einlegen eines medikamentenfreisetzenden Stents, 2 Stents in eine\nKoronararterie zu kodieren. Für die Art der medikamentenfreisetzenden Stents sind die zwei\nsechsstelligen Kodes aus dem OPS 8-83b.0- Art des medikamentenfreisetzenden Stents zu\nkodieren.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.01.2021 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 11.11.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-354\nSchlagworte: Stent, Einlage, fehlgeschlagen\nStand: 2010-08-17\nAktualisiert: 01.01.2019\nOPS: 8-837.m; 8-83b.0; 5-995;\nProblem/Erläuterung:\nWährend einer Koronarangiographie bei Drei-Gefäßerkrankung wird eine RIVA-Stenose\naufgedehnt und dann ein medikamentenfreisetzender Stent eingelegt. Anschließend wird\nversucht, eine weitere Einengung distal des Stents mit einem zweiten\nmedikamentenfreisetzenden Stent zu versorgen. Dies gelingt nicht, weil sich der Stent an\neiner Gefäßbiegung verhakt. Der Stent wird verworfen. Ist die Stenteinlage mit\n8-837.m0 Einlegen eines medikamentenfreisetzenden Stents, ein Stent in eine\nKoronararterie\noder\n8.837.m1 Einlegen eines medikamentenfreisetzenden Stents, 2 Stents in eine Koronararterie\nzu verschlüsseln?\nIst der Schlüssel 8-83b.0 Zusatzinformationen zu Materialien, Art des\nmedikamentenfreisetzenden Stents ein- oder zweimal anzugeben?\nKodierempfehlung SEG 4:\nZu verschlüsseln ist 8-837.m1 Einlegen eines medikamentenfreisetzenden Stents, 2 Stents in\neine Koronararterie . Gemäß DKR P004, Punkt 4 ist die Prozedur nahezu vollständig erbracht\nund wird daher ohne Zusatzkode 5-995 kodiert. Die Angabe des Schlüssels 5-995 Vorzeitiger\nAbbruch einer Operation (Eingriff nicht komplett durchgeführt) scheidet hier auch deshalb\naus, da keine Operation, sondern eine Maßnahme aus Kapitel 8 (Nichtoperative\ntherapeutische Maßnahmen) durchgeführt wurde.\nDer Schlüssel 8-83b.0 Zusatzinformationen zu Materialien, Art des\nmedikamentenfreisetzenden Stents ist allerdings nur einmal anzugeben, da diese\nZusatzinformation nur für implantierte Stents anzugeben ist (siehe Hinweis im OPS).\nKommentierung FoKA:\nDissens: Die Einträge im OPS-Katalog stehen zueinander im Widerspruch.\nGemäß der Hinweise zum OPS 8-837.m* ist die Angabe des Materials obligat anzuwenden\n(Hinw.: Die Art der medikamentenfreisetzenden Stents ist gesondert zu kodieren (8-83b.0\nff.)). Wenn somit für den primären Kode die Kodierbarkeit in Übereinstimmung mit den\nDKR anerkannt wird, ist auch der abhängige Materialkode anzugeben.\n\nRückmeldung SEG 4:\nLaut OPS ist der Zusatzkode nur für implantierte Stents anzugeben. Deshalb kein\nÄnderungsbedarf.","pdfFile":"pdf/2020-10-28_KDE-354_Entscheidung-KDE-354-Stent,-Einlage,-fehlgeschlagen.pdf-(46-kB).pdf","codes":{"icd":[],"ops":["8-837.m","8-837.m1","8-83b.0","5-995","8-837.m0"],"dkr":["P004"]},"category":"kde"},{"decisionDate":"2020-10-28","publicationDate":"2020-12-16","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-386","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 386 Anastomositis.pdf (45,5 kB)","sourceURL":"https://www.g-drg.de/content/download/9966/file/Entscheidung%20KDE%20386%20Anastomositis.pdf","keywords":"Entscheidung KDE 386 Anastomositis.pdf (45,5 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n28.10.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des PKV-Verbandes\nwie folgt entschieden:\nEntscheidung KDE 386:\nWird ein Patient wegen einer Anastomositis an einer gastrojejunalen Anastomose bei zurückliegender\nBillroth II Operation (Operation vor drei Jahren) und mit Ulcera im Jejunum behandelt, ist dies mit den\nnachfolgend zutreffenden Kodes oder Kodes aus\nK29.6 Sonstige Gastritis\nK28.- Ulcus pepticum jejuni\nK52.9 Nichtinfektiöse Gastroenteritis und Kolitis, nicht näher bezeichnet\nK91.88 Sonstige Krankheiten des Verdauungssystems nach medizinischen Maßnahmen, andernorts\nnicht klassifiziert\nzu kodieren.\nDer Kode K91.88 Sonstige Krankheiten des Verdauungssystems nach medizinischen Maßnahmen,\nandernorts nicht klassifiziert dient der Kodierung der Anastomositis und stellt gleichzeitig den\nZusammenhang zwischen der Anastomositis und der vorangegangenen Billroth II-Operation her.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.01.2021 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 11.11.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\n\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-386\nSchlagwort: Anastomositis\nStand: 2011-04-12\nAktualisiert: 01.01.2019\nICD: T81.8; K29.6; K52.9\nProblem/Erläuterung:\nBei einem Patienten mit einem Billroth II - Magen (Operation vor drei Jahren) wird\ngastroskopisch eine Anastomositis an der gastrojejunalen Anastomose mit Ulcera im\nJejunum beschrieben. Können hier als Nebendiagnose der ICD-Kode T81.8 Sonstige\nKomplikationen bei Eingriffen, anderenorts nicht klassifiziert oder der ICD-Kode K91.88\nSonstige Krankheiten des Verdauungssystems nach medizinischen M aßnahmen ,\nanderenorts nicht klassifiziert angegeben werden?\nKodierempfehlung SEG 4:\nEin spezifischer Kode für eine Anastomositis existiert nicht. Da hier morphologisch neben\nden Ulcera eine Gastritis und eine Enteritis vorlagen, sind folgende Kodes, da spezifischer\nals die oben genannten, zu verwenden:\nK29.6 Sonstige Gastritis ,\nK28.9 Ulcus pepticum jejuni, weder als akut noch chr onisch bezeichnet, ohne Blutung oder\nPerforation und\nK52.9 Nichtinfektiöse Gastroenteritis und Kolitis, nicht näher bezeichnet .\nKommentierung FoKA:\nDissens:\nEs sind zwar die vom MDK vorgeschlagenen Kodes zu benutzen, jedoch in einer\nKombination mit K91.88 um den Zustand möglichst spezifisch zu beschreiben.\nDer Suchbegriff \"Anastomositis\" wird zwar im alphabetischen Verzeichnis unter dem Kode\nT81.4 aufgeführt, jedoch beschreibt dieser eine \"Infektion nach einem Eingriff, anderenorts\nnicht klassifiziert\". Gemäß DKR D014 ist grundsätzlich die systematische Einordnung eines\nalphabetischen Kodes zu überprüfen, da nur der systematische Katalog maßgeblich für die\nKodierung ist.\nRückmeldung SEG 4\nKein Änderungsbedarf (27.08.2015)","pdfFile":"pdf/2020-10-28_KDE-386_Entscheidung-KDE-386-Anastomositis.pdf-(45,5-kB).pdf","codes":{"icd":["K29.6","K28","K52.9","K91.88","T81.8","K28.9","T81.4"],"ops":[],"dkr":["D014"]},"category":"kde"},{"decisionDate":"2020-10-28","publicationDate":"2020-08-19","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-393","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 393 Magenblutung, Teerstuhl.pdf (213,73 kB)","sourceURL":"https://www.g-drg.de/content/download/9967/file/Entscheidung%20KDE%20393%20Magenblutung,%20Teerstuhl.pdf","keywords":"Entscheidung KDE 393 Magenblutung, Teerstuhl.pdf (213,73 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n28.10.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 393:\nWird ein Patient zwei Tage nach endoskopischer Polypektomie am Magen mit Teerstuhl stationär\naufgenommen und wird die Polypabtragungsstelle als ursächlich für die Blutung festgestellt, ist der\nKode K92.2 Gastrointestinale Blutung, nicht näher bezeichnet als Hauptdiagnose anzugeben.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.01.2021 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 11.11.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-393\nSchlagwort: Magenblutung, Teerstuhl\nStand: 16.06.2011\nAktualisiert: 01.01.2016\nICD: K92.2; Y84.9!; T81.0\nProblem/Erläuterung:\nZwei Tage nach endoskopischer Polypektomie am Magen wird ein Patient mit Teerstuhl\nstationär aufgenommen. Ursächlich wird eine Blutung aus der Polypabtragungsstelle\nfestgestellt. Was ist die Hauptdiagnose?\nK92.2 Gastrointestinale Blutung, nicht näher bezeichnet\noder\nT81.0 Blutung und Hämatom al s Komplikation eines Eingriffs, anderenorts nicht\nklassifiziert .\nKodierempfehlung SEG 4:\nK92.2 Gastrointestinale Blutung, nicht näher bezeichnet ist als Hauptdiagnose zu\nverschlüsseln, optional mit Y84.9! Zwischenfälle durch medizinische Maßnahmen, nich t\nnäher bezeichnet als Nebendiagnose. K92.2 ist der spezifische Kode in Bezug auf die\nErkrankung.\nKommentierung FoKA:\nDissens:\nDie korrekte Kodierung ist die Kombination aus K92.2 und T81.0. Diese bildet den\nSachverhalt im Rahmen der Ätiologie/Manifestation-Verschlüsselung am treffendsten ab.\nY84.9! kann gemäß 012 ergänzend zur T81.0 kodiert werden.\nRückmeldung SEG 4:\nEine Kodierung der Ätiologie erfolgt nach den DKR nur im Kreuz-Stern-System. (27.08.2015)\nAktualisierung Kodierempfehlung SEG 4 vom 01.01.2019:\nK92.2 Gastrointestinale Blutung, nicht näher bezeichnet ist als Hauptdiagnose zu\nverschlüsseln, optional mit Y84.9! Zwischenfälle durch medizinische Maßnahmen, nicht\nnäher bezeichnet als Nebendiagnose. K92.2 ist der spezifische Kode in Bezug auf die\nErkrankung.\nSiehe auch Kodierempfehlung 559.","pdfFile":"pdf/2020-10-28_KDE-393_Entscheidung-KDE-393-Magenblutung,-Teerstuhl.pdf-(213,73-kB).pdf","codes":{"icd":["K92.2","Y84.9","T81.0"],"ops":[],"dkr":[]},"category":"kde"},{"decisionDate":"2020-10-28","publicationDate":"2020-08-19","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-404","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 404 Strahlenschutzschiene, Abformung, Bestrahlungsvorbereitung.pdf (46,88 kB)","sourceURL":"https://www.g-drg.de/content/download/9968/file/Entscheidung%20KDE%20404%20Strahlenschutzschiene,%20Abformung,%20Bestrahlungsvorbereitung.pdf","keywords":"Entscheidung KDE 404 Strahlenschutzschiene, Abformung, Bestrahlungsvorbereitung.pdf (46,88 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n28.10.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 404:\nWird bei einem Patienten während des stationären Krankenhausaufenthaltes durch\nLaserresektion ein Zungenkarzinom lokal in sano entfernt und eine Neck dissection links\ndurchgeführt sowie eine adjuvante Radiatio geplant (der Patient soll sich 12 Tage nach\nEntlassung zum Planungs-CT vorstellen) und wird der Patient während des aktuellen\nAufenthaltes dem Mund-Kiefer-Gesichtschirurgen zur \"Abformung\" von Oberkiefer und\nUnterkiefer für die spätere Anfertigung einer Strahlenschutzschiene vorgestellt, die\nStrahlenschutzschienen jedoch weder während des stationären Aufenthaltes noch danach vom\nKrankenhaus angefertigt, ist für die Abformung von Ober- und Unterkiefer in diesem Fall (KDE-\n404) der OPS 8-527.6 Konstruktion und Anpassung von Fixations- und Behandlungshilfen bei\nStrahlentherapie, Behandlungshilfen nicht zu kodieren.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.01.2021 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 11.11.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-404\nSchlagwort: Strahlenschutzschiene, Abformung, Bestrahlungsvorbereitung\nStand: 16.08.2011\nAktualisiert: 11.12.2019\nOPS: 8-527.6\nProblem/Erläuterung:\nBei einem Patienten wird während des stationären Krankenhausaufenthaltes durch\nLaserresektion ein Zungenkarzinom lokal in sano entfernt und es erfolgt eine Neck\ndissection links. Es ist nun eine adjuvante Radiatio geplant. Während des aktuellen\nAufenthaltes wird der Patient dem Mund-Kiefer-Gesichtschirurgen vorgestellt, welcher eine\n\"Abformung\" von Oberkiefer und Unterkiefer für die spätere Anfertigung einer\nStrahlenschutzschiene vornimmt.\nDie Strahlenschutzschienen werden weder während des stationären Aufenthaltes noch\nnachstationär innerhalb der OGVD angefertigt. Der Patient soll sich 12 Tage nach\nEntlassung zum Planungs-CT vorstellen.\nIst die Kodierung des OPS 8-527.6 Konstruktion und Anpassung von Fixations- und\nBehandlungshilfen bei Strahlentherapie, Behandlungshilfen korrekt?\nKodierempfehlung SEG 4:\nWährend des stationären Aufenthaltes erfolgte weder die Konstruktion noch die\nAnpassung einer Fixations- oder Behandlungshilfe. Die Anfertigung eines Kieferabdruckes\nist im OPS-Katalog nicht abbildbar und daher nicht zu kodieren.\nKommentierung FoKA:\nDissens:\nFür die Bewertung des Problems sind sowohl die Kodierrichtlinien als auch\ngesundheitsökonomische Überlegungen zu berücksichtigen. Eine pauschalierte Ablehnung\nder Kodierung als Hebel zur Steuerung der Vergütung erscheint insofern nicht\ngerechtfertigt. Zu vermeiden ist sowohl eine Doppelvergütung als auch eine fehlende\nVergütung der Herstellung der Strahlenschutzschiene.\nSämtliche am Patienten durchzuführenden Schritte sind während des stationären\nAufenthaltes durchgeführt worden. Die Herstellung der Schiene wäre sowieso\npatientenfern erfolgt, unabhängig, ob er sich zu diesem Zeitpunkt selber noch im\nKrankenhaus befindet oder nicht.\nBei einem späteren Aufenthalt ist der Kode (ohne erneute Anpassung) jedoch nicht mehr zu\nkodieren.\nGemäß DKR P005 liegt das Datum der ersten Leistung im Zusammenhang zur Erstellung der\nSchiene im stationären Aufenthalt.\n\nErgänzend sind folgende Fragen zu berücksichtigen:\n* Wer hat die Erstellung der Strahlenschutzschiene veranlasst (z.B. Krankenhaus oder\nniedergelassener Strahlentherapeut)?\n* Wem wird die Leistung des Mund-Kiefer-Gesichtschirurgen in Rechnung gestellt\n(Krankenhaus oder Krankenkasse)?\n* Wird diese Leistung durch die Krankenkassen gegenüber Dritten vergütet oder wird die\nHerstellung der Strahlenschutzschiene dem Krankenhaus in Rechnung gestellt?\nRückmeldung SEG 4:\nDie im OPS-Kode beschriebene Leistung ist nicht erbracht worden. (27.08.2015)","pdfFile":"pdf/2020-10-28_KDE-404_Entscheidung-KDE-404-Strahlenschutzschiene,-Abformung,-Bestrahlungsvorbereitung.pdf-(46,88-kB).pdf","codes":{"icd":[],"ops":["8-527.6"],"dkr":["P005"]},"category":"kde"},{"decisionDate":"2020-10-28","publicationDate":"2020-11-11","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-410","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 410 Scheidenstumpffixation, Hysterektomie, vaginale.pdf (154,23 kB)","sourceURL":"https://www.g-drg.de/content/download/9969/file/Entscheidung%20KDE%20410%20Scheidenstumpffixation,%20Hysterektomie,%20vaginale.pdf","keywords":"Entscheidung KDE 410 Scheidenstumpffixation, Hysterektomie, vaginale.pdf (154,23 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n28.10.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 410:\nDie Frage, ob der Kode 5-704.43 in dem genannten Fall (KDE-410) zusätzlich kodiert werden\ndarf, kann nicht beantwortet werden, da der Kode nicht mehr existiert und im OPS der Kode-\nBereich zur Abbildung von Scheidenstumpffixationen umstrukturiert wurde. Ob und welcher Kode\nfür eine Scheidenstumpffixation zu verwenden ist, ergibt sich aus den einschlägigen Regelungen\nder DKR und den entsprechenden Kodes und Hinweisen im OPS.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.01.2021 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 11.11.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE 410\nSchlagwort: Scheidenstumpffixation, Hysterektomie, vaginale\nStand: 2011-08-16\nAktualisiert: 01.01.2016\nOPS: 5-704.43\nProblem/Erläuterung:\nBei einer vaginalen Hysterektomie werden eine hohe Peritonealisierung und\nScheidenecknähte als prophylaktische Maßnahme durchgeführt. Darf in diesem Fall\nzusätzlich 5-704.43 Scheidenstumpffixation, vaginal verschlüsselt werden?\nKodierempfehlung SEG 4:\nIn diesen Fällen ist die Prozedur 5-704.43 nicht zusätzlich zu kodieren, da sie Bestandteil der\nvaginalen Hysterektomie ist.\nVoraussetzung für die zusätzliche Kodierung ist, dass sie nicht im Rahmen des\nWundverschlusses durchgeführt wird, sondern eine zusätzliche Präparation erforderlich ist\nwie z.B. bei der Sacrospinalen Fixation nach Amreich und Richter bei\nProlapshysterektomien.\nAb 2016 ist das operative Vorgehen bei Scheidenstumpffixationen nach der Art des\nZuganges, der Art der Fixation und der Verwendung von alloplastischem Material\nabbildbar.\nKommentierung FoKA:\nDissens:\nDer alleinige Wundverschluß im Rahmen der vaginalen Hysterektomie kann die zusätzliche\nKodierung von 5-704.43 Scheidenstumpffixation, vaginal nicht begründen.\nWenn es sich hier um eine Erweiterung des Eingriffes mit anderer therapeutischer Intention\nhandelt, ist die Kodierung der Scheidenstumpffixation zusätzlich anzugeben. Über die\nKodierbarkeit ist nur im Einzelfall anhand des OP-Berichtes zu entscheiden. Die Auswahl des\nangewandten OP-Verfahrens ist hierbei unerheblich.\nRückmeldung SEG 4:\nEin Dissens ist aus der Kommentierung nicht ableitbar. (27.08.2015)\nAktualisierung Kodierempfehlung SEG 4 vom 01.01.2019:\nIn diesen Fällen ist die Prozedur 5-704.43 nicht zusätzlich zu kodieren, da sie Bestandteil der\nvaginalen Hysterektomie ist.\n\nVoraussetzung für die zusätzliche Kodierung ist, dass sie nicht im Rahmen des\nWundverschlusses durchgeführt wird, sondern eine zusätzliche Präparation erforderlich ist\nwie z. B. bei der Sacrospinalen Fixation nach Amreich und Richter bei\nProlapshysterektomien.\nFür Fälle ab 2016 ist das operative Vorgehen bei Scheidenstumpffixationen nach der Art des\nZuganges, der Art der Fixation und der Verwendung von alloplastischem Material\nabbildbar.\nFür Fälle ab 2018 findet sich unter der Kategorie 5-68 Inzision, Exzision und Extirpation des\nUterus und der Prozedur 5-704 Operationen an Vagina und Douglasraum, Vaginale\nKolporrhaphie und Beckenbodenplastik der Hinweis: Die Durchführung einer spezifischen\nScheidenstumpffixation im Rahmen einer Vorder- und/oder Hinterwandplastik ist gesondert\nzu kodieren (5-704.46 bis 5-704.4p). Die Kodierung einer spezifischen\nScheidenstumpffixation setzt voraus, dass eine Prozedur aus 5-704.46 bis 5-704.4p inhaltlich\noperativ erbracht wurde.","pdfFile":"pdf/2020-10-28_KDE-410_Entscheidung-KDE-410-Scheidenstumpffixation,-Hysterektomie,-vaginale.pdf-(154,23-kB).pdf","codes":{"icd":[],"ops":["5-704.43","5-68","5-704","5-704.46","5-704.4p"],"dkr":[]},"category":"kde"},{"decisionDate":"2020-10-28","publicationDate":"2020-11-11","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-428","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung und Begr&uuml;ndung KDE 428 Seelsorger, Palliativmedizin.pdf (143,69 kB)","sourceURL":"https://www.g-drg.de/content/download/10055/file/Entscheidung%20und%20Begr%C3%BCndung%20KDE%20428%20Seelsorger,%20Palliativmedizin.pdf","keywords":"Entscheidung und Begr&uuml;ndung KDE 428 Seelsorger, Palliativmedizin.pdf (143,69 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n28.10.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellte\nKodierempfehlung (KDE) 428 mehrheitlich wie folgt entschieden:\nEntscheidung KDE 428:\nDie von einem Seelsorger/ einer Seelsorgerin erbrachten Leistungen sind nicht im Rahmen\nder OPS-Kodes 8-982 Palliativmedizinische Komplexbehandlung und 8-98e Spezialisierte\nstationäre palliativmedizinische Komplexbehandlung bei der Ermittlung der pro Patient\nerbrachten Leistungen/Therapiezeit zu berücksichtigen\nBegründung:\nUnter Berücksichtigung der vorgebrachten Überlegungen hinsichtlich der Finanzierung von\nSeelsorgeleistungen über die Gemeinkosten eines Krankenhauses bzw. durch andere\nKostenträger, der Heterogenität des Begriffs der Seelsorge, eines potenziellen\nVerdrängungseffektes zu Lasten der in den Mindestmerkmalen des OPS genannten\nBerufsgruppen sowie einer konsistenten Anwendung des Begriffs des palliativmedizinischen\nBehandlungsteams im OPS ist der Schlichtungsausschuss mehrheitlich zu dem Ergebnis\ngekommen, dass die von einem Seelsorger/einer Seelsorgerin erbrachten Leistungen nicht\nzu berücksichtigen sind.\n\neingereichte Anträge für das Schlichtungsverfahren:\nAntrag der Deutschen Krankenhausgesellschaft:\nDie durch einen Seelsorger z. B. im Rahmen der OPS-Kodes 8-982 Palliativmedizinische\nKomplexbehandlung , 8-98e Spezia l isierte stationäre palliativmedizinische\nKomplexbehandlung und 8-98h Spezia l isierte palliativmedizinische Komplexbehandlung\ndurch einen Palliativdienst erbrachten Leistungen sind bei der Ermittlung der pro Patient\nerbrachten Leistungen/Zeiten zu berücksichtigen.\nGegenantrag des GKV-Spitzenverbandes:\nDie von einem Seelsorger/einer Seelsorgerin erbrachten Leistungen sind keine Leistungen\nder Krankenversicherung und nicht im Rahmen der OPS-Kodes 8-982 Palliativmedizinische\nKomplexbehandlung und 8-98e Spezialisierte stationäre p alliativmedizinische\nKomplexbehandlung bei der Ermittlung der pro Patient erbrachten Leistungen/Therapiezeit\nzu berücksichtigen.\nGültigkeit der Entscheidung:\nDiese Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser,\ndie Krankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.01.2021 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n25.11.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nRechtsbehelfsbelehrung:\nGegen diese Entscheidung des Schlichtungsausschusses kann innerhalb eines Monats nach\nBekanntgabe Klage beim Sozialgericht Berlin, Invalidenstr. 52, 10557 Berlin, schriftlich oder\nzu Protokoll des Urkundsbeamten der Geschäftsstelle erhoben werden.\nSiegburg, 25.11.2020\nDr. Franz Metzger\nVorsitzender des Schlichtungsausschusses nach § 19 KHG\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-428\nSchlagwort: Seelsorger, Palliativmedizin\nStand:\nAktualisiert: 01.01.2017\nOPS: 8-982 8-98e\nProblem/Erläuterung:\nKönnen die durch einen Seelsorger erbrachten Leistungen z.B. bei den OPS-Komplexkodes\n8-982 Palliativmedizinische Komplexbehandlung\nund\n8-98e Spezialisierte stationäre palliativmedizinische Komplexbehandlung für die\nTherapiezeit berücksichtigt werden?\nKodierempfehlung SEG-4:\nDie Patienten-, Angehörigen- und/oder Familiengespräche können von allen Berufsgruppen\ndes Behandlungsteams durchgeführt werden. Der Seelsorger gehört nicht zur Gruppe der\nTherapeuten/Behandler. Somit sind die Leistungen eines Seelsorgers nicht bei der\nTherapiezeit zu berücksichtigen.\nAb 2017 gilt dies auch für den OPS-Komplexkode 8-98h Spezialisierte palliativmedizinische\nKomplexbehandlung durch einen Palliativdienst .\nKommentierung FoKA:\nDissens:\ndefiniert.\nFachliche Inhalte von prozeduralen Leistungen werden vorrangig durch Fachgesellschaften\nDurch die Deutsche Gesellschaft für Palliativmedizin e.V. (DGP) als zuständige\nFachgesellschaft wurde eine Stellungnahme veröffentlicht:\n\"... Im Unterschied zum herkömmlichen Verständnis der Krankenhausseelsorge - als von der\nBehandlung unabhängiges, ergänzendes Angebot - übernimmt die Seelsorge im\nPalliativkontext anteilige Verantwortung am Therapieplan. Dies geschieht durch gezielte\nIdentifikation von spirituellen Belastungsfaktoren und Ressourcen. Ziel ist die Einbeziehung\nder spirituellen und existentiellen Dimension von Leid und Lebensqualität in die\nmultimodale Therapieplanung. Adressaten sind dabei Patienten und Ange- hörige sowie\ndas gesamte Team. Die Selbstverständlichkeit der Einbindung der Seelsorge zeigt sich in der\nTeilnahme an multiprofessionellen Fall- und multidisziplinären Teambesprechungen und\n\nTeamsupervision. Dokumentation von Leistungen erfolgt dabei selbstverständlich unter\nWahrung des Seelsorgegeheimnisses in der Patientendokumentation. ...\"\nDer FoKA schließt sich dieser Stellungnahme an und hält deshalb die Anrechnung\nseelsorgerischer Gesprächszeiten auf die im OPS geforderten Therapieminuten für\ngerechtfertigt.\nRückmeldung SEG 4\nIm OPS-Kode ist die Seelsorge nicht in den Mindestmerkmalen zu den Therapiebereichen\nenthalten. (27.08.2015)\nAktualisierung Kodierempfehlung SEG 4 vom 01.01.2019:\nDie Patienten-, Angehörigen- und/oder Familiengespräche können von allen Berufsgruppen\ndes Behandlungsteams durchgeführt werden. Der Seelsorger gehört nicht zur Gruppe der\nTherapeuten. Somit sind die Leistungen eines Seelsorgers nicht bei der Therapiezeit zu\nberücksichtigen.\nFür Fälle ab 2017 gilt dies auch für den OPS-Komplexkode 8-98h Spezialisierte\npalliativmedizinische Komplexbehandlung durch einen Palliativdi enst.","pdfFile":"pdf/2020-10-28_KDE-428_Entscheidung-und-Begr&uuml;ndung-KDE-428-Seelsorger,-Palliativmedizin.pdf-(143,69-kB).pdf","codes":{"icd":[],"ops":["8-982","8-98e","8-98h"],"dkr":[]},"category":"kde"},{"decisionDate":"2020-10-28","publicationDate":"2020-10-06","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-562","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 562 SIB, Simultan Integrierter Boost.pdf (46,34 kB)","sourceURL":"https://www.g-drg.de/content/download/9970/file/Entscheidung%20KDE%20562%20SIB,%20Simultan%20Integrierter%20Boost.pdf","keywords":"Entscheidung KDE 562 SIB, Simultan Integrierter Boost.pdf (46,34 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n28.10.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 562:\nGemäß OPS 8-52 Strahlentherapie ist jede Fraktion einer Strahlentherapie einzeln zu kodieren.\nEine Fraktion umfasst alle Einstellungen und Bestrahlungsfelder für die Bestrahlung eines\nZielvolumens. Ein Zielvolumen ist das Körpervolumen, welches ohne Patientenumlagerung oder\nTischverschiebung über zweckmäßige Feldanordnungen erfasst und mit einer festgelegten Dosis\nnach einem bestimmten Dosiszeitmuster bestrahlt werden kann.\nIn dem vorliegenden Fall (KDE-562), in dem bei der Patientin mit Mammakarzinom während der\nstrahlentherapeutischen Behandlung der Drüsenkörper mit simultan integriertem Boost (SIB)\neine höhere Dosis im Boostgebiet erfährt, die Patientin für die eine Sitzung aber nur einmal\ngelagert wird und nur eine Dosisverteilung erzielt wird, ist der Boost in diesem Fall nicht\ngesondert zu kodieren, da der Aufwand pro Bestrahlungssitzung dem bei der Bestrahlung eines\nZielvolumens entspricht.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.01.2021 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 11.11.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE 562\nSchlagworte: SIB, Simultan Integrierter Boost\nErstellt: 25.08.2016\nAktualisiert: 01.01.2019\nProblem/Erläuterung:\nEine strahlentherapeutische Behandlung bei Mammakarzinom erfolgt mit simultan\nintegriertem Boost (SIB), d.h., dass der Drüsenkörper eine unterschiedliche Dosis während\nder Bestrahlung erhält, nämlich eine höhere im Boostgebiet. Die Patientin wird einmal\ngelagert, es wird nur eine unterschiedliche Dosisverteilung erzielt.\nVor Anwendung des SIB erfolgte die Boostbestrahlung klassischerweise im Anschluss an die\nBestrahlung des primären Zielvolumens im Rahmen einer zweiten Strahlentherapeutischen\nSitzung mit Umlagerung.\nWie ist die Bestrahlung mit SIB zu kodieren?\nKodierempfehlung SEG 4:\nJede Fraktion einer Strahlentherapie ist einzeln zu kodieren. Eine Fraktion umfasst alle\nEinstellungen und Bestrahlungsfelder für die Bestrahlung eines Zielvolumens. Da das\nZielvolumen das Körpervolumen ist, das ohne Patientenumlagerung oder Tischverschiebung\nmit festgelegter Dosis nach einem bestimmten Dosiszeitmuster bestrahlt werden kann, ist\ndie Bestrahlung mit SIB mit nur einem OPS-Kode zu verschlüsseln. Ein spezifischer OPS-\nKode, der die spezielle Dosis-Zeitverteilung (Boost) im Zielvolumen abbildet, steht nicht zur\nVerfügung, die Bestrahlung mit SIB ist deshalb mit dem OPS-Kode 8-522.91\nStrahlentherapie, Hochvoltstrahlentherapie, Linearbeschleuniger, intensitätsmodulierte\nRadiotherapie mit bildgestützter Einstellung zu verschlüsseln.\nKommentierung FoKA:\nDissens SEG 4, Konsens MDS (27.10.2016):\nZwar erfolgt die Bestrahlung ohne Umlagerung des Patienten oder Lageänderung des\nTisches, die Zielvolumina für beide Bestrahlungsfraktionen unterscheiden sich in ihrer Größe\nund Lokalisation sowie der jeder Lokalisation zugeordneten Dosis.\nIm Vorschlagsverfahren für die Entwicklung des OPS 2017 wurde darüber hinaus durch die\nExperten des Medizinischen Dienstes des Spitzenverbandes Bund der Krankenkassen ein\nVorschlag für die Implementierung eines eigenständigen Kodes für das SIB-Verfahren\neingereicht. In der Begründung heißt es: \"Die 3D -konformale Bestrahlung ohne IMRT\nerfordert bei Bestrahlung mehrerer Zielvolumina eine erhöhten Aufwand. Bei der\nintensitätsmodulierten Radiotherapie (IMRT) können zwei (oder mehr) Zi elvolumina ohne\nUmlagerung und ohne Tischverschiebung in der derselben Sitzung bestrahlt werden (z. B.\n\nBestrahlung mittels SIB). Der Aufwand entspricht dabei eher dem bei der Bestrahlung eines\nZielvolumens.\nDerzeit ermöglicht der OPS 8 -522 in dieser Situa tion eine zwei - bzw. mehrfache Kodierung\nfür eine Sitzung. Diese Vorgehensweise entspricht der fachlichen Definition des\nZielvolumens nach DIN 6814 -8 und der wörtlichen Definition des Zielvolumens im OPS ...\n\"\nDer Vorschlag wurde durch das DIMDI für 2017 nicht umgesetzt.","pdfFile":"pdf/2020-10-28_KDE-562_Entscheidung-KDE-562-SIB,-Simultan-Integrierter-Boost.pdf-(46,34-kB).pdf","codes":{"icd":[],"ops":["8-52","8-522.91"],"dkr":[]},"category":"kde"},{"decisionDate":"2020-11-11","publicationDate":"2020-11-11","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-400","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 400 Megaureter, Kontrolluntersuchung.pdf (42,37 kB)","sourceURL":"https://www.g-drg.de/content/download/10046/file/Entscheidung%20KDE%20400%20Megaureter,%20Kontrolluntersuchung.pdf","keywords":"Entscheidung KDE 400 Megaureter, Kontrolluntersuchung.pdf (42,37 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n11.11.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 400:\nWenn ein Neugeborenes wegen persistierendem Ikterus in ein Krankenhaus aufgenommen wird\nund eine sonographische Beurteilung der ableitenden Harnwege bei bekanntem Megaureter\nerfolgt, anschließend in Bezug auf den Megaureter aber keine weiteren diagnostischen oder\ntherapeutischen Maßnahmen während des stationären Aufenthaltes erfolgen, ist der Kode Q62.2\nAngeborener Megaureter gemäß DKR D003 Nebendiagnosen als Nebendiagnose anzugeben.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.01.2021 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 25.11.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE 400\nSchlagworte: Megaureter, Kontrolluntersuchung\nStand: 16.06.2011\nAktualisiert: 01.01.2019\nProblem/Erläuterung:\nEin Neugeborenes wird wegen persistierendem Ikterus ins Krankenhaus aufgenommen. Bei\nder Sonographie erfolgt auch eine Beurteilung der ableitenden Harnwege. Dabei wird ein\nbekannter Megaureter bestätigt. Während des Aufenthaltes erfolgen diesbezüglich keine\nweiteren diagnostischen oder therapeutischen Maßnahmen.\nKann hier der ICD-Kode Q62.2 Angeborener Megaureter als Nebendiagnose angegeben\nwerden?\nKodierempfehlung SEG 4:\nAllein die nochmalige Kontrolle der bekannten Harntransportstörung im Sinne eines\nabnormen Befundes ohne weitergehende Diagnostik ist gemäß DKR D003 nicht als\nNebendiagnose zu kodieren.\nKommentierung FoKA:\nDissens:\nBei einem Megaureter eines Neugeborenen handelt es sich um eine klinisch relevante und\nüberwachungspflichtige Erkrankung. Wenn im Rahmen einer bildgebenden Diagnostik aus\nanderer Indikation auch eine Verlaufskontrolle des Megaureters durchgeführt wird, muss\nder Ressourcenverbrauch der bildgebenden Diagnostik auch dieser Diagnose zugeordnet\nwerden. Es handelt sich nicht um einen \"Abnormen Befund\" im Sinne der DKR D002.\nRückmeldung SEG 4:\nEs handelt sich um einen abnormen Befund im Sinne der DKR. (27.08.2015)","pdfFile":"pdf/2020-11-11_KDE-400_Entscheidung-KDE-400-Megaureter,-Kontrolluntersuchung.pdf-(42,37-kB).pdf","codes":{"icd":["Q62.2"],"ops":[],"dkr":["D003","D002"]},"category":"kde"},{"decisionDate":"2020-11-11","publicationDate":"2020-07-21","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-535","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 535 Down-Syndrom, Nebendiagnose.pdf (45,84 kB)","sourceURL":"https://www.g-drg.de/content/download/10047/file/Entscheidung%20KDE%20535%20Down-Syndrom,%20Nebendiagnose.pdf","keywords":"Entscheidung KDE 535 Down-Syndrom, Nebendiagnose.pdf (45,84 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n11.11.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 535:\nErfolgt wie in dem vorliegendem Fall (KDE-535), eine stationäre Behandlung eines fünf Monate\nalten Säuglings mit Down-Syndrom wegen einer länger bestehenden Otitis media mit purulenter\nOtorrhoe und Nachweis von Pseudomonas aeruginosa, die mit einer intravenösen\nAntibiotikatherapie behandelt wird, ist gemäß DKR D004 Syndrome der zutreffende Kode aus\nQ90.- Down-Syndrom als Nebendiagnose zu kodieren. Die Otitis media stellt eine spezifische\nManifestation des Down-Syndroms dar.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.01.2021 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 25.11.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE 535\nSchlagworte: Down-Syndrom, Nebendiagnose\nErstellt: 04.05.2015\nAktualisiert: 01.01.2016\nProblem/Erläuterung:\nStationäre Behandlung eines fünf Monate alten Säuglings wegen einer länger bestehenden\nOtitis media mit purulenter Otorrhoe und Nachweis von Pseudomonas aeruginosa. Es\nerfolgt eine intravenöse Antibiotikatherapie. Anamnestisch ist ein Down-Syndrom bekannt,\nein Herzfehler liegt nicht vor. Trinkverhalten und Nahrungsaufnahme sind\naltersentsprechend unauffällig. In Bezug auf das bekannte Down-Syndrom entsteht kein\nAufwand.\nIst ein Kode aus Q90.- Down-Syndrom als Nebendiagnose zu kodieren?\nKodierempfehlung SEG 4:\nQ90.- Down-Syndrom ist nicht als Nebendiagnose zu kodieren, da diese Erkrankung das\nPatientenmanagement nicht beeinflusst hat (DKR D003).\nDie im Vordergrund stehende Otitis media ist keine Manifestation des Down-Syndroms. Deshalb ist\nDKR D004 hier nicht anzuwenden.\n25.08.2016 Keine Manifestation des Down-Syndroms. Kein Änderungsbedarf.\nSiehe auch Kodierempfehlung 556.\nKommentierung FoKA:\nDissens (Stand 04.07.2016)\nDas Auftreten der Erkrankung und die Therapieentscheidung (Antibiose: Art und\nApplikation) sowie die Notwendigkeit einer stationären Behandlung wird maßgeblich\ndurch die Komorbidität (Trisomie 21) beeinflusst. Untypisch im Fall ist auch der\nnachgewiesene gramnegative Erreger, der am ehesten im Ergebnis der Immunschwäche als\nMerkmal der Begleiterkrankung aufgetreten ist. Vgl. Strukturiertes Vorgehen bei akuter\nOtitis media. Im Normalfall sind bakterielle Erreger einer AOM Pneumokokken oder\nHämophilus influenca. Durch die Begründung der stationären Aufnahme sind die Kriterien\neiner Nebendiagnose erfüllt.\nRückmeldung SEG 4:\nEs handelt sich um einen abnormen Befund im Sinne der DKR. (27.08.2015)\n\nAktualisierung Kodierempfehlung SEG 4 vom 01.01.2019:\nQ90.- Down-Syndrom ist nicht als Nebendiagnose zu kodieren, da diese Erkrankung das\nPatientenmanagement nicht beeinflusst hat (DKR D003).\nDie im Vordergrund stehende Otitis media ist keine Manifestation des Down-Syndroms.\nDeshalb ist DKR D004 hier nicht anzuwenden.\nSiehe auch Kodierempfehlung 556.","pdfFile":"pdf/2020-11-11_KDE-535_Entscheidung-KDE-535-Down-Syndrom,-Nebendiagnose.pdf-(45,84-kB).pdf","codes":{"icd":["Q90"],"ops":[],"dkr":["D004","D003"]},"category":"kde"},{"decisionDate":"2020-11-11","publicationDate":"2020-12-16","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-555","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 555 Wunde, offen, infiziert.pdf (149,26 kB)","sourceURL":"https://www.g-drg.de/content/download/10048/file/Entscheidung%20KDE%20555%20Wunde,%20offen,%20infiziert.pdf","keywords":"Entscheidung KDE 555 Wunde, offen, infiziert.pdf (149,26 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n11.11.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 555:\nWird ein Patient bei Zustand nach großflächiger Kontaktverbrennung II. Grades am Rumpf,\nwelche er sich Tage zuvor zugezogen hat und die sich infiziert zeigt, aufgenommen sowie im\nWundabstrich Streptokokkus agalactiae, Staphylokokkus aureus, Serratia marcescens und\nSerratia ureilytica nachgewiesen und erfolgen als Wundmanagement eine antibiotische Therapie,\nwiederholt chirurgische Eingriffe sowie aufwändige Verbandswechsel, ist als Hauptdiagnose die\nVerbrennung zu kodieren.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.01.2021 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 25.11.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE 555\nSchlagworte: Wunde, offen, infiziert\nErstellt: 20.06.2016\nProblem/Erläuterung:\nAufnahme eines Patienten bei Zustand nach großflächiger Kontaktverbrennung II. Grades\nam Rumpf, welche er sich Tage zuvor zugezogen hatte. Die Wunde zeigte sich infiziert. Im\nWundabstrich Nachweis von Streptokokkus agalactiae, Staphylokokkus aureus, Serratia\nmarcescens und Serratia ureilytica. Als Wundmanagement erfolgten eine antibiotische\nTherapie, wiederholt chirurgische Eingriffe sowie aufwändige Verbandswechsel. Was ist die\nHauptdiagnose?\nKodierempfehlung SEG 4:\nL08.8 Sonstige näher bezeichnete lokale Infektionen der Haut und der Unterhaut ist für die\ninfizierte Wunde zu kodieren. Es handelt sich um eine offene Wunde, welche sich infiziert\nhat.\nFür die Kodierung von Komplikationen bei offenen Wunden ist die Regelung der DKR 1905\nKomplikationen offener Wunden anzuwenden. Hierbei ist zuerst der spezifische Kode für\ndie Komplikation anzugeben, hier L08.8, da die Infektion mit einem spezifischen Kode der\nICD-10-GM abbildbar ist. Der Kode für die offene Wunde ist als Nebendiagnose anzugeben.\n25.08.2016 Es geht um die Kodierung einer Komplikation einer offenen Wund. Kein\nÄnderungsbedarf.\nKommentierung FoKA:\nDissens (04.07.2016)\nIm Fallbeispiel fehlen Angaben zur Größe der Verbrennung, zum tatsächlichen zeitlichen\nAbstand und zur Art der Vorbehandlung.\nDer beschriebene klinische Verlauf ist nicht für eine zweitgradigen Verbrennung plausibel,\nvielmehr spricht das Beispiel für eine drittgradige Verbrennung, die initial unterschätzt\nwurde. Alle beschriebenen Maßnahmen sind gleichermaßen typisch für die Behandlung\neiner Verbrennung. Die DKR 1905 ist nicht anzuwenden, da es sich bei einer Verbrennung\nnicht um eine offene Wunde im Sinne der Klassifikation handelt.\nAls Hauptdiagnose ist bei Anwendung der DKR D005 die Verbrennung mit Bezug zum\ntatsächlichen Schweregrad, Lokalisation und Größe zu verschlüsseln:\n\"Behandlung einer akuten Verletzung/Verbrennung und geplanter Folgeeingriff\nFür die initiale und nachfolgende Behandlung einer aktuellen Verletzung/Verbrennung ist\nder Kode für die Verletzung/Verbrennung (weiterhin) als Hauptdiagnose zu verwenden.\"\n\nAktualisierung Kodierempfehlung SEG 4 vom 01.01.2019:\nL08.8 Sonstige näher bezeichnete lokale Infektionen der Haut und der Unterhaut ist für die\ninfizierte Wunde zu kodieren. Es handelt sich um eine offene Wunde, welche sich infiziert\nhat.\nFür die Kodierung von Komplikationen bei offenen Wunden ist die Regelung der DKR 1905\nKomplikationen offener Wunden anzuwenden. Hierbei ist zuerst der spezifische Kode für\ndie Komplikation anzugeben, hier L08.8, da die Infektion mit einem spezifischen Kode der\nICD-10-GM abbildbar ist. Der Kode für die offene Wunde ist als Nebendiagnose anzugeben.","pdfFile":"pdf/2020-11-11_KDE-555_Entscheidung-KDE-555-Wunde,-offen,-infiziert.pdf-(149,26-kB).pdf","codes":{"icd":["L08.8"],"ops":[],"dkr":["D005"]},"category":"kde"},{"decisionDate":"2020-11-11","publicationDate":"2020-11-25","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-556","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 556 Achondroplasie, Syndrom, angeboren, Wundheilungsst&ouml;rung.pdf (214,11 kB)","sourceURL":"https://www.g-drg.de/content/download/10049/file/Entscheidung%20KDE%20556%20Achondroplasie,%20Syndrom,%20angeboren,%20Wundheilungsst%C3%B6rung.pdf","keywords":"Entscheidung KDE 556 Achondroplasie, Syndrom, angeboren, Wundheilungsst&ouml;rung.pdf (214,11 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n11.11.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 556:\nIn dem vorliegenden Fall (KDE 556) der Aufnahme eines Patienten wegen einer\nWundheilungsstörung im Bereich des Rückens nach vorheriger knöcherner Dekompression bei\nschwerer Spinalkanalstenose bei Achondroplasie, bei dem aktuell eine Wundrevision und\nVerschluss eines Liquorlecks erfolgt, ist weder die Wundheilungsstörung noch das Liquorleck\neine spezifische Manifestation der Achondroplasie. Die Kodierung der Achondroplasie richtet\nsich daher nach DKR D003 Nebendiagnosen.\nDie Nebendiagnose ist danach abhängig vom Aufwand zu kodieren, welcher sich jedoch an\nHand der hier zum Sachverhalt vorliegenden Informationen allein nicht abschließend sicher\nbestimmen lässt.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.01.2021 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 25.11.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE 556\nSchlagworte: Achondroplasie, Syndrom, angeboren, Wundheilungsstörung\nErstellt: 25.04.2016\nAktualisiert: 01.01.2019\nProblem/Erläuterung:\nWiederaufnahme eines Patienten wegen einer Wundheilungsstörung im Bereich des\nRückens nach knöcherner Dekompression bei schwerer Spinalkanalstenose bei\nAchondroplasie. Aktuell erfolgt eine Wundrevision und Verschluss eines Liquorlecks. Ist\nQ77.4 Achondroplasie als Nebendiagnose zu kodieren?\nKodierempfehlung SEG 4:\nQ77.4 ist nicht zusätzlich zu kodieren.\nWeder die Wundheilungsstörung noch das Liquorleck sind Manifestationen des zugrunde\nliegenden Syndroms. Auch verursacht das Syndrom keine Beeinflussung des\nPatientenmanagements.\nSiehe auch Kodierempfehlung 535.\nKommentierung FoKA:\nDissens (04.07.2016)\nDie Achondroplasie gehört zu den sogenannten Orphan Diseases. Das Vorliegen des\nkomplexen Erkrankungsbildes erfordert Anpassungen des anästhesiologischen\nManagements (Lagerung, Wärmemanagement, Sicherung der Atemwege, differenzierte\nAufklärung etc.)*. Die Nebendiagnosendefinition ist durch den nachvollziehbaren\nRessourcenverbrauch erfüllt. Es ist methodisch falsch, nur einen Zusammenhang zur\nOperation zu sehen\n* Quellennachweis: https:/ / www. orpha. net/ data/ patho/ Pro/ de/ Achondroplasia_DE. pdf","pdfFile":"pdf/2020-11-11_KDE-556_Entscheidung-KDE-556-Achondroplasie,-Syndrom,-angeboren,-Wundheilungsst&ouml;rung.pdf-(214,11-kB).pdf","codes":{"icd":["Q77.4"],"ops":[],"dkr":["D003"]},"category":"kde"},{"decisionDate":"2020-11-11","publicationDate":"2020-11-25","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-558","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 558 ECMO_ECLS, Intervention, spezielle.pdf (147,11 kB)","sourceURL":"https://www.g-drg.de/content/download/10050/file/Entscheidung%20KDE%20558%20ECMO_ECLS,%20Intervention,%20spezielle.pdf","keywords":"Entscheidung KDE 558 ECMO_ECLS, Intervention, spezielle.pdf (147,11 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n11.11.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 558:\nDie Extrakorporale Membranoxygenierung (ECMO) / Extracorporal Life Support System (ECLS)\ngehören zu den speziellen Interventionen auf der Intensivstation. Im Rahmen einer\nintensivmedizinischen Komplexbehandlung ist nur die Anlage der ECMO/ECLS bei der\nErmittlung der diesbezüglichen Aufwandspunkte für den TISS zu berücksichtigen.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.01.2021 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 25.11.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE 558\nSchlagworte: ECMO/ECLS, Intervention, spezielle\nErstellt: 20.06.2016\nAktualisiert: 01.01.2019\nProblem/Erläuterung:\nIst die tägliche Erfassung des Betriebs einer/s Extrakorporalen Membranoxygenierung\n(ECMO) / Extracorporal Life Support System (ECLS) als spezielle Intervention auf der\nIntensivstation im Rahmen der intensivmedizinischen Komplexbehandlung korrekt?\nKodierempfehlung SEG 4:\nDer Betrieb einer ECMO/ECLS (nicht die Anlage) kann bei einem Patienten auf einer\nIntensivstation nicht täglich als spezielle Intervention im Rahmen der intensivmedizinischen\nKomplexbehandlung erfasst werden. Der Betrieb der ECMO/ECLS ist nicht als spezielle\nIntervention zu werten.\nKommentierung FoKA:\nDissens (04.07.2016)\nECMO/ECLS sind keine Routineverfahren auf Intensivstationen. Die Beispielsliste für\nInterventionen auf der ICU* ist nicht abschließend.\nModerne kontinuierliche Herzunterstützungsverfahren waren bei der Entwicklung des\nScores nicht bekannt und wurden nicht berücksichtigt.\nIm Rahmen einer KDE ist nicht zu klären, ob das Verfahren zu berücksichtigen ist. Eine\nEntscheidung ist den Partnern der Selbstverwaltung vorbehalten.\n* Quellennachweis: http:/ / www. divi. de/ images/ Dokumente/ Empfehlungen/\nQualitaetssicherung/ 2000_tiss28. pdf","pdfFile":"pdf/2020-11-11_KDE-558_Entscheidung-KDE-558-ECMO_ECLS,-Intervention,-spezielle.pdf-(147,11-kB).pdf","codes":{"icd":[],"ops":[],"dkr":[]},"category":"kde"},{"decisionDate":"2020-11-11","publicationDate":"2020-12-16","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-585","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 585 Aortenklappenstenose, bikuspidale Aortenklappe.pdf (219,8 kB)","sourceURL":"https://www.g-drg.de/content/download/10051/file/Entscheidung%20KDE%20585%20Aortenklappenstenose,%20bikuspidale%20Aortenklappe.pdf","keywords":"Entscheidung KDE 585 Aortenklappenstenose, bikuspidale Aortenklappe.pdf (219,8 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n11.11.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 585:\nBei der 78-jährigen Patientin (KDE-585), die zur geplanten Operation einer\nAortenklappenstenose kommt und bei der erst intraoperativ eine bikuspidale Aortenklappe mit\nStenose festgestellt wird, deren Vorhandensein nicht zu einer Änderung im geplanten\nOperationsablauf führt, ist der Kode I35.0 Aortenklappenstenose als Hauptdiagnose zu kodieren.\nDie bikuspidale Aortenklappe wird in diesem Fall nicht mit einem Kode aus Q23.- Angeborene\nFehlbildungen der Aorten- und der Mitralklappe als Nebendiagnose kodiert.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.01.2021 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 25.11.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE 558\nSchlagworte: Aortenklappenstenose, bikuspidale Aortenklappe\nErstellt: 31.08.2017\nAktualisiert: 01.01.2019\nProblem/Erläuterung:\n78-jährige Patientin kommt geplant zur Operation einer Aortenklappenstenose.\nIntraoperativ findet sich eine bikuspidale Aortenklappe mit Stenose.\nWie ist die Aortenklappenstenose in diesem Fall zu kodieren?\nKodierempfehlung SEG 4:\nDie Aortenklappenstenose ist in diesem Fall nur mit I35.0 Aortenklappenstenose zu\nkodieren. Es liegt zwar eine angeborene Fehlbildung der Klappe vor (bikuspidale\nAortenklappe), die das Entstehen einer Aortenklappenstenose begünstigen kann, aber\nkeine angeborene Aortenklappenstenose. Deshalb ist kein Kode aus Kapitel XVII zu\nverwenden.\nSiehe auch Kodierempfehlung 533.\nKommentierung FoKA:\nDissens (15.09.2017):\nKodes aus dem Kapitel XVII sind in der Anwendung nicht auf die Fälle zu begrenzen, bei\ndenen die komplette klinische Manifestation bereits bei Geburt besteht. Diagnosen aus\nQ23.- beschreiben mit einem Kombinationskode eine komplexe Erkrankung der\nHerzklappe(n) und der Aorta und der im zeitlichen Verlauf resultierenden funktionalen\nBeeinträchtigung.\nIn den Hinweisen des systematischen Verzeichnisses und im alphabetischen Verzeichnis zum\nKode Q23.1 Angeborene Aorte nklappeninsuffizienz ist ausdrücklich der Begriff \"bikuspide\nAortenklappe\" aufgeführt. Wenn die klinische Manifestation keine Insuffizienz sondern\neine Stenose ist, ist in der Differenzierung der Kode Q23.0 Angeborene\nAortenklappenstenose auszuwählen. Dabei ist zu beachten, dass unter dem Klassentitel des\nICD-Dreistellers I35 angeborene Erkrankungen der Aortenklappe exkludiert werden und auf\ndas Kapitel XVII verwiesen wird.\nEine Stenose der Aortenklappe ist eine regelhafte Folge einer bikuspiden Anlage der\nAortenklappe. Der enge Zusammenhang zwischen einer pathologischen Klappenanatomie\nund den resultierenden Stenosen bzw. Insuffizienzen kann der Fachliteratur entnommen\nwerden. Bikuspide Aortenklappe und Dilatation der Aorta ascendens und Klassifikation\nbikuspider Aortenklappen.\nSiehe auch Anfrage_0092","pdfFile":"pdf/2020-11-11_KDE-585_Entscheidung-KDE-585-Aortenklappenstenose,-bikuspidale-Aortenklappe.pdf-(219,8-kB).pdf","codes":{"icd":["I35.0","Q23","Q23.1","Q23.0","I35"],"ops":[],"dkr":[]},"category":"kde"},{"decisionDate":"2020-11-11","publicationDate":"2020-11-25","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-586","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 586 8-980, 8-98f, Aufnahmestatus ITS.pdf (153,32 kB)","sourceURL":"https://www.g-drg.de/content/download/10052/file/Entscheidung%20KDE%20586%208-980,%208-98f,%20Aufnahmestatus%20ITS.pdf","keywords":"Entscheidung KDE 586 8-980, 8-98f, Aufnahmestatus ITS.pdf (153,32 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n11.11.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 586:\nFür die Berechnung der Aufwandspunkte für die intensivmedizinische Komplexbehandlung gilt\nfür die Auswahl des korrekten Aufnahmestatus Folgendes:\nDie Definitionen der Kategorien „geplant chirurgisch“, „nicht geplant chirurgisch“ und\n„medizinisch“ stellen nur auf den Zeithorizont zum Operationstermin ab. Eine nicht geplante\nchirurgische Aufnahme auf die Intensivstation liegt vor, wenn der Operationstermin erst in den\nletzten 24 Stunden geplant war oder postoperativ eine ungeplante Aufnahme auf Intensivstation\nerforderlich ist. Der OPS differenziert nicht nach den Gründen, die zur postoperativen Aufnahme\nauf die Intensivstation geführt haben. Demnach liegt in dem vorliegenden Fall (KDE-586) eine\nnicht geplante chirurgische Aufnahme vor.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.01.2021 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 25.11.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE 586\nSchlagworte: 8-980, 8-98f, Aufnahmestatus ITS\nErstellt: 16.10.2017\nAktualisiert: 01.01.2019\nProblem/Erläuterung:\nElektive stationäre Aufnahme zur geplanten Leistenhernien-Operation rechts. Intraoperativ\nAuftreten eines reanimationspflichtigen Herz-/Kreislaufversagens im Rahmen eines\nMyokardinfarktes (STEMI). Vorzeitiger Abbruch der Operation, notfallmäßige\nDurchführung einer Herzkatheteruntersuchung mit Stentimplantation und Aufnahme auf\ndie Intensivstation. Welches ist der korrekte Aufnahmestatus bei der Berechnung für die\nAufwandspunkte für die Intensivmedizinische Komplexbehandlung bei Erwachsenen?\nKodierempfehlung SEG 4:\nDer korrekte Aufnahmestatus ist „Medizinische Aufnahme“, da die Aufnahme aus nicht-\noperativen Gründen erfolgte. Siehe auch FAQ DIMDI 8009 (Art der Aufnahme)\nKommentierung FoKA:\nDissens (22.01.2018):\nIm Fallbeispiel wird der Patient ungeplant postoperativ auf der Intensivstation\naufgenommen. Hier ist der folgende Ausfüllhinweis zum Aufnahmestatus zu beachten: Eine\nungeplante chirurgische Aufnahme liegt vor, wenn der Operationstermin erst in den letzten\n24 Stunden geplant war oder postoperativ eine ungeplante Aufnahme auf Intensivstation\nerforderlich ist.","pdfFile":"pdf/2020-11-11_KDE-586_Entscheidung-KDE-586-8-980,-8-98f,-Aufnahmestatus-ITS.pdf-(153,32-kB).pdf","codes":{"icd":[],"ops":["8-980","8-98f"],"dkr":[]},"category":"kde"},{"decisionDate":"2020-11-11","publicationDate":"2020-10-15","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-596","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 596 Aszitesdrainage, Aszitespunktion.pdf (215,79 kB)","sourceURL":"https://www.g-drg.de/content/download/10053/file/Entscheidung%20KDE%20596%20Aszitesdrainage,%20Aszitespunktion.pdf","keywords":"Entscheidung KDE 596 Aszitesdrainage, Aszitespunktion.pdf (215,79 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n11.11.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 596:\nBei einer therapeutischen Peritonealdrainage (OPS 8-148.0 Therapeutische Drainage von\nanderen Organen und Geweben, Peritonealraum) wird die aus therapeutischen Zwecken zu\nentfernende Flüssigkeit mittels eines gelegten Schlauchsystems über einen bestimmten Zeitraum\nabgelassen (z. B. mittels Schwerkraft, Sog- oder Kapillarwirkung). Das Legen der\nPeritonealdrainage erfolgt durch den Arzt. Das Ablassen der Flüssigkeit erfordert in der Regel\nkeine ärztliche Anwesenheit und erfolgt im Rahmen der allgemeinen fachlichen Beobachtung im\nKrankenhaus durch das Pflegepersonal.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.01.2021 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 25.11.2020 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE 596\nSchlagworte: Aszitesdrainage, Aszitespunktion\nErstellt: 26.06.2019\nStand: 10.09.2019\nProblem/Erläuterung:\nWelche Voraussetzungen sind für die Kodierung des OPS 8-148.0 Therapeutische Drainage\nvon anderen Organen und Geweben, Peritonealraum zu fordern?\nKodierempfehlung SEG 4:\nFolgende Voraussetzungen müssen kumulativ erfüllt sein:\n1. Dokumentation mittels Überwachungsprotokoll (Kreislaufparameter, Drainagemenge)\n2. Dokumentation einer geeigneten Fixation der Drainage (z.B. mittels Naht)\n3. Dokumentation der Art des verwendeten Drainagesystems\n4. Mehrtägiger Verbleib der Drainage und / oder mehrfache Drainage über dasselbe System\nund / oder Drainage über mehrere Stunden.\nKommentierung FoKA:\nDissens:\nDie Definition einer Drainage in Abgrenzung zu einer Punktion wurde durch den FoKA\nbereits in der Anfrage 136 bearbeitet.\nEine zeitliche Abgrenzung von Punktion und Drainage ist nicht möglich. Zu unterscheiden\nsind Punktionen von temporären oder permanenten Drainagen, bei denen ein Ableitsystem\ndurch Punktion oder chirurgisch eingebracht wird.\nWenn das technische System noch während des Arzt-Patienten-Kontaktes, in dem das\nSystem in den Körper eingebracht wurde, wieder entfernt wird, handelt es sich um eine\nPunktion. In allen anderen Fällen, handelt es sich um eine Drainage.\nDokumentationsanforderungen hinsichtlich Kreislaufüberwachung oder der Fixation der\nDrainage sind fachlich nicht nachvollziehbar.\nDie Dokumentation des Drainagesystems, der Drainagemenge und der Drainagezeit (bzw.\nder Zeitpunkte der Anlage und der Entfernung) ist im Sinne der ärztlichen\nDokumentationspflicht erforderlich.\n(Stand 10.09.2019)","pdfFile":"pdf/2020-11-11_KDE-596_Entscheidung-KDE-596-Aszitesdrainage,-Aszitespunktion.pdf-(215,79-kB).pdf","codes":{"icd":[],"ops":["8-148.0"],"dkr":[]},"category":"kde"},{"decisionDate":"2020-12-02","publicationDate":"2020-10-06","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-129","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 129 Blutungsan&auml;mie, Gastroskopie, Blutkonserven.pdf (42,87 kB)","sourceURL":"https://www.g-drg.de/content/download/10146/file/Entscheidung%20KDE%20129%20Blutungsan%C3%A4mie,%20Gastroskopie,%20Blutkonserven.pdf","keywords":"Entscheidung KDE 129 Blutungsan&auml;mie, Gastroskopie, Blutkonserven.pdf (42,87 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n02.12.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 129:\nIn dem beschriebenen Fall (KDE-129), bei dem der Patient wegen einer vermuteten\ngastrointestinalen Blutung aufgenommen wird und bei einer Notfall-Gastroskopie eine\nMagenblutung festgestellt wird, für den Patienten 4 Blutkonserven gekreuzt, laborchemisch eine\nAnämie gesichert, eine Hb-Kontrolle durchgeführt, aber die Blutkonserven während des\nstationären Aufenthaltes nicht gegeben werden und auch sonst keine Behandlung der Anämie,\nz.B. keine Eisenmedikation erfolgt, kann u. a. der Kode D62 Akute Blutungsanämie als\nNebendiagnose kodiert werden.\nGültigkeit:\nDiese Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser,\ndie Krankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.02.2021 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n16.12.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen diese Entscheidung des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-129\nSchlagwort: Blutungsanämie, Gastroskopie, Blutkonserven\nStand: 2007-01-10\nAktualisiert: 2019-01-01\nICD: D62\nProblem/Erläuterung:\nAufnahme wegen gastrointestinaler Blutung. Bei der Notfall-Gastroskopie Feststellung\neiner Magenblutung. 4 Konserven werden gekreuzt, aber während des stationären\nAufenthaltes nicht gegeben. Laborchemisch Anämie gesichert, Hb-Kontrolle wird\ndurchgeführt. Eine Behandlung der Anämie wird nicht durchgeführt, keine\nEisenmedikation. Berechtigt das Kreuzen von Konserven die Kodierung von D62 Akute\nBlutungsanämie als Nebendiagnose?\nKodierempfehlung SEG 4:\nDas prophylaktische Bereitstellen von Blutkonserven bei einer Notfallgastroskopie\nrechtfertigt nicht die Kodierung von D62 Akute Blutungsanämie . Die Kontrolle des\nabnormen Hb-Wertes rechtfertigt laut DKR D003d (abnorme Befunde) nicht die Kodierung\nvon D62.\nKommentar FoKA:\nDissens:\nIm vorliegenden Fall entsteht ein diagnostischer Mehraufwand durch das notfallmäßige\nund nicht routinemäßige Kreuzen der Blutkonserven, dadurch ist die Definition der\nNebendiagnosen gemäß DKR D003d erfüllt und D62 kann hier kodiert werden.\nDie prophylaktische Bereitstellung von Blutkonserven ist eine Prozedur, die nicht\nverschlüsselt werden kann.\nRückmeldung SEG 4:\nKein Änderungsbedarf.","pdfFile":"pdf/2020-12-02_KDE-129_Entscheidung-KDE-129-Blutungsan&auml;mie,-Gastroskopie,-Blutkonserven.pdf-(42,87-kB).pdf","codes":{"icd":["D62"],"ops":[],"dkr":["D003d"]},"category":"kde"},{"decisionDate":"2020-12-02","publicationDate":"2020-10-06","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-372","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 372 Komplexbehandlung Leistungserbringung.pdf (46,17 kB)","sourceURL":"https://www.g-drg.de/content/download/10147/file/Entscheidung%20KDE%20372%20Komplexbehandlung%20Leistungserbringung.pdf","keywords":"Entscheidung KDE 372 Komplexbehandlung Leistungserbringung.pdf (46,17 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n02.12.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 372:\nBei der Anrechnung von Therapiezeiten der genannten Therapiebereiche im Rahmen des OPS-\nKodes 8-983 Multimodale rheumatologische Komplexbehandlung sind die Leistungen von\nPflegepersonal nur dann anzurechnen, sofern die jeweils hierzu erforderliche berufsrechtliche\nbzw. fachliche Qualifikation für den zutreffenden Therapiebereich vorliegt.\nEs können pauschal Leistungen in hälftigem Zeitumfang (z. B. 15 Minuten für eine\nTherapieeinheit von 30 Minuten) hinzugerechnet werden, die keine durchgehende Anwesenheit\neines Vertreters der benannten Therapiebereiche erfordern (z. B. Rotlichtlampe).\nGültigkeit:\nDiese Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser,\ndie Krankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.02.2021 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n16.12.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen diese Entscheidung des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-372\nSchlagworte: Komplexbehandlung, Leistungserbringung\nStand: 2012-01-16\nAktualisiert: 01.01.2019\nOPS: 8-983\nProblem/Erläuterung:\nOPS 8-983 Multimodale rheumatologische Komplexbehandlung fordert Leistungen in\ndefinierter „Therapiedichte“ bei Einsatz explizit benannter Therapiebereiche.\n1. Können solche Leistungen hinzugerechnet werden, die durch das Pflegepersonal der\nStation erbracht werden?\n2. Können Leistungen in vollem Zeitumfang hinzugerechnet werden, die keine\ndurchgehende Anwesenheit eines Vertreters der benannten Therapiebereiche\nerfordern (z.B. Belassen eines Coolpacks oder einer Rotlichtlampe für 30 Minuten)?\nKodierempfehlung SEG 4:\n1. Nur die durch einen Therapeuten (Vertreter eines der benannten Therapiebereiche)\nerbrachten Leistungen können hinzugerechnet werden.\n2. Nur die Zeit, in der der Therapeut unmittelbar mit der Behandlung des Patienten\nbefasst ist, ist hinzuzurechnen.\nKommentierung FoKA:\nDissens:\n1. In den Mindestmerkmalen des OPS-Kodes wird keine Aussage zur formalen\nQualifikation der Mitarbeiter in den Therapiebereichen getroffen. Es ist davon\nauszugehen, dass bei Leistungserbringung durch einen ausgebildeten Vertreter des\nTherapiebereiches die Mindestmerkmale erfüllt sind, da die entsprechende fachliche\nQualifikation vorhanden ist. Der Wortlaut der Hinweise zum OPS-Kode schließt die\nLeistungserbringung bspw. im Rahmen einer Delegation durch weitere\nBerufsgruppen nicht aus. Zum Nachweis der korrekten Leistungserbringung ist bei\neiner Delegation der Nachweis der individuellen fachlichen Qualifikation von\nLeistungserbringern zu führen.\n2. Den Mindestmerkmalen zum OPS-Kode ist die Forderung nach einer\nPersonalbindung im Rahmen der Therapie nicht zu entnehmen. Insbesondere bei\napparativen Verfahren der physikalischen Therapie ist die ständige Anwesenheit des\nTherapeuten medizinisch nicht notwendig. Der Begriff \"Therapiedichte\" zielt auf die\ntherapeutischen Verfahren am Patienten und nicht auf den Personaleinsatz im\nKrankenhaus ab.\n\nRückmeldung SEG 4\nKein Änderungsbedarf. (27.08.2015)","pdfFile":"pdf/2020-12-02_KDE-372_Entscheidung-KDE-372-Komplexbehandlung-Leistungserbringung.pdf-(46,17-kB).pdf","codes":{"icd":[],"ops":["8-983"],"dkr":[]},"category":"kde"},{"decisionDate":"2020-12-02","publicationDate":"2020-11-25","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-430","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 430 Prothesenwechsel, Mamma, prophylaktisch.pdf (43,77 kB)","sourceURL":"https://www.g-drg.de/content/download/10148/file/Entscheidung%20KDE%20430%20Prothesenwechsel,%20Mamma,%20prophylaktisch.pdf","keywords":"Entscheidung KDE 430 Prothesenwechsel, Mamma, prophylaktisch.pdf (43,77 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n02.12.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 430:\nWenn bei einer Patientin mit Zustand nach Ablatio mammae rechts wegen Mammakarzinom\nnach abgeschlossener Chemotherapie sowie nach Brustaufbau mit Mammaprothese nunmehr\naufgrund einer fehlerhaft hergestellten Mammaprothese der Patientin angeraten wird das\nImplantat vorsorglich entfernen zu lassen, die diesbezüglichen Untersuchungen einschließlich\nbildgebender Verfahren ohne pathologischen Befund sind, eine Reoperation mit\nProthesenwechsel erfolgt und bei der histologischen Untersuchung des periprothetischen\nGewebes Fremdkörperreaktionen ohne Hinweis auf einen Prothesendefekt bzw. eine\neingetretene Komplikation gefunden werden, wird der Kode Z40.8 Sonstige prophylaktische\nOperation als Hauptdiagnose angegeben.\nGültigkeit:\nDiese Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser,\ndie Krankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.02.2021 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n16.12.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen diese Entscheidung des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-430\nStand:\nAktualisiert: 01.01.2019\nICD: Z40.8; T85.88\nSchlagwort: Prothesenwechsel, Mamma, prophylaktisch\nProblem/Erläuterung:\nAblatio mammae rechts wegen Mammakarzinom. Nach abgeschlossener Chemotherapie\nerfolgte der Brustaufbau mit Mammaprothese. Aufgrund einer fehlerhaft hergestellten\nMammaprothese wurde der Versicherten angeraten, das Implantat vorsorglich entfernen zu\nlassen. Die Untersuchungen einschließlich bildgebender Verfahren sind ohne\npathologischen Befund. Es erfolgt eine Reoperation mit Prothesenwechsel. Bei der\nhistologischen Untersuchung des periprothetischen Gewebes Fremdkörperreaktionen ohne\nHinweis auf Prothesendefekt. Was ist die Hauptdiagnose?\nKodierempfehlung SEG 4:\nZ40.8 Sonstige prophylaktische Operation ist als Hauptdiagnose zuzuweisen. Der\nProthesenwechsel erfolgte aus Gründen der Prophylaxe. Eine Komplikation lag nicht vor.\nDie Behandlung des Mammakarzinoms war mit dem Brustaufbau abgeschlossen. Bei der\naktuellen Reoperation handelt sich auch nicht um eine geplante Folgeoperation.\nKommentierung FoKA:\nDissens:\nIn der DKR 1205d sind die in Frage kommenden Kodes abschließend aufgelistet.\nBei der Entfernung einer Mamma-Prothese auf Grund einer fehlerhaften Herstellung ist von\neiner Sonstigen Komplikation durch interne Pr othesen, Implantate oder Transplantate,\nanderenorts nicht klassifiziert auszugehen, die gemäß ICD 10 mit T85.88 zu verschlüsseln ist.\nRückmeldung SEG 4\nDKR 1205 regelt den Unterschied zwischen medizinischen und kosmetischen Gründen, nicht\nden prophylaktischen Prothesenwechsel. (27.08.2015)","pdfFile":"pdf/2020-12-02_KDE-430_Entscheidung-KDE-430-Prothesenwechsel,-Mamma,-prophylaktisch.pdf-(43,77-kB).pdf","codes":{"icd":["Z40.8","T85.88"],"ops":[],"dkr":["1205d"]},"category":"kde"},{"decisionDate":"2020-12-02","publicationDate":"2020-12-16","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-433","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 433 Organtransplantation, Registrierung.pdf (42,66 kB)","sourceURL":"https://www.g-drg.de/content/download/10149/file/Entscheidung%20KDE%20433%20Organtransplantation,%20Registrierung.pdf","keywords":"Entscheidung KDE 433 Organtransplantation, Registrierung.pdf (42,66 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n02.12.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 433:\nDer Kode U55.- Erfolgte Registrierung zur Organtransplantation sagt aus, dass bei dem\nPatienten eine Registrierung zur Organtransplantation erfolgt ist. Diese Registrierung muss nicht\nim aktuellen stationären Aufenthalt erfolgt sein. Der Kode ist zu verwenden, wenn die erfolgte\nRegistrierung weiterhin Gültigkeit besitzt.\nGültigkeit:\nDiese Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser,\ndie Krankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.02.2021 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n16.12.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen diese Entscheidung des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-433\nStand:\nAktualisiert: 01.01.2019\nICD: U55.-\nSchlagwort: Organtransplantation, Registrierung\nProblem/Erläuterung:\nBei dem Patienten wurde im Rahmen eines Voraufenthaltes die Indikation zur\nHerztransplantation gestellt und für die Transplantation angemeldet (Krankenhaus A).\nAktuell Aufnahme in ein heimatnahes Krankenhaus (B) wegen kardialer Dekompensation.\nIst die Kodierung der Schlüsselnummer U55.- Erfolgte Registrierung zur\nOr gantransplantation durch das Krankenhaus B korrekt, obwohl die Diagnostik und der\nAufwand bereits im Rahmen eines anderen Krankenhausaufenthaltes erfolgten?\nKodierempfehlung SEG 4:\nDie Kodierung einer Schlüsselnummer aus U55.- Erfolgte Registrierung zur\nOrgantransplantation durch das Krankenhaus B ist nicht korrekt. Die Registrierung ist durch\ndas Krankenhaus A erfolgt. Das Krankenhaus B hat bezüglich der Schlüsselnummer keinen\nerkennbaren Aufwand.\nKommentierung FoKA:\nDissens:\nDer Kode U55.- beschreibt nicht den Aufwand der Evaluation einer notwendigen\nTransplantation, die durch einen OPS-Kode abzubilden ist, sondern deren Ergebnis.\nDie aus dem Beispiel abgeleitete Schlussfolgerung eines fehlenden Ressourcenverbrauchs im\nKrankenhaus B ist aus der knappen Schilderung des Sachverhalts nicht ableitbar.\nNur bei fehlendem Aufwand im Sinne der Nebendiagnosen-Definition ist U55,- nicht zu\nkodieren.\nRückmeldung SEG 4\nKein Änderungsbedarf. (27.08.2015)","pdfFile":"pdf/2020-12-02_KDE-433_Entscheidung-KDE-433-Organtransplantation,-Registrierung.pdf-(42,66-kB).pdf","codes":{"icd":["U55"],"ops":[],"dkr":[]},"category":"kde"},{"decisionDate":"2020-12-02","publicationDate":"2020-10-06","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-466","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 466 (ehemals KDE 20) Shuntkomplikation, Shuntverschluss, Shuntneuanlage, Nativshunt, Prothesenshunt, Niereninsuffizienz .pdf (248,95 kB)","sourceURL":"https://www.g-drg.de/content/download/10150/file/Entscheidung%20KDE%20466%20%28ehemals%20KDE%2020%29%20Shuntkomplikation,%20Shuntverschluss,%20Shuntneuanlage,%20Nativshunt,%20Prothesenshunt,%20Niereninsuffizienz%20.pdf","keywords":"Entscheidung KDE 466 (ehemals KDE 20) Shuntkomplikation, Shuntverschluss, Shuntneuanlage, Nativshunt, Prothesenshunt, Niereninsuffizienz .pdf (248,95 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n02.12.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 466 (ehemals KDE 20):\nWird wie in dem vorliegende Fall (KDE-466 ehemals KDE-20) ein Patient mit dialysepflichtiger\nNierenkrankheit ausschließlich zur Thrombektomie bei Thrombose eines AV-Shunts (Shunt aus\nkörpereigenem Material) elektiv aufgenommen, so ist für die Thrombose des AV-Shunts der\nKode T82.8 Sonstige näher bezeichnete Komplikationen durch Prothesen, Implantate oder\nTransplantate im Herzen und in den Gefäßen als Hauptdiagnose zu kodieren.\nGültigkeit:\nDiese Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser,\ndie Krankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.02.2021 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n16.12.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen diese Entscheidung des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-466\nSchlagwort: Shuntkomplikation, Shuntverschluss, Shuntneuanlage, Nativshunt,\nProthesenshunt, Niereninsuffizienz\nErstellt: 2013-01-08\nAktualisiert SEG 4: 01.01.2018\nAktualisiert FoKA: 30.07.2018\nOPS: 5-837.00\nProblem/Erläuterung:\nFallkonstellation 1 (Bis 2012 Kodierempfehlung Nr. 15)\nStationäre Aufnahme elektiv zur geplanten Revision eines Shunts wegen Knickstenose\n(Shunt aus alloplastischem Material) bei dialysepflichtiger Nierenkrankheit. Diagnostik und\nIndikationsstellung ambulant erfolgt, erfolgreicher Revisionseingriff.\nFallkonstellation 2\nStationäre Aufnahme elektiv zur geplanten Revision eines Shunts wegen Knickstenose bei\ndialysepflichtiger Nierenkrankheit (Shunt aus alloplastischem Material). Diagnostik und\nIndikationsstellung ambulant erfolgt, Revisionseingriff nicht erfolgreich, deshalb Indikation\nzur Shuntneuanlage.\nFallkonstellation 3 (Bis 2012 Kodierempfehlung Nr. 20)\nStationäre Aufnahme elektiv zur Thrombektomie wegen Thrombose eines AV-Shunts\n(Shunt aus körpereigenem Material) bei dialysepflichtiger Nierenkrankheit. Diagnostik und\nIndikationsstellung ambulant erfolgt, erfolgreiche Thrombektomie.\nFallkonstellation 4\nStationäre Aufnahme elektiv zur Thrombektomie wegen Thrombose eines Shunts (Shunt\naus alloplastischem Material) bei dialysepflichtiger Nierenkrankheit. Diagnostik und\nIndikationsstellung ambulant erfolgt, erfolgreiche Thrombektomie.\nFallkonstellation 5 (Bis 2012 Kodierempfehlung Nr. 245)\nStationäre Aufnahme zur geplanten Shuntneuanlage bei Shuntverschluss (AV-Shunt aus\nkörpereigenem Material oder Shunt mit alloplastischem Material) mit bekannter\ndialysepflichtiger Nierenkrankheit. Diagnostik und Indikationsstellung ambulant erfolgt.\nWas ist jeweils die Hauptdiagnose?\nKodierempfehlung SEG 4:\nzu Fall 1:\nWenn der liegende Shunt (Shunt aus alloplastischem Material) auf Grund einer\nKomplikation nicht mehr funktionsfähig ist und die Aufnahme speziell zur Revision des\nShunts erfolgt, ist als Hauptdiagnose die Schlüsselnummer T82.5 Mechanische Komplikation\ndurch sonstige Geräte und Implantate im Herzen und in den Gefäßen zuzuweisen.\n\nEs handelt sich hier um den spezifischen Kode, da neben der Information des verwendeten\nalloplastischen Materials noch zusätzlich der Organbezug und die Art der Komplikation\nabgebildet ist. Siehe hierzu auch die Hinweise und Beispiele unter dem Kode. Nach DKR\nD002 ist hier ausnahmsweise der T-Kode der spezifischere Kode und somit vorrangig vor\neinem unspezifischen Kode aus dem Organkapitel.\nZu Fall 2:\nWenn der liegende Shunt (Shunt aus alloplastischem Material) auf Grund einer\nKomplikation nicht mehr funktionsfähig ist und die Aufnahme speziell zur Revision des\nShunts erfolgt, ist als Hauptdiagnose die Schlüsselnummer T82.5 Mechanische Komplikation\ndurch sonstige Geräte und Implantate im Herzen und in den Gefäßen zuzuweisen. Die\nShuntkomplikation hat den stationären Aufenthalt hauptsächlich veranlasst. Es war bei\nIndikationsstellung nicht absehbar, dass eine Shuntneuanlage erfolgen muss.\nEs handelt sich hier um den spezifischen Kode, da neben der Information des verwendeten\nalloplastischen Materials noch zusätzlich der Organbezug und die Art der Komplikation\nabgebildet sind. Siehe hierzu auch die Hinweise und Beispiele unter dem Kode. Nach DKR\nD002 ist hier ausnahmsweise der T-Kode der spezifischere Kode und somit vorrangig vor\neinem unspezifischen Kode aus dem Organkapitel.\nzu Fall 3:\nFür einen Patienten, der bereits vorher einen Shunt erhielt und bereits regelmäßig dialysiert\nwird, ist als Hauptdiagnose die Krankheit zu kodieren, die den stationären Aufenthalt\nhauptsächlich veranlasst hat. Dies ist die Thrombose im AV- Shunt, der in diesem Fall aus\nkörpereigenem Material (Vene/Arterie) besteht. Nach DKR D002 sind die Kodes aus dem\nOrgankapitel vorrangig vor den Kodes für Erkrankungen bzw. Störungen nach\nmedizinischen Maßnahmen und vor den T-Kodes zu verwenden.\nDa es sich in der Regel um eine Thrombose des venösen Schenkels handelt, ist als\nHauptdiagnose die Schlüsselnummer I80.80 Thrombose, Phlebitis und Thrombophlebitis\noberflächlicher Gefäße der oberen Extremitäten zuzuweisen. Ist in seltenen Fällen auch der\narterielle Schenkel betroffen, kann dies durch den Kode I74.2 Embolie und Thrombose der\nArterien der oberen Extremitäten oder I74.3 Embolie und Thrombose der Arterien der\nunteren Extremitäten abgebildet werden.\nZu Fall 4:\nDie Shuntthrombose hat den stationären Aufenthalt hauptsächlich veranlasst. Wenn der\nliegende Shunt aus alloplastischem Material auf Grund einer Thrombose nicht mehr\nfunktionsfähig ist und die Aufnahme speziell zur Thrombektomie erfolgt, ist als\nHauptdiagnose die Schlüsselnummer T82.5 Mechanische Komplikation durch sonstige\nGeräte und Implantate im Herzen und in den Gefäßen zuzuweisen, da hierfür kein\nspezifischer Kode aus den Organkapiteln der ICD existiert.\nEs handelt sich hier um den spezifischen Kode, da neben der Information des verwendeten\nalloplastischen Materials noch zusätzlich der Organbezug und die Art der Komplikation\nabgebildet sind. Siehe hierzu auch die Hinweise und Beispiele unter dem Kode.\nzu Fall 5:\nAb 2007 ist in der speziellen Kodierrichtlinie 0912 der Passus Chirurgisch angelegte arterio-\nvenöse Fistel/Shunt gestrichen worden und somit für die Zuweisung der Hauptdiagnose die\nRegelung der DKR D002 anzuwenden. Verantwortlich für den stationären\nKrankenhausaufenthalt ist die Shuntneuanlage bei dialysepflichtiger Nierenkrankheit. Die\n\nShuntneuanlage erfolgt in Zielrichtung der Behandlung der dialysepflichtigen\nNierenkrankheit. Die Schlüsselnummer N18.5 ist somit Hauptdiagnose.\nDie Shuntneuanlage erfolgt weder zur Behebung einer Komplikation eines nicht mehr\nfunktionsfähigen Shunts noch stellt sie einen Revisionseingriff dar. Die Neuanlage ist bei\nfehlender Revisionsmöglichkeit wie die Shunterstanlage bei dialysepflichtiger\nNierenkrankheit zu werten. Die Aufnahme erfolgt explizit nicht zur Durchführung gezielter\nMaßnahmen am nicht mehr funktionsfähigen Shunt. Die Indikationsstellung zur Neuanlage\nwar bereits ambulant gestellt worden und somit die Ursache des Shuntversagens und die\nRevisionsmöglichkeit abgeklärt.\nKommentierung FoKA:\nDissens:\n1. Konsens\n2. Konsens\n3. Dissens: Ein Shunt ist im anatomischen Sinne weder eine Arterie noch eine Vene. Im\nICD-10 Katalog wird unter T82.5 der operativ angelegte arteriovenöse Shunt\ngenannt, so dass dieser Schlüssel ausgewählt werden muss. Dem widerspricht auch\nnicht die Koderrichtlinie DKR D015l, die die Kodierung von Schlüsseln aus T80ff.\nuntersagt, wenn es spezifischere Schlüssel für die Komplikation gibt.\n4. Konsens\n5. Konsens\n(Stand 30.07.2018)\nRückmeldung SEG 4:\nKein Änderungsbedarf. (27.08.2015)\nKDE-20\nSchlagwort: Shuntkomplikation\nErstellt: 08.08.2005\nAktualisiert: 08.01.2013\nICD: I82.8;I74.2; I74.3\nProblem/Erläuterung:\nSiehe Kodierempfehlung 466, Fallkonstellation 3.\nKodierempfehlung SEG 4:\nSiehe Kodierempfehlung 466, Fallkonstellation 3.\nKommentar FoKA:\nKDE wurde am 08.01.2013 in KDE-466 aufgenommen\n\nAktualisierung Kodierempfehlung SEG 4 vom 01.01.2019:\nProblem/ Erläuterung:\nFallkonstellation 1 (bis 2012 Kodierempfehlung Nr. 15)\nStationäre Aufnahme elektiv zur geplanten Revision eines Shunts wegen Knickstenose\n(Shunt aus alloplastischem Material) bei dialysepflichtiger Nierenkrankheit. Diagnostik und\nIndikationsstellung ambulant erfolgt, erfolgreicher Revisionseingriff.\nFallkonstellation 2\nStationäre Aufnahme elektiv zur geplanten Revision eines Shunts wegen Knickstenose bei\ndialysepflichtiger Nierenkrankheit (Shunt aus alloplastischem Material). Diagnostik und\nIndikationsstellung ambulant erfolgt, Revisionseingriff nicht erfolgreich, deshalb Indikation\nzur Shuntneuanlage.\nFallkonstellation 3 (bis 2012 Kodierempfehlung Nr. 20)\nStationäre Aufnahme elektiv zur Thrombektomie wegen Thrombose eines AV-Shunts\n(Shunt aus körpereigenem Material) bei dialysepflichtiger Nierenkrankheit. Diagnostik und\nIndikationsstellung ambulant erfolgt, erfolgreiche Thrombektomie.\nFallkonstellation 4\nStationäre Aufnahme elektiv zur Thrombektomie wegen Thrombose eines Shunts (Shunt\naus alloplastischem Material) bei dialysepflichtiger Nierenkrankheit. Diagnostik und\nIndikationsstellung ambulant erfolgt, erfolgreiche Thrombektomie.\nFallkonstellation 5 (bis 2012 Kodierempfehlung Nr. 245)\nStationäre Aufnahme zur geplanten Shuntneuanlage bei Shuntverschluss (AV-Shunt aus\nkörpereigenem Material oder Shunt mit alloplastischem Material) mit bekannter\ndialysepflichtiger Nierenkrankheit. Diagnostik und Indikationsstellung ambulant erfolgt.\nKodierempfehlung SEG 4:\nzu Fall 1:\nWenn der liegende Shunt (Shunt aus alloplastischem Material) auf Grund einer\nKomplikation nicht mehr funktionsfähig ist und die Aufnahme speziell zur Revision des\nShunts erfolgt, ist als Hauptdiagnose die Schlüsselnummer T82.5 Mechanische Komplikation\ndurc h sonstige Geräte und Implantate im Herzen und in den Gefäßen zuzuweisen.\nEs handelt sich hier um den spezifischen Kode, da neben der Information des verwendeten\nalloplastischen Materials noch zusätzlich der Organbezug und die Art der Komplikation\nabgebildet sind. Siehe hierzu auch die Hinweise und Beispiele unter dem Kode. Nach DKR\nD002 ist hier ausnahmsweise der T-Kode der spezifischere Kode und somit vorrangig vor\neinem unspezifischen Kode aus dem Organkapitel.\nZu Fall 2:\nWenn der liegende Shunt (Shunt aus alloplastischem Material) auf Grund einer\nKomplikation nicht mehr funktionsfähig ist und die Aufnahme speziell zur Revision des\nShunts erfolgt, ist als Hauptdiagnose die Schlüsselnummer T82.5 Mechanische Komplikation\ndurch sonstige Geräte und Implant ate im Herzen und in den Gefäßen zuzuweisen. Die\n\nShuntkomplikation hat den stationären Aufenthalt hauptsächlich veranlasst. Es war bei\nIndikationsstellung nicht absehbar, dass eine Shuntneuanlage erfolgen muss.\nEs handelt sich hier um den spezifischen Kode, da neben der Information des verwendeten\nalloplastischen Materials noch zusätzlich der Organbezug und die Art der Komplikation\nabgebildet sind. Siehe hierzu auch die Hinweise und Beispiele unter dem Kode. Nach DKR\nD002 ist hier ausnahmsweise der T-Kode der spezifischere Kode und somit vorrangig vor\neinem unspezifischen Kode aus dem Organkapitel.\nzu Fall 3:\nFür einen Patienten, der bereits vorher einen Shunt erhielt und bereits regelmäßig dialysiert\nwird, ist als Hauptdiagnose die Krankheit zu kodieren, die den stationären Aufenthalt\nhauptsächlich veranlasst hat. Dies ist die Thrombose im AV-Shunt, der in diesem Fall aus\nkörpereigenem Material (Vene/Arterie) besteht. Nach DKR D002 sind die Kodes aus dem\nOrgankapitel vorrangig vor den Kodes für Erkrankungen bzw. Störungen nach\nmedizinischen Maßnahmen und vor den T-Kodes zu verwenden.\nDa es sich in der Regel um eine Thrombose des venösen Schenkels handelt, ist als\nHauptdiagnose die Schlüsselnummer I80.80 Thrombo se, Phlebitis und Thrombophlebitis\noberflächlicher Gefäße der oberen Extremitäten zuzuweisen. Ist in seltenen Fällen auch der\narterielle Schenkel betroffen, kann dies durch den Kode I74.2 Embolie und Thrombose der\nArterien der oberen Extremitäten oder I74.3 Embolie und Thrombose der Arterien der\nunteren Extremitäten abgebildet werden.\nZu Fall 4:\nDie Shuntthrombose hat den stationären Aufenthalt hauptsächlich veranlasst. Wenn der\nliegende Shunt aus alloplastischem Material auf Grund einer Thrombose nicht mehr\nfunktionsfähig ist und die Aufnahme speziell zur Thrombektomie erfolgt, ist als\nHauptdiagnose die Schlüsselnummer T82.5 Mechanische Komplikation durch sonstige\nGeräte und Implantate im Herzen und in den Gefäßen zuzuweisen, da hierfür kein\nspezifischer Kode aus den Organkapiteln der ICD existiert.\nEs handelt sich hier um den spezifischen Kode, da neben der Information des verwendeten\nalloplastischen Materials noch zusätzlich der Organbezug und die Art der Komplikation\nabgebildet sind. Siehe hierzu auch die Hinweise und Beispiele unter dem Kode.\nzu Fall 5:\nAb 2007 ist in der speziellen Kodierrichtlinie 0912 der Passus Chirurgisch angelegte arterio-\nvenöse Fistel/Shunt gestrichen worden und somit für die Zuweisung der Hauptdiagnose die\nRegelung der DKR D002 anzuwenden. Verantwortlich für den stationären\nKrankenhausaufenthalt ist die Shuntneuanlage bei dialysepflichtiger Nierenkrankheit. Die\nShuntneuanlage erfolgt in Zielrichtung der Behandlung der dialysepflichtigen\nNierenkrankheit. Die Schlüsselnummer N18.5 ist somit Hauptdiagnose.\nDie Shuntneuanlage erfolgt weder zur Behebung einer Komplikation eines nicht mehr\nfunktionsfähigen Shunts noch stellt sie einen Revisionseingriff dar. Die Neuanlage ist bei\nfehlender Revisionsmöglichkeit wie die Shunterstanlage bei dialysepflichtiger\n\nNierenkrankheit zu werten. Die Aufnahme erfolgt explizit nicht zur Durchführung gezielter\nMaßnahmen am nicht mehr funktionsfähigen Shunt. Die Indikationsstellung zur Neuanlage\nwar bereits ambulant gestellt worden und somit die Ursache des Shuntversagens und die\nRevisionsmöglichkeit abgeklärt.\nKodierempfehlung: 20\nSchlagworte: Shuntkomplikation\nErstellt: 08.08.2005\nAktualisiert: 01.01.2019\nProblem /Erläuterung: Siehe Kodierempfehlung 466, Fallkonstellation 3.\nKodierempfehlung: Siehe Kodierempfehlung 466, Fallkonstellation 3.","pdfFile":"pdf/2020-12-02_KDE-466_Entscheidung-KDE-466-(ehemals-KDE-20)-Shuntkomplikation,-Shuntverschluss,-Shuntneuanlage,-Nativshunt.pdf","codes":{"icd":["T82.8","T82.5","I80.80","I74.2","I74.3","N18.5","I82.8"],"ops":["5-837.00"],"dkr":["D002","D015l"]},"category":"kde"},{"decisionDate":"2020-12-02","publicationDate":"2020-08-19","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-549","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 549 Beatmung, nichtinvasiv, intermittierend.pdf (42,91 kB)","sourceURL":"https://www.g-drg.de/content/download/10151/file/Entscheidung%20KDE%20549%20Beatmung,%20nichtinvasiv,%20intermittierend.pdf","keywords":"Entscheidung KDE 549 Beatmung, nichtinvasiv, intermittierend.pdf (42,91 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n02.12.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 549:\nDie Beatmung eines von Anbeginn an diskontinuierlich nichtinvasiv über Maske beatmeten,\nintensivmedizinisch versorgten Patienten richtet sich nach den Regelungen der jeweils gültigen\nDKR 1001 Maschinelle Beatmung. Diese schließen die Anrechnung von Zeiten mit Beatmung\nund beatmungsfreien Intervallen in dem dort geregelten Umfang mit ein.\nGültigkeit:\nDiese Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser,\ndie Krankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.02.2021 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n16.12.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen diese Entscheidung des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-549\nSchlagworte: Beatmung, nichtinvasiv, intermittierend\nErstellt: 13.10.2015\nAktualisiert: 01.01.2019\nProblem/Erläuterung:\nEin Patient wird auf der Intensivstation von Beginn an diskontinuierlich (über Maske)\nnichtinvasiv stundenweise beatmet. Wie ist die Dauer der Beatmung zu berechnen?\nKodierempfehlung SEG 4:\nAnzurechnen auf die Beatmungszeit sind ausschließlich die tatsächlich erbrachten Zeiten\nder Atemunterstützung.\nBei einer von Anfang an diskontinuierlichen Maskenbeatmung werden die Phasen zwischen\nden tatsächlich erbrachten Beatmungszeiten für die Gesamtbeatmungszeit nicht\nberücksichtigt, da es sich hierbei nicht um die in den DKR geregelte Entwöhnungsphase\nhandelt.\nKommentierung FoKA:\nDissens:\nIn der DKR 1001 steht im Wortlaut: \"Zur Entwöhnung vom Respirator zählt auch die\nmaschinelle Unterstützung der Atmung durch intermittierende Phasen assistierter\nnichtinvasiver Beatmung bzw. Atemunterstützung wie z.B. durch Masken-CPAP/ASB oder\ndurch Masken-CPAP jeweils im Wechsel mit Spontanatmung ohne maschinelle\nUnterstützung.\"\nEine Maskenbeatmung (NIV) ist eine Beatmung im Sinne der DKR 1001, wenn der Patient\nintensivmedizinisch versorgt wird (vgl. Anfrage 44). Die DKR enthält keine Vorschriften, die\neine abweichende Zählweise der Beatmungsstunden im Vergleich zu einer invasiven\nBeatmung rechtfertigen würden. Somit müssen beatmungsfreie Intervalle im Rahmen einer\nEntwöhnung (Weaning) auch bei einer NIV-Beatmung berücksichtigt werden. Von einem\nWeaning ist auszugehen, wenn der Behandlungsplan darauf ausgerichtet ist, die Beatmung\nzu beenden oder bei einem heimbeatmeten Patienten die Intensität der Beatmung zu\nreduzieren, bis eine stabile respiratorische Situation erreicht ist. Die Intensität einer\nBeatmung ist z.B. durch die inspiratorische Sauerstoffkonzentration, die Beatmungsdrücke\noder die Dauer der beatmungsfreien Intervalle charakterisiert. Siehe auch Anfrage 0100.\n(18.01.2016)","pdfFile":"pdf/2020-12-02_KDE-549_Entscheidung-KDE-549-Beatmung,-nichtinvasiv,-intermittierend.pdf-(42,91-kB).pdf","codes":{"icd":[],"ops":[],"dkr":[]},"category":"kde"},{"decisionDate":"2020-12-02","publicationDate":"2020-10-06","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-583","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 583 Krampfanfall, Hirnmetastase, Bronchialkarzinom.pdf (42,68 kB)","sourceURL":"https://www.g-drg.de/content/download/10152/file/Entscheidung%20KDE%20583%20Krampfanfall,%20Hirnmetastase,%20Bronchialkarzinom.pdf","keywords":"Entscheidung KDE 583 Krampfanfall, Hirnmetastase, Bronchialkarzinom.pdf (42,68 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n02.12.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 583:\nWird ein Patient wegen einer symptomatischen Epilepsie auf dem Boden von Hirnmetastasen bei\neiner Tumorerkrankung aufgenommen und wird ausschließlich die symptomatische Epilepsie\nbehandelt, so sind gemäß DKR 0201 Neubildungen und Schlichtungsausschuss Bund alter\nFassung (Beschluss vom 04.07.2016) die symptomatische Epilepsie als Hauptdiagnose sowie\ndie Hirnmetastasen und der Tumor als Nebendiagnosen zu verschlüsseln.\nGültigkeit:\nDiese Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser,\ndie Krankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.02.2021 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n16.12.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen diese Entscheidung des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-583\nSchlagworte: Krampfanfall, Hirnmetastase, Bronchialkarzinom\nErstellt: 27.06.2017\nStand: 15.09.2017\nAktualisiert: 01.01.2019\nProblem/Erläuterung\nEin Patient wird wegen einer symptomatischen Epilepsie mit komplexen fokalen, sekundär\ngeneralisierenden Anfällen auf dem Boden von Hirnmetastasen eines Bronchialkarzinoms\nstationär aufgenommen. Ein Behandlungsaufwand bezüglich des Bronchialkarzinoms oder\nder Hirnmetastasen selbst besteht während des Aufenthaltes nicht. Wie sind Haupt- und\nNebendiagnose zu kodieren?\nKodierempfehlung SEG 4:\nGemäß dem Beschluss des Schlichtungsausschusses vom 25.07.2016 sind als Hauptdiagnose\nG40.2 Lokalisationsbezogene (fokale) (partielle) symptomatische Epilepsie und epileptische\nSyndrome mit komplexen fokalen Anfällen und als Nebendiagnose C34.- Bösartige\nN eubildung der Bronchien und der Lunge zuzuweisen. Die Hirnmetastasen sind ohne\nAufwand nicht zu kodieren. Siehe auch Kodierempfehlung 235.\nKommentierung FoKA:\nDissens (15.09.2017):\nAls Hauptdiagnose ist der Krampfanfall zu verschlüsseln.\nDie dem Krampfanfall zugrunde liegende Erkrankung ist die Hirnmetastase. Die\nHirnmetastase ist gemäß DKR D002f (und 0201n):\"Wenn sich ein Patient mit einem\nSymptom vorstellt und die zugrunde liegende Krankheit zum Zeitpunkt der Aufnahme\nbekannt ist, jedoch nur das Symp tom behandelt wird, ist das Symptom als Hauptdiagnose\nund die zugrunde liegende Krankheit als Nebendiagnose zu kodieren.\" als Nebendiagnose\nzu verschlüsseln.\nGemäß dem Beschluss des Schlichtungsausschusses ist das primär ursächliche\nBronchialkarzinom als Nebendiagnose zu kodieren.","pdfFile":"pdf/2020-12-02_KDE-583_Entscheidung-KDE-583-Krampfanfall,-Hirnmetastase,-Bronchialkarzinom.pdf-(42,68-kB).pdf","codes":{"icd":["G40.2","C34"],"ops":[],"dkr":["D002f"]},"category":"kde"},{"decisionDate":"2020-12-02","publicationDate":"2020-12-16","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/kde-entscheidungen-des-schlichtungsausschusses-2020/kde-entscheidungen-2020-nach-kde-nummer","id":"KDE-584","categoryLabel":"KDE-Entscheidung 2020","title":"Entscheidung KDE 584 Weaning.pdf (40,81 kB)","sourceURL":"https://www.g-drg.de/content/download/10153/file/Entscheidung%20KDE%20584%20Weaning.pdf","keywords":"Entscheidung KDE 584 Weaning.pdf (40,81 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n02.12.2020\nhat der Schlichtungsausschuss nach § 19 KHG über die zwischen der Sozialmedizinischen\nExpertengruppe Vergütung und Abrechnung der Medizinischen Dienste (SEG 4) und dem\nFachausschuss für ordnungsgemäße Kodierung und Abrechnung der Deutschen Gesellschaft\nfür Medizincontrolling (FoKA) bis zum 31.12.2019 als strittig festgestellten\nKodierempfehlungen (KDE) nach § 19 Abs. 5 KHG, nach konsentiertem Antrag der\nDeutschen Krankenhausgesellschaft, des GKV-Spitzenverbandes und des Verbandes der\nPrivaten Krankenversicherung e.V. wie folgt entschieden:\nEntscheidung KDE 584:\nDie Berücksichtigung des Weanings bei der Ermittlung der Gesamtbeatmungsdauer richtet sich\nnach den Regeln der jeweils gültigen DKR 1001 Maschinelle Beatmung. Diese schließen die\nAnrechnung von Zeiten mit Beatmung und beatmungsfreien Intervallen im Rahmen des\nWeanings in dem dort geregelten Umfang mit ein.\nGültigkeit:\nDiese Entscheidung des Schlichtungsausschusses gilt für die zugelassenen Krankenhäuser,\ndie Krankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.02.2021 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n16.12.2020 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen diese Entscheidung des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nHistorie:\nKodierempfehlung, Fragestellung und Verlauf der Diskussion zwischen der\nSozialmedizinischen Expertengruppe Vergütung und Abrechnung der Medizinischen\nDienste (SEG 4) und dem Fachausschuss für ordnungsgemäße Kodierung und Abrechnung\nder Deutschen Gesellschaft für Medizincontrolling (FoKA).\nKDE-584:\nSchlagworte: Weaning\nErstellt: 31.08.2017\nStand: 15.09.2017\nAktualisiert: 01.01.2019\nProblem/Erläuterung:\nSetzt ein Weaning eine Mindestdauer einer vorangegangenen Beatmung voraus?\nKodierempfehlung SEG 4:\nEin Weaning (Entwöhnung) gemäß DKR 1001 mit intermittierenden Phasen von Beatmung\nund Spontanatmung setzt eine vorherige Gewöhnung durch eine durchgehende Beatmung\nfür mindestens 48 Stunden voraus.\nKommentierung FoKA:\nDissens (15.09.2017):\nDie Aussage der SEG 4 ist falsch. Die Dauer einer durchgehenden Beatmung als\nVoraussetzung für ein Weaning ist in den Kodierrichtlinien nicht enthalten. Fachlich ist die\nAussage ebenfalls nicht nachvollziehbar.","pdfFile":"pdf/2020-12-02_KDE-584_Entscheidung-KDE-584-Weaning.pdf-(40,81-kB).pdf","codes":{"icd":[],"ops":[],"dkr":[]},"category":"kde"},{"decisionDate":"2021-06-23","publicationDate":"2021-07-21","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/entscheidungen-des-schlichtungsausschusses","id":"S20210005","categoryLabel":"Schlichtungsverfahren nach § 19 KHG","title":"Entscheidung _S20210005 (Kodierung des Fibrinogenmangels) 21.07.2021.pdf (130,84 kB)","sourceURL":"https://www.g-drg.de/content/download/10458/file/Entscheidung%20_S20210005%20%28Kodierung%20des%20Fibrinogenmangels%29%2021.07.2021.pdf","keywords":"Entscheidung _S20210005 (Kodierung des Fibrinogenmangels) 21.07.2021.pdf (130,84 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n23.06.2021\nhat der Schlichtungsausschuss nach § 19 KHG über den Antrag S20210005 Kodierung des\nFibrinogenmangels des Klinikums der Universität München AöR wie folgt entschieden:\nEntscheidung S20210005 Kodierung des Fibrinogenmangels:\nMit dem Kode D65.0 Erworbene Afibrinogenämie ist auch ein erworbener Mangel an\nFibrinogen zu kodieren.\nBegründung:\nFür die Kodierung des im Antrag beschriebenen erworbenen Fibrinogenmangels\n(Hypofibrinogenämie) fehlt im systematischen Verzeichnis ein, den Sachverhalt vollständig\nwiedergebender Kode. Das Alphabetische Verzeichnis zur ICD-10-GM verweist sowohl für\nden erworbenen Fibrinogenmangel, als auch für die erworbene Afibrinogenämie, die\nerworbene Fibrinogenopenie sowie die erworbene Hypofibrinogenämie auf den Kode\nD65.0. Die Begriffe Afibrinogenämie, Fibrinogenopenie und Hypofibrinogenämie werden\ndem Kode D68.8 Sonstige näher bezeichnete Koagulopathien zugeordnet. Im\nsystematischen Verzeichnis ist alternativ noch der Kode D68.4 Erworbener Mangel an\nGerinnungsfaktoren zu finden.\nBei beiden letztgenannten Kodes (D68.8 sowie die D68.4) ist jedoch der spezifische Bezug\nzum Fibrinogenmangel nicht enthalten. Unter Berücksichtigung der Vorgaben der\nDeutschen Kodierrichtlinie D014 Im Alphabetischen Verzeichnis verwendete formale\nVereinbarungen war die Mehrheit der Mitglieder des Schlichtungsausschusses der Meinung,\ndass die spezifischere Kodierung mit dem Kode D65.0 gegeben ist.\nWünschenswert wäre jedoch eine zukünftige Differenzierung in der ICD-10-GM, um den\nSachverhalt einer erworben Afibrinogenämie und einer erworbenen Hypofibrinogenämie\ndifferenziert abbilden zu können.\n\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.09.2021 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 21.07.2021 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nRechtsbehelfsbelehrung:\nGegen diese Entscheidung des Schlichtungsausschusses kann innerhalb eines Monats nach\nBekanntgabe Klage beim Sozialgericht Berlin, Invalidenstr. 52, 10557 Berlin, schriftlich oder\nzu Protokoll des Urkundsbeamten der Geschäftsstelle erhoben werden.\nSiegburg, 21.07.2021\nDr. Franz Metzger\nVorsitzender des Schlichtungsausschusses nach § 19 KHG","pdfFile":"pdf/2021-06-23_S20210005_Entscheidung-_S20210005-(Kodierung-des-Fibrinogenmangels)-21.07.2021.pdf-(130,84-kB).pdf","codes":{"icd":["D65.0","D68.8","D68.4"],"ops":[],"dkr":["D014"]},"category":"regular"},{"decisionDate":"2022-03-23","publicationDate":"2022-04-27","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/entscheidungen-des-schlichtungsausschusses","id":"S20220001","categoryLabel":"Schlichtungsverfahren nach § 19 KHG","title":"Entscheidung_S20220001 (Thrombektomie ZE 133) 27.04.2022.pdf (47,9 kB)","sourceURL":"https://www.g-drg.de/content/download/11145/file/Entscheidung_S20220001%20%28Thrombektomie%20ZE%20133%29%2027.04.2022.pdf","keywords":"Entscheidung_S20220001 (Thrombektomie ZE 133) 27.04.2022.pdf (47,9 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n23.03.2022\nhat der Schlichtungsausschuss nach § 19 KHG über den Antrag S20220001 „Thrombektomie\nZE 133“ der Helios Kliniken GmbH (hier IK 261201356) wie folgt entschieden:\nEntscheidung S20220001 Thrombektomie ZE 133:\nDie vorliegende Konstellation wurde durch die Änderung des OPS-Kataloges 2022\nabschließend geregelt. Demnach gilt ab 01.01.2022:\nSofern ein Stentretriever, zu kodieren mit den OPS-Kodes 8-83b.84 bis .86 und zusätzlich ein\nThrombektomie-Aspirationskatheter, zu kodieren mit den OPS-Kodes 8-83b.87 bis .89\nverwendet werden, können die jeweiligen Zusatzentgelte abgerechnet werden.\nBis zum 31.12.2021 gilt:\nSofern ein Stentretriever-System (bestehend aus mehreren Komponenten wie z.B.\nFührungsdraht, Katheter, weitere Komponenten), zu kodieren mit den OPS-Kodes 8-83b.84\nbis .86, und zusätzlich ein Aspirationskatheter-System (bestehend aus mehreren\nKomponenten wie z.B. Microdraht, Aspirationskatheter, Vorrichtung zur Aspiration), zu\nkodieren mit den OPS-Kodes 8-83b.80 bis .83, verwendet werden, können für die Systeme\njeweils die Zusatzentgelte ZE152 (für das Stentretriever-System) und ZE133 (für das\nAspirationskatheter-System) abgerechnet werden. Die individuelle Zusammenstellung der\nSysteme aus zur Leistungserbringung erforderlichen und geeigneten Einzel-Komponenten\nist möglich.\nBegründung:\nAb dem Jahr 2022 wurde der Sachverhalt durch Änderung des OPS geregelt.\nDa nicht auszuschließen ist, dass es noch Fälle aus dem Vorjahr geben kann, die in den\nRegelungsbereich des Schlichtungsausschusses fallen können, wurde auch für diesen\nZeitraum eine Entscheidung formuliert, die sich an der im OPS 2022 getroffenen Regelung\norientiert.\n\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.06.2022 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 27.04.2022 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nRechtsbehelfsbelehrung:\nGegen diese Entscheidung des Schlichtungsausschusses kann innerhalb eines Monats nach\nBekanntgabe Klage beim Sozialgericht Berlin, Invalidenstr. 52, 10557 Berlin, schriftlich oder\nzu Protokoll des Urkundsbeamten der Geschäftsstelle erhoben werden.\nSiegburg, 27.04.2022\nDr. Franz Metzger\nVorsitzender des Schlichtungsausschusses nach § 19 KHG","pdfFile":"pdf/2022-03-23_S20220001_Entscheidung_S20220001-(Thrombektomie-ZE-133)-27.04.2022.pdf-(47,9-kB).pdf","codes":{"icd":[],"ops":["8-83b.84","8-83b.87","8-83b.80"],"dkr":[]},"category":"regular"},{"decisionDate":"2022-03-23","publicationDate":"2022-04-27","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/entscheidungen-des-schlichtungsausschusses","id":"S20220002","categoryLabel":"Schlichtungsverfahren nach § 19 KHG","title":"Entscheidung_S20220002 (Adh&auml;siolyse) 27.04.2022.pdf (47,14 kB)","sourceURL":"https://www.g-drg.de/content/download/11144/file/Entscheidung_S20220002%20%28Adh%C3%A4siolyse%29%2027.04.2022.pdf","keywords":"Entscheidung_S20220002 (Adh&auml;siolyse) 27.04.2022.pdf (47,14 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n23.03.2022\nhat der Schlichtungsausschuss nach § 19 KHG über den Antrag S20220002 „Adhäsiolyse“ der\nHelios Weißeritztal-Kliniken wie folgt entschieden:\nEntscheidung S20220002 Adhäsiolyse:\nDie DKR 1102 ist anzuwenden. Ein „relevanter Aufwand“ liegt beispielsweise vor, wenn:\n- das Fortschreiten einer Operation oder die eigentlich geplante Operation durch eine\nnotwendig werdende Adhäsiolyse deutlich behindert oder verzögert wird oder\n- außerhalb der Präparation des geplanten Operationsfeldes eine eigenständige\naufwendige Adhäsiolyse vorgenommen wird.\nEine Adhäsiolyse, die durch einfaches Lösen mittels Schere (wenige Scherenschläge) erfolgt,\nstellt keinen relevanten Aufwand dar.\nBegründung:\nEinleitend ist darauf hinzuweisen, dass im vorliegenden Fall die DKR 1102 anzuwenden ist,\nda die speziellen Kodierrichtlinien vor den allgemeinen Kodierrichtlinien gelten. Eine\nAblehnung der Kodierung mit Verweis auf die in der Kodierrichtlinie P001 im Absatz\n„Prozedurenkomponenten“ beschriebene monokausale Kodierung trägt daher inhaltlich\nnicht.\nDie im Antrag vorgeschlagene Abänderung der Begrifflichkeit „relevanter Aufwand“ in\n„erheblicher Mehraufwand“ erscheint nicht geeignet um zu einer Problemlösung\nbeizutragen. Wünschenswert wäre es zu einer präziseren Definition des Begriffes\n„relevanter Aufwand“ zu kommen, entsprechende Vorschläge sollten z.B. von den\nFachgesellschaften eingebracht werden.\nInsofern dienen die in der Entscheidung aufgenommenen Beispiele zur Erläuterung von\nunstrittigen Positionen, diese stellen jedoch keine abschließende Definition dar.\n\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.06.2022 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 27.04.2022 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nRechtsbehelfsbelehrung:\nGegen diese Entscheidung des Schlichtungsausschusses kann innerhalb eines Monats nach\nBekanntgabe Klage beim Sozialgericht Berlin, Invalidenstr. 52, 10557 Berlin, schriftlich oder\nzu Protokoll des Urkundsbeamten der Geschäftsstelle erhoben werden.\nSiegburg, 27.04.2022\nDr. Franz Metzger\nVorsitzender des Schlichtungsausschusses nach § 19 KHG","pdfFile":"pdf/2022-03-23_S20220002_Entscheidung_S20220002-(Adh&auml;siolyse)-27.04.2022.pdf-(47,14-kB).pdf","codes":{"icd":[],"ops":[],"dkr":["P001"]},"category":"regular"},{"decisionDate":"2022-03-23","publicationDate":"2022-04-27","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/entscheidungen-des-schlichtungsausschusses","id":"S20220003","categoryLabel":"Schlichtungsverfahren nach § 19 KHG","title":"Entscheidung_S20220003 (Erregerkodierung) 27.04.2022.pdf (42,55 kB)","sourceURL":"https://www.g-drg.de/content/download/11143/file/Entscheidung_S20220003%20%28Erregerkodierung%29%2027.04.2022.pdf","keywords":"Entscheidung_S20220003 (Erregerkodierung) 27.04.2022.pdf (42,55 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n23.03.2022\nhat der Schlichtungsausschuss nach § 19 KHG über den Antrag S20220003\n„Erregerkodierung“ der Helios Weißeritztal-Kliniken wie folgt entschieden:\nEntscheidung S20220003 Erregerkodierung:\nDer Antrag wird nach § 8 Abs. 1 der Geschäftsordnung für den Schlichtungsausschuss nach\n§ 19 KHG wegen Unzulässigkeit abgelehnt.\nBegründung:\nDas Schlichtungsverfahren wurde mit Feststellung der Unzulässigkeit durch den\nSchlichtungsausschuss für beendet erklärt. Die Unzulässigkeit des Antrags lag aufgrund des\nZurückziehens des Regelungsvorschlags durch die Antragstellerin vor. Ein solcher ist nach\n§ 12 Abs. 2 der Vereinbarung über die Bildung eines Schlichtungsausschusses nach § 19 KHG\nund nach § 3 Abs. 4 der Geschäftsordnung für den Schlichtungsausschuss nach § 19 KHG für\neinen vollständigen Antrag aber erforderlich.\nRechtsbehelfsbelehrung:\nGegen diese Entscheidung des Schlichtungsausschusses kann innerhalb eines Monats nach\nBekanntgabe Klage beim Sozialgericht Berlin, Invalidenstr. 52, 10557 Berlin, schriftlich oder\nzu Protokoll des Urkundsbeamten der Geschäftsstelle erhoben werden.\nSiegburg, 27.04.2022\nDr. Franz Metzger\nVorsitzender des Schlichtungsausschusses nach § 19 KHG","pdfFile":"pdf/2022-03-23_S20220003_Entscheidung_S20220003-(Erregerkodierung)-27.04.2022.pdf-(42,55-kB).pdf","codes":{"icd":[],"ops":[],"dkr":[]},"category":"regular"},{"decisionDate":"2022-03-23","publicationDate":"2022-04-27","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/entscheidungen-des-schlichtungsausschusses","id":"S20220004","categoryLabel":"Schlichtungsverfahren nach § 19 KHG","title":"Entscheidung_S20220004 (Sepsiskodierung) 27.04.2022.pdf (44,61 kB)","sourceURL":"https://www.g-drg.de/content/download/11142/file/Entscheidung_S20220004%20%28Sepsiskodierung%29%2027.04.2022.pdf","keywords":"Entscheidung_S20220004 (Sepsiskodierung) 27.04.2022.pdf (44,61 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n23.03.2022\nhat der Schlichtungsausschuss nach § 19 KHG über den Antrag S20220004\n„Sepsiskodierung“ der Helios Weißeritztal-Kliniken wie folgt entschieden:\nEntscheidung S20220004 Sepsiskodierung:\nDer Antrag wird abgelehnt. Die Zuweisung der Hauptdiagnose ist in der DKR D002\numfassend geregelt.\nBegründung:\nDie Antragstellerin bittet in ihrem Antrag um Priorisierung der Sepsiskodierung in Bezug\nauf die Hauptdiagnose unabhängig vom Ressourcenverbrauch. Der Antrag war abzulehnen,\nda die Erforderlichkeit einer abweichenden Regelung von den in der DKR D002 getroffenen\nRegelungen, die in bestimmten Fällen gerade die Auswahl der Hauptdiagnose nach dem\nRessourcenverbrauch vorsehen, von der Antragstellerin nicht dargestellt werden konnte.\n\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.06.2022 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 27.04.2022 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nRechtsbehelfsbelehrung:\nGegen diese Entscheidung des Schlichtungsausschusses kann innerhalb eines Monats nach\nBekanntgabe Klage beim Sozialgericht Berlin, Invalidenstr. 52, 10557 Berlin, schriftlich oder\nzu Protokoll des Urkundsbeamten der Geschäftsstelle erhoben werden.\nSiegburg, 27.04.2022\nDr. Franz Metzger\nVorsitzender des Schlichtungsausschusses nach § 19 KHG","pdfFile":"pdf/2022-03-23_S20220004_Entscheidung_S20220004-(Sepsiskodierung)-27.04.2022.pdf-(44,61-kB).pdf","codes":{"icd":[],"ops":[],"dkr":["D002"]},"category":"regular"},{"decisionDate":"2022-07-20","publicationDate":"2022-08-17","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/entscheidungen-des-schlichtungsausschusses","id":"S20220008","categoryLabel":"Schlichtungsverfahren nach § 19 KHG","title":"Entscheidung_S20220008 (Kl&auml;rung Erregerkodierung bei Infektion Sekund&auml;rinfektion einer offenen Wunde (z.B. Hautulkus)) 17.08.2022.pdf (220,75 kB)","sourceURL":"https://www.g-drg.de/content/download/11695/file/Entscheidung_S20220008%20%28Kl%C3%A4rung%20Erregerkodierung%20bei%20Infektion%20Sekund%C3%A4rinfektion%20einer%20offenen%20Wunde%20%28z.B.%20Hautulkus%29%29%2017.08.2022.pdf","keywords":"Entscheidung_S20220008 (Kl&auml;rung Erregerkodierung bei Infektion Sekund&auml;rinfektion einer offenen Wunde (z.B. Hautulkus)) 17.08.2022.pdf (220,75 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n20.07.2022\nhat der Schlichtungsausschuss nach § 19 KHG über den Antrag S20220008 „Klärung\nErregerkodierung bei Infektion/ Sekundärinfektion einer offenen Wunde (z.B. Hautulkus)“\nder Helios Weißeritztal-Kliniken GmbH wie folgt entschieden:\nEntscheidung S20220008\nKlärung Erregerkodierung bei Infektion/ Sekundärinfektion einer offenen Wunde\n(z.B. Hautulkus):\nBei offenen Wunden mit klaren Zeichen einer Infektion (z.B. Rötung, Schwellung\nÜberwärmung) wird zusätzlich zu einem geeigneten Kode für die Infektion (z.B. L08.8) ein\nKode aus B95.-! Streptokokken und Staphylokokken als Ursache von Krankheiten, die in\nanderen Kapiteln klassifiziert sind , B96.-! Sonstige näher bezeichnete Bakterien als Ursache\nvon Krankheiten, die in anderen Kapiteln klassifiziert sind oder B98.-! Sonstige näher\nbezeichnete infektiöse Erreger als Ursache von Krankheit en, die in anderen Kapiteln\nklassifiziert sind angegeben, sofern entsprechende Bakterien nachgewiesen werden und\ndiese einen zusätzlichen Aufwand im Sinne der DKR D003 begründen.\nIm Falle einer chronischen offenen Wunde ohne klare Zeichen einer Infektion kann eine\nnachgewiesene pathologische Besiedlung (nachgewiesen durch ein anerkanntes Scoring-\nInstrument zum Infektionsrisiko) mit Bakterien über die Kombination eines geeigneten\nKodes für die Wunde (z.B. L89.- Dekubitalgeschwür und Druckzone ) und der Kodes B95.-!,\nB96.-!, B98.-! kodiert werden, falls eine diesbezüglich resistenzgerechte\nArzneimitteltherapie erfolgt. In diesem Fall ist der Terminus „als Ursache von Krankheiten“\nzu den Kodes B95.\n-!, B96.-! und B98.\n-! sowohl als primärursächliche Kausalität als auch im\nSinne einer sekundär aggravierenden bzw. krankheitsunterhaltenden Ursache zu werten.\nBegründung:\nMit dem ersten Absatz der oben dargestellten Entscheidung des Schlichtungsausschusses\nerfolgt eine Klarstellung, dass bei Wunden, bei denen eine Infektion vorliegt, neben dem\nKode für die Wunde auch die Infektion zu kodieren ist. Wurde ein Keim, der ursächlich für\ndie Infektion ist, nachgewiesen, ist dieser in Kombination mit der Infektion zu kodieren,\nsofern die in der DKR D003 zur Kodierung einer Nebendiagnose genannten\nVoraussetzungen erfüllt sind. Bezüglich der Auswahl der zu kodierenden ICD-Kodes, der\nKodierung der Hauptdiagnose und der Kodierung von Nebendiagnosen gelten die in Frage\nkommenden allgemeinen und speziellen Kodierrichtlinien. Die dort festgelegten Vorgaben\nwerden durch den ersten Absatz nicht tangiert.\n\nDer zweite Absatz regelt die Kodierung eines Keimnachweises in einer chronischen Wunde,\nbei der aber keine klaren Zeichen einer Infektion vorliegen. Voraussetzung ist das Vorliegen\neiner Risikowunde sowie die Durchführung einer resistenzgerechten Arzneimitteltherapie.\nNur in diesen Fällen ist es zulässig, den Erregerschlüssel (B95.-!, B96.-!, B98.-!) in\nKombination mit dem Kode für die chronische Wunde zu verwenden. Das Vorliegen einer\nRisikowunde muss durch die Anwendung eines wissenschaftlich anerkannten Scoring-\nInstruments zum Infektionsrisiko (z.B. wound at risk score (W.A.R. score) ≥ 3) aus der\nDokumentation ableitbar sein. Die Kodierung bei einer „einfachen“ Keimbesiedelung ist\ndaher ausgeschlossen.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.10.2022 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 17.08.2022 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nRechtsbehelfsbelehrung:\nGegen diese Entscheidung des Schlichtungsausschusses kann innerhalb eines Monats nach\nBekanntgabe Klage beim Sozialgericht Berlin, Invalidenstr. 52, 10557 Berlin, schriftlich oder\nzu Protokoll des Urkundsbeamten der Geschäftsstelle erhoben werden.\nSiegburg, 17.08.2022\nDr. Franz Metzger\nVorsitzender des Schlichtungsausschusses nach § 19 KHG","pdfFile":"pdf/2022-07-20_S20220008_Entscheidung_S20220008-(Kl&auml;rung-Erregerkodierung-bei-Infektion-Sekund&auml;rinfektion-einer-off.pdf","codes":{"icd":["L08.8","B95","B96","B98","L89"],"ops":[],"dkr":["D003"]},"category":"regular"},{"publicationDate":"2022-07-27","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/entscheidungen-des-schlichtungsausschusses","id":"S20220009","categoryLabel":"Schlichtungsverfahren nach § 19 KHG","title":"Entscheidung_S20220009 (Beatmungsstunden ...) 27.07.2022.pdf (43,46 kB)","sourceURL":"https://www.g-drg.de/content/download/11687/file/Entscheidung_S20220009%20%28Beatmungsstunden%20...%29%2027.07.2022.pdf","keywords":"Entscheidung_S20220009 (Beatmungsstunden ...) 27.07.2022.pdf (43,46 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIm schriftlichen Verfahren vom\n29.06.2022\nhat der Schlichtungsausschuss nach § 19 KHG über den Antrag S20220009\n„Beatmungsstunden OPS 8-718.8 bzw. 8-718.9 (ZE2022-190)“ des Fachkrankenhauses\nKloster Grafschaft GmbH wie folgt entschieden:\nEntscheidung S20220009\nBeatmungsstunden OPS 8-718.8 bzw. 8-718.9 (ZE2022-190):\nDer Antrag wird nach § 8 Abs. 1 der Geschäftsordnung für den Schlichtungsausschuss nach\n§ 19 KHG wegen Unzulässigkeit abgelehnt.\nBegründung:\nDer vorliegende Antrag erfüllt nicht die Voraussetzung nach § 10 Abs. 1 Ziffer 5 der\nVereinbarung über die Bildung des Schlichtungsausschusses nach § 19 KHG.\nBeantragt wird eine ergänzende Erläuterung in den Hinweisen zu einem OPS Schlüssel, zu\ndem ein regelungsgleicher Antrag im aktuellen Vorschlagsverfahren zur Weiterentwicklung\ndes OPS für das Jahr 2023 beim BfArM eingereicht worden ist. Somit ist zur Klärung der\nFragestellung die originäre Zuständigkeit durch das Vorschlagsverfahren für die ICD-10-GM\nund den OPS beim BfArM gegeben.\nRechtsbehelfsbelehrung:\nGegen diese Entscheidung des Schlichtungsausschusses kann innerhalb eines Monats nach\nBekanntgabe Klage beim Sozialgericht Berlin, Invalidenstr. 52, 10557 Berlin, schriftlich oder\nzu Protokoll des Urkundsbeamten der Geschäftsstelle erhoben werden.\nSiegburg, 27.07.2022\nDr. Franz Metzger\nVorsitzender des Schlichtungsausschusses nach § 19 KHG","pdfFile":"pdf/2022-07-27_S20220009_Entscheidung_S20220009-(Beatmungsstunden-...)-27.07.2022.pdf-(43,46-kB).pdf","codes":{"icd":[],"ops":["8-718.8","8-718.9"],"dkr":[]},"category":"regular"},{"publicationDate":"2022-09-01","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/entscheidungen-des-schlichtungsausschusses","id":"S20220007","categoryLabel":"Schlichtungsverfahren nach § 19 KHG","title":"Entscheidung_S20220007 (Kl&auml;rung) 01.09.2022.pdf (45,95 kB)","sourceURL":"https://www.g-drg.de/content/download/11714/file/Entscheidung_S20220007%20%28Kl%C3%A4rung%29%2001.09.2022.pdf","keywords":"Entscheidung_S20220007 (Kl&auml;rung) 01.09.2022.pdf (45,95 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIm schriftlichen Verfahren vom\n04.08.2022\nhat der Schlichtungsausschuss nach § 19 KHG über den Antrag S20220007 „Klärung“ des\nEvangelischen Krankenhauses Niederrhein wie folgt entschieden:\nEntscheidung S20220007 Klärung:\nDer Antrag wird nach § 8 Abs. 1 der Geschäftsordnung für den Schlichtungsausschuss nach\n§ 19 KHG wegen Unzulässigkeit abgelehnt.\nBegründung:\nDer vorliegende Antrag erfüllt nicht die Voraussetzung nach § 10 Abs. 1 Ziffer 5 der\nVereinbarung über die Bildung des Schlichtungsausschusses nach § 19 KHG.\nBeantragt wird eine Änderung bezüglich der Strukturmerkmale zu einem OPS Schlüssel, zu\ndem ein vergleichbarer Antrag im aktuellen Vorschlagsverfahren zur Weiterentwicklung\ndes OPS für das Jahr 2023 beim BfArM eingereicht worden ist. Somit ist zur Klärung der\nFragestellung die originäre Zuständigkeit durch das Vorschlagsverfahren für die ICD-10-GM\nund den OPS beim BfArM gegeben.\nRechtsbehelfsbelehrung:\nGegen diese Entscheidung des Schlichtungsausschusses kann innerhalb eines Monats nach\nBekanntgabe Klage beim Sozialgericht Berlin, Invalidenstr. 52, 10557 Berlin, schriftlich oder\nzu Protokoll des Urkundsbeamten der Geschäftsstelle erhoben werden.\nSiegburg, 01.09.2022\nDr. Franz Metzger\nVorsitzender des Schlichtungsausschusses nach § 19 KHG","pdfFile":"pdf/2022-09-01_S20220007_Entscheidung_S20220007-(Kl&auml;rung)-01.09.2022.pdf-(45,95-kB).pdf","codes":{"icd":[],"ops":[],"dkr":[]},"category":"regular"},{"decisionDate":"2022-09-21","publicationDate":"2022-10-19","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/entscheidungen-des-schlichtungsausschusses","id":"S20220010","categoryLabel":"Schlichtungsverfahren nach § 19 KHG","title":"Entscheidung_S20220010 (Kl&auml;rung Notwendigkeit einer t&auml;glichen art. oder kap. Blutgasanalyse ...) 19.10.2022.pdf (47,51 kB)","sourceURL":"https://www.g-drg.de/content/download/11905/file/Entscheidung_S20220010%20%28Kl%C3%A4rung%20Notwendigkeit%20einer%20t%C3%A4glichen%20art.%20oder%20kap.%20Blutgasanalyse%20...%29%2019.10.2022.pdf","keywords":"Entscheidung_S20220010 (Kl&auml;rung Notwendigkeit einer t&auml;glichen art. oder kap. Blutgasanalyse ...) 19.10.2022.pdf (47,51 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n21.09.2022\nhat der Schlichtungsausschuss nach § 19 KHG über den Antrag S20220010 „Klärung:\nNotwendigkeit einer täglichen art. oder kap. Blutgasanalyse zur Berechnung von\nBeatmungsstunden“ des Klinikums der Universität Regensburg wie folgt entschieden:\nEntscheidung S20220010\nKlärung: Notwendigkeit einer täglichen art. oder kap. Blutgasanalyse zur\nBerechnung von Beatmungsstunden:\nDas zur Kodierung von Beatmungsstunden gemäß DKR 1001 erforderliche Monitoring der\nAtmung erfolgt im Einzelfall gemäß den bestehenden medizinischen Erfordernissen. Es\numfasst dabei die Gasaustauschparameter (z.B. pO2, pH, pCO2, sO2) mit invasiven oder\nnicht invasiven Messverfahren (z.B. arterieller, kapillärer oder venöser Blutgasanalyse,\nPulsoxymetrie, transkutane Oxymetrie und CO2-Messung) sowie relevante Gerätemesswerte\n(z.B. Atemfrequenz, Atemzugvolumen, Atemminutenvolumen, Beatmungsdrücke).\nBegründung:\nDie Kodierrichtlinie (DKR) 1001 Maschinelle Beatmung macht hinsichtlich der strittigen\nFrage, was ein Monitoring der Atmung beinhalten muss, keine differenzierten Vorgaben.\nDie Ausgestaltung der intensivmedizinischen Versorgung wird durch die\npatientenindividuellen Erfordernisse im Einzelfall bestimmt. In medizinisch definierten\nFallkonstellationen (z.B. Phase einer Beatmungsentwöhnung) kann eine stabile\nBeatmungssituation bestehen, in der zur Steuerung der Beatmung keine invasiven\nMessverfahren notwendig sind.\nDaher wird in Ergänzung zu den Ausführungen der DKR 1001 festgelegt, dass das\ngeforderte Monitoring der Atmung im Rahmen der intensivmedizinischen Versorgung der\nPatienten entsprechend den patientenindividuellen, medizinischen Erfordernissen\nauszurichten ist.\nDie Formulierung stellt hierbei sicher, dass die Anwendbarkeit auf jede Form der Beatmung\nnach DKR 1001 gegeben ist und die Regeln zur Berechnung der Dauer der Beatmung nicht\nverändert werden.\n\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.12.2022 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 19.10.2022 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nRechtsbehelfsbelehrung:\nGegen diese Entscheidung des Schlichtungsausschusses kann innerhalb eines Monats nach\nBekanntgabe Klage beim Sozialgericht Berlin, Invalidenstr. 52, 10557 Berlin, schriftlich oder\nzu Protokoll des Urkundsbeamten der Geschäftsstelle erhoben werden.\nSiegburg, 19.10.2022\nDr. Franz Metzger\nVorsitzender des Schlichtungsausschusses nach § 19 KHG","pdfFile":"pdf/2022-09-21_S20220010_Entscheidung_S20220010-(Kl&auml;rung-Notwendigkeit-einer-t&auml;glichen-art.-oder-kap.-Blutgasanalys.pdf","codes":{"icd":[],"ops":[],"dkr":[]},"category":"regular"},{"decisionDate":"2022-11-30","publicationDate":"2022-12-22","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/entscheidungen-des-schlichtungsausschusses","id":"S20220012","categoryLabel":"Schlichtungsverfahren nach § 19 KHG","title":"Entscheidung_S20220012 (Kl&auml;rung Anwendung DKR-Psych 2022 PP014f auf Leistungen am Aufnahmetag ...) 22.12.2022.pdf (51,37 kB)","sourceURL":"https://www.g-drg.de/content/download/12749/file/Entscheidung_S20220012%20%28Kl%C3%A4rung%20Anwendung%20DKR-Psych%202022%20PP014f%20auf%20Leistungen%20am%20Aufnahmetag%20...%29%2022.12.2022.pdf","keywords":"Entscheidung_S20220012 (Kl&auml;rung Anwendung DKR-Psych 2022 PP014f auf Leistungen am Aufnahmetag ...) 22.12.2022.pdf (51,37 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n30.11.2022\nhat der Schlichtungsausschuss nach § 19 KHG über den Antrag S20220012 „Klärung\nAnwendung DKR-Psych 2022, PP014f auf Leistungen am Aufnahmetag in der KJPP“ der KJF\nKlinik Josefinum gGmbH wie folgt entschieden:\nEntscheidung S20220012\nKlärung Anwendung DKR-Psych 2022, PP014f auf Leistungen am Aufnahmetag in\nder KJPP:\nBei der Ermittlung der Therapieeinheiten gemäß OPS 9-649 Anzahl der Therapieeinheiten\npro Woche bei Erwachsenen und 9-696 Anzahl der Therapieeinheiten pro Woche bei\nKindern und Jugendlichen sind die Therapeutengespräche von den dort genannten\nBerufsgruppen ab Aufnahme, pauschal einmalig für den (teil)stationären Aufenthalt (in\nchronologischer Reihenfolge) in Höhe von 90 Minuten als Aufnahme- und\nKontrolluntersuchung gemäß DKR PP014 Prozeduren, die normalerweise nicht verschlüsselt\nwerden (Gespräche) nicht zu berücksichtigen. Für alle im weiteren Behandlungsverlauf über\ndie 90 Minuten hinausgehenden, durch die genannten Berufsgruppen erbrachten\nLeistungen, sind Therapieeinheiten entsprechend den Regelungen des OPS-Kodes 9-649\nAnzahl der Therapieeinheiten pro Woche bei Erwachsenen und 9-696 Anzahl der\nTherapieeinheiten pro Woche bei Kindern und Jugendlichen i.V.m. den entsprechenden\nPrimärkodes anzurechnen. Die somatischen Aufnahme- und Kontrolluntersuchungen sind\ngemäß DKR PP014 unabhängig davon nicht zu verschlüsseln.\nBegründung:\nMit dem vorliegenden Antrag soll die Frage geklärt werden, inwieweit\nTherapeutengespräche bei Aufnahme als Aufnahmeuntersuchung gemäß DKR PP014 zu\nwerten sind, oder ob es sich hierbei um eine anrechenbare und damit kodierbare\nTherapieeinheit handelt.\nDer Antrag bezieht sich dabei primär auf die Kinder- und Jugendpsychiatrie. Da der\nRegelungsgegenstand, die Anwendung der DKR PP014, auch die Erwachsenenpsychiatrie\nbetrifft, wurde mehrheitlich entschieden im Schiedsspruch auch diesen Bereich zu\nberücksichtigen. Eine unterschiedliche Handhabung des gleichen Sachverhalts in der Kinder-\nund Jugendpsychiatrie und in der Erwachsenenpsychiatrie erscheint nicht sinnvoll.\nEntsprechend der grundsätzlichen Festlegung in der DKR PP014, dass Leistungen, die bei\njedem Patienten anfallen, nicht zu kodieren sind, bestand prinzipielle Übereinstimmung\ndarüber, dass Therapeutengespräche bei Aufnahme nicht in vollem Umfang als\n\nTherapieeinheit Berücksichtigung finden können. Eine Abgrenzung der in der Praxis\ngebräuchlichen Begrifflichkeiten ist schwierig, auch findet in der Regel ein fließender\nÜbergang der einzelnen Maßnahmen (z. B. diagnostische und therapeutische Bestandteile\neines Therapeutengespräches) statt.\nZiel war es daher eine in der Praxis einfach anwendbare Umsetzung zu finden. Die im\nSchiedsspruch gefundene Regelung legt daher fest, dass die somatischen Aufnahme- und\nKontrolluntersuchungen keine kodierbare Leistung im Sinne der DKR PP014 darstellen. Von\nTherapeutengesprächen (z.B. Aufnahmegespräch und folgenden, erneuten\nAnamneseerhebung bei Therapeutenwechsel oder Stationswechsel) sind pauschal die ersten\n90 Minuten als nicht kodierbare Leistung entsprechend der DKR PP014 anzusehen und bei\nder Berechnung der Therapieeinheiten nicht zu berücksichtigen. Werden\nTherapeutengespräche beginnend mit dem Aufnahmeprozess bis zur Summe von 90\nMinuten von verschiedenen der im OPS (9-649.ff und 9-696.ff) genannten Berufsgruppen\nerbracht, so ist in chronologischer Reihenfolge vorzugehen. Die Pauschale von 90 Minuten\nist hierbei nicht für Therapeutengespräche jeder Berufsgruppe einzeln in Abzug zu bringen,\nsondern insgesamt einmalig für die Therapeutengespräche aller Berufsgruppen in Summe.\n\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.02.2023 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 22.12.2022 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nRechtsbehelfsbelehrung:\nGegen diese Entscheidung des Schlichtungsausschusses kann innerhalb eines Monats nach\nBekanntgabe Klage beim Sozialgericht Berlin, Invalidenstr. 52, 10557 Berlin, schriftlich oder\nzu Protokoll des Urkundsbeamten der Geschäftsstelle erhoben werden.\nSiegburg, 22.12.2022\nDr. Franz Metzger\nVorsitzender des Schlichtungsausschusses nach § 19 KHG","pdfFile":"pdf/2022-11-30_S20220012_Entscheidung_S20220012-(Kl&auml;rung-Anwendung-DKR-Psych-2022-PP014f-auf-Leistungen-am-Aufnahmetag-..pdf","codes":{"icd":[],"ops":["9-649","9-696","9-649.ff","9-696.ff"],"dkr":["PP014f","PP014"]},"category":"regular"},{"decisionDate":"2023-06-09","publicationDate":"2023-07-07","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/entscheidungen-des-schlichtungsausschusses","id":"S20230002","categoryLabel":"Schlichtungsverfahren nach § 19 KHG","title":"Entscheidung_S20230002 (Kann bei einer Infektion mit SARS-CoV-2 der Kode B34.2 (Infektion durch Coronaviren...) angegeben werden) 07.07.2023.pdf (51,45 kB)","sourceURL":"https://www.g-drg.de/content/download/12998/file/Entscheidung_S20230002%20%28Kann%20bei%20einer%20Infektion%20mit%20SARS-CoV-2%20der%20Kode%20B34.2%20%28Infektion%20durch%20Coronaviren...%29%20angegeben%20werden%29%2007.07.2023.pdf","keywords":"Entscheidung_S20230002 (Kann bei einer Infektion mit SARS-CoV-2 der Kode B34.2 (Infektion durch Coronaviren...) angegeben werden) 07.07.2023.pdf (51,45 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n09.06.2023\nhat der Schlichtungsausschuss nach § 19 KHG über den Antrag S20230002 „Kann bei einer\nInfektion mit SARS-CoV-2 der Kode B34.2 (Infektion durch Coronaviren nicht näher\nbezeichneter Lokalisation) angegeben werden?“ des GKV-Spitzenverbandes wie folgt\nentschieden:\nEntscheidung S20230002\nKann bei einer Infektion mit SARS-CoV-2 der Kode B34.2 (Infektion durch\nCoronaviren nicht näher bezeichneter Lokalisation) angegeben werden?:\nWird ein Patient wegen eines Symptoms oder mehrerer Symptome für COVID-19\naufgenommen und liegt keine organspezifische Manifestation vor, so ist das führende\nSymptom als Hauptdiagnose zu kodieren. Die Kodierung der ICD Schlüsselnummern B34.2\nInfektion durch Coronaviren nicht näher bezeichneter Lokalisation , B34.88 Sonstige\nVirusinfektionen nicht näher bezeichneter Lokalisation und B34.9 Virusinfektion, nicht\nnäher bezeichnet ist in Verbindung mit einem Kode aus U07.1! COVID -19, Virus\nnachgewiesen oder U07.2! COVID -19, Virus nicht nachgewiesen ausgeschlossen.\nBegründung:\nVom Antragsteller war die Klärung der Frage beantragt, ob für die Kodierung von Fällen\nmit COVID-19 Erkrankung der Kode B34.2 verwendet werden darf.\nDas Bundesinstitut für Arzneimittel und Medizinprodukte (BfArM) hat hierzu bereits\nmehrere Kodierfragen (Kodierfrage GM-1018, Kodierfrage GM-1019 sowie\nKodierempfehlung zu Fallkonstellationen im Zusammenhang mit dem Infektionsgeschehen\nSARS-CoV-2/COVID-19) veröffentlicht, die eine Verwendung des Kodes nicht befürworten\nbzw. explizit ausschließen. Für eine Erkrankung mit COVID-19 sind vielmehr die Kodes\nU07.1! oder U07.2! zu verwenden. Dieser Empfehlung des BfArM hat sich der\nSchlichtungsausschuss grundsätzlich angeschlossen. Um auch eine mögliche Ausweichkodie-\nrung zu regeln, wurden die Kodes B34.88 und B34.9 in den Schlichtungsspruch einbezogen.\nDie oben genannten Kodierfragen des BfArM sind bei der Kodierung von Fällen mit\nCOVID-19 Erkrankung prinzipiell zu beachten. Für die spezielle Fallkonstellation, dass sich\nein Patient mit einem oder mehreren Symptomen einer COVID-19 Erkrankung vorstellt, die\nkeiner organspezifischen Manifestation zugeordnet werden können, gibt die DKR D002\nHauptdiagnose Absatz „Zuweisung der zugrunde liegenden Krankheit als Hauptdiagnose“\n\nvor, dass die zugrunde liegende Erkrankung zu kodieren ist. Nach der oben genannten\nFestlegung wäre dies ein Kode aus dem Bereich U07.\n- Krankheiten mit unklarer Ätiologie,\nbelegte und nicht belegte Schlüsselnummern U07.-, allerdings dürfen die Kodes U07.1! und\nU07.2! nicht als Primärkode und somit nicht als Hauptdiagnose verwendet werden.\nGeschuldet ist dies der Situation, dass sie unterjährig eingeführt werden mussten.\nFür diesen Sonderfall wird daher festgelegt, dass abweichend von der DKR D002\nHauptdiagnose Absatz „Zuweisung der zugrunde liegenden Krankheit als Hauptdiagnose“\n,\ndas Symptom als Hauptdiagnose zu kodieren ist. Bei mehreren Symptomen ist als\nHauptdiagnose das Symptom (führendes Symptom) zu kodieren, das den höchsten\nRessourcenverbrauch verursacht hat (DKR D002 Absatz „Zwei oder mehr Diagnosen, die\ngleichermaßen der Definition der Hauptdiagnose entsprechen“ ). Der Primärkode für das\nSymptom ist dabei mit dem Sekundärkode U07.1! oder U07.2! zu kombinieren.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.09.2023 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 07.07.2023 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nRechtsbehelfsbelehrung:\nGegen diese Entscheidung des Schlichtungsausschusses kann innerhalb eines Monats nach\nBekanntgabe Klage beim Sozialgericht Berlin, Invalidenstr. 52, 10557 Berlin, schriftlich oder\nzu Protokoll des Urkundsbeamten der Geschäftsstelle erhoben werden.\nSiegburg, 07.07.2023\nDr. Franz Metzger\nVorsitzender des Schlichtungsausschusses nach § 19 KHG","pdfFile":"pdf/2023-06-09_S20230002_Entscheidung_S20230002-(Kann-bei-einer-Infektion-mit-SARS-CoV-2-der-Kode-B34.2-(Infektion-durch-Coro.pdf","codes":{"icd":["B34.2","B34.88","B34.9","U07.1","U07.2","U07"],"ops":[],"dkr":["D002"]},"category":"regular"},{"decisionDate":"2023-07-13","publicationDate":"2023-08-10","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/entscheidungen-des-schlichtungsausschusses","id":"S20230003","categoryLabel":"Schlichtungsverfahren nach § 19 KHG","title":"Entscheidung_S20230003 (Ist die Anlagerung von Knochenfragmenten an die Wirbels&auml;ule eine Spondylodese) 10.08.2023.pdf (49,33 kB)","sourceURL":"https://www.g-drg.de/content/download/13028/file/Entscheidung_S20230003%20%28Ist%20die%20Anlagerung%20von%20Knochenfragmenten%20an%20die%20Wirbels%C3%A4ule%20eine%20Spondylodese%29%2010.08.2023.pdf","keywords":"Entscheidung_S20230003 (Ist die Anlagerung von Knochenfragmenten an die Wirbels&auml;ule eine Spondylodese) 10.08.2023.pdf (49,33 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n13.07.2023\nhat der Schlichtungsausschuss nach § 19 KHG über den Antrag S20230003 „(Ist die\nAnlagerung von Knochenfragmenten an die Wirbelsäule eine Spondylodese?)“ des GKV-\nSpitzenverbandes wie folgt entschieden:\nEntscheidung S20230003\nIst die Anlagerung von Knochenfragmenten an die Wirbelsäule eine Spondylodese?:\nDie Spondylodese (OPS 5-836) kann sowohl als nicht instrumentierte als auch als\nsogenannte Instrumentations-Spondylodese erbracht werden. Eine nicht instrumentierte\nSpondylodese setzt neben der Verwendung von Knochenersatzmaterialien oder\nKnochentransplantaten auch die Eröffnung und Anfrischung (Entknorpelung) der\nWirbelgelenke voraus.\nBegründung:\nGemäß den, im Schlichtungsverfahren vorgetragenen, fachlichen Argumenten, kann eine\nSpondylodese (OPS-Kode 5-836) sowohl als nicht instrumentierte als auch als sogenannte\nlnstrumentations-Spondylodese erbracht werden. Für die Kodierung mit einem Kode aus\n5-836 ist im Fall einer Spondylodese, die nicht instrumentiert durchgeführt wird, neben den\nim OPS unter Hinweise genannten Voraussetzungen, auch die Eröffnung und Anfrischung\n(Entknorpelung) der Wirbelgelenke erforderlich.\nEine Überprüfung, der im OPS enthaltenen Hinweise zur Kodierung einer Spondylodese, um\ngegebenenfalls erforderliche, weitere Aspekte ist für das Vorschlagsverfahren für den OPS\nVersion 2025 vorgesehen.\n\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.10.2023 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 10.08.2023 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nRechtsbehelfsbelehrung:\nGegen diese Entscheidung des Schlichtungsausschusses kann innerhalb eines Monats nach\nBekanntgabe Klage beim Sozialgericht Berlin, Invalidenstr. 52, 10557 Berlin, schriftlich oder\nzu Protokoll des Urkundsbeamten der Geschäftsstelle erhoben werden.\nSiegburg, 10.08.2023\nDr. Franz Metzger\nVorsitzender des Schlichtungsausschusses nach § 19 KHG","pdfFile":"pdf/2023-07-13_S20230003_Entscheidung_S20230003-(Ist-die-Anlagerung-von-Knochenfragmenten-an-die-Wirbels&auml;ule-eine-Spondy.pdf","codes":{"icd":[],"ops":["5-836"],"dkr":[]},"category":"regular"},{"decisionDate":"2023-07-14","publicationDate":"2023-08-10","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/entscheidungen-des-schlichtungsausschusses","id":"S20220015","categoryLabel":"Schlichtungsverfahren nach § 19 KHG","title":"Entscheidung_S20220015 (Kodierung Hauptdiagnose bei Wiederaufnahme zur Cholezystektomie nach ERCP ...) 10.08.2023.pdf (51,29 kB)","sourceURL":"https://www.g-drg.de/content/download/13027/file/Entscheidung_S20220015%20%28Kodierung%20Hauptdiagnose%20bei%20Wiederaufnahme%20zur%20Cholezystektomie%20nach%20ERCP%20...%29%2010.08.2023.pdf","keywords":"Entscheidung_S20220015 (Kodierung Hauptdiagnose bei Wiederaufnahme zur Cholezystektomie nach ERCP ...) 10.08.2023.pdf (51,29 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n14.07.2023\nhat der Schlichtungsausschuss nach § 19 KHG über den Antrag S20220015 „(Kodierung\nHauptdiagnose bei Wiederaufnahme zur Cholezystektomie nach ERCP bei Cholangitis oder\nCholezystitis mit Gallenwegsobstruktion)“ des Universitätsklinikums Bonn wie folgt\nentschieden:\nEntscheidung S20220015\nKodierung Hauptdiagnose bei Wiederaufnahme zur Cholezystektomie nach ERCP\nbei Cholangitis oder Cholezystitis mit Gallenwegsobstruktion:\nWenn bei einem Patienten in einem vorangegangenen Aufenthalt bei Gallengangstein mit\nObstruktion eine ERCP zur Steinentfernung durchgeführt wurde und in einem zweiten\nAufenthalt die stationäre Aufnahme zur Cholezystektomie erfolgt, ist für die Festlegung\nder Hauptdiagnose für diesen zweiten Aufenthalt der für den aktuell vorliegenden Befund\n(z.B. Gallenblasenstein ohne Gallenwegsobstruktion) zutreffende Kode aus K80.-\nChole lithiasis zu verwenden.\nEntsprechend ist bei diesen Fällen beim Aufenthalt zur Gallenblasenentfernung nicht mehr\neine Obstruktion und/oder Entzündung zu kodieren, wenn diese nicht mehr vorliegen.\nDie Regelungen zur Fallzusammenführung bleiben hiervon unberührt.\nBegründung:\nIm Rahmen der Diskussion des Antrags wurde herausgearbeitet, dass es sich nicht nur um\nFälle handelt, bei denen eine geplante Aufnahme zur Folgebehandlung vorliegt. Daher\nwurde der Schlichtungsspruch so formuliert, dass er unabhängig von der anzuwendenden\nKodierrichtlinie zur Festlegung der Hauptdiagnose in den beschriebenen Situationen\nangewandt werden kann.\nPrinzipiell wird die Anwendbarkeit der DKR D005 Fol g ezustände und geplante\nFolgeeingriffe auf eine der im Antrag beschriebenen Fallkonstellationen gesehen, wenn die\nVoraussetzungen zur Anwendbarkeit der DKR D005, insbesondere, dass die\nCholezystektomie bereits während des Aufenthaltes, in dem die ERCP zur Steinentfernung\ndurchgeführt wurde, konkret geplant worden sein muss, gegeben sind.\nDarüber hinaus liegen nun Kodes zur Kodierung als Hauptdiagnose vor (K80.-\nCholelithiasis ), die neben der Kodierung der Grunderkrankung noch weitere Informationen\nzum Ausprägungsgrad enthalten. Hier ist zwischen der Kodierung der Grunderkrankung\nund dem Ausprägungsgrad zu differenzieren. Die möglichen Ausprägungsgrade einer\nCholelithiasis mit bzw. ohne Gallenwegsobstruktion, Cholangitis oder Cholezystitis sind bei\n\nerneuter Aufnahme zur Folgebehandlung nur dann zu kodieren, wenn diese noch\nvorhanden sind bzw. die Aufnahme mitbegründet haben.\nBei den Fällen, bei denen es zu einem Abweichen von der zu berücksichtigenden Leitlinie\nkommt, sollte auch eine entsprechende Begründung dokumentiert werden.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.10.2023 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 10.08.2023 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nRechtsbehelfsbelehrung:\nGegen diese Entscheidung des Schlichtungsausschusses kann innerhalb eines Monats nach\nBekanntgabe Klage beim Sozialgericht Berlin, Invalidenstr. 52, 10557 Berlin, schriftlich oder\nzu Protokoll des Urkundsbeamten der Geschäftsstelle erhoben werden.\nSiegburg, 10.08.2023\nDr. Franz Metzger\nVorsitzender des Schlichtungsausschusses nach § 19 KHG","pdfFile":"pdf/2023-07-14_S20220015_Entscheidung_S20220015-(Kodierung-Hauptdiagnose-bei-Wiederaufnahme-zur-Cholezystektomie-nach-ERCP-...pdf","codes":{"icd":["K80"],"ops":[],"dkr":["D005"]},"category":"regular"},{"decisionDate":"2023-08-09","publicationDate":"2023-09-06","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/entscheidungen-des-schlichtungsausschusses","id":"S20210008","categoryLabel":"Schlichtungsverfahren nach § 19 KHG","title":"Entscheidung_S20210008 (Berechnung der Dauer einer kontinuierlichen Dialyse) 06.09.2023.pdf (54,16 kB)","sourceURL":"https://www.g-drg.de/content/download/13060/file/Entscheidung_S20210008%20%28Berechnung%20der%20Dauer%20einer%20kontinuierlichen%20Dialyse%29%2006.09.2023.pdf","keywords":"Entscheidung_S20210008 (Berechnung der Dauer einer kontinuierlichen Dialyse) 06.09.2023.pdf (54,16 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n09.08.2023\nhat der Schlichtungsausschuss nach § 19 KHG über den Antrag S20210008 „Berechnung der\nDauer einer kontinuierlichen Dialyse“ des Universitätsklinikums Hamburg-Eppendorf wie\nfolgt entschieden:\nEntscheidung S20210008\nBerechnung der Dauer einer kontinuierlichen Dialyse:\nBei kontinuierlichen Nierenersatzverfahren gemäß den OPS-Kodes 8-853, 8-854, 8-855,\n8-857 und 8-85a sind Zeiten einer Unterbrechung von jeweils bis zu 24 Stunden bei der\nBerechnung der Dauer der einzelnen Behandlungszyklen/Anwendungen mitzuzählen.\nSofern, retrospektiv betrachtet, das Verfahren nach einer Unterbrechung von mehr als 24\nStunden endete oder nach mehr als 24 Stunden wiederaufgenommen wurde, ist der\nBehandlungszyklus abgeschlossen. Am letzten Tag des Behandlungszyklus wird die\nStundenzahl von 00:00 Uhr bis zur tatsächlichen Beendigung des Verfahrens, auf volle\nStunden aufgerundet, berechnet.\nBegründung:\nMit dem vorliegenden Antrag sollte die Frage geklärt werden, wie Pausenzeiten (z.B. durch\nFilterwechsel, Unterbrechung durch Diagnostik, Auslassversuch etc.) bei kontinuierlichen\nNierenersatzverfahren für die Berechnung der zu kodierenden Dauer eines\nBehandlungszyklus zu berücksichtigen sind. Nach eingehender Beratung der vorgetragenen\nAspekte ist der Schlichtungsausschuss zu der Überzeugung gelangt, dass einzelne\nPausenzeiten von jeweils bis zu 24 Stunden nicht in Abzug zu bringen sind, insbesondere\nunter dem Aspekt, dass dies einen erheblichen Mehraufwand für die Dokumentation\nbedeuten würde.\nMit der im Beschluss dargestellten, ergänzenden Regelung in Satz 2 und 3 soll klargestellt\nwerden, dass die Zeit nach der Beendigung eines Behandlungszyklus nicht im Sinne eines\nAuslassversuchs zu zählen ist. Damit soll den vorgetragenen Bedenken, dass mit der\ngetroffenen Regelung nach Satz 1 am Ende eines jeden Behandlungszyklus eines\nkontinuierlichen Nierenersatzverfahrens ein Zeitraum von bis zu 24 Stunden als\nAuslassversuch deklariert und zur Gesamtzeit hinzugezählt werden könnte, Rechnung\ngetragen werden. Die getroffene Entscheidung legt fest, dass für die Berechnung der Dauer\neines kontinuierlichen Nierenersatzverfahren die Stunden von Beginn der maschinellen\nBehandlung bis zum Ende der maschinellen Behandlung gezählt werden, ohne dazwischen\nliegende, einzelne Pausen von jeweils bis zu 24 Stunden in Abzug bringen zu müssen.\n\nEine Regelung für Unterbrechungen von mehr als 24 Stunden ist nicht notwendig, da dies\nnach den Hinweisen im OPS den Beginn eines neuen Behandlungszyklus definiert und somit\ndie Kodierung eines neuen OPS-Kodes mit neuer Stundenzählung auslöst.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.11.2023 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 06.09.2023 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nRechtsbehelfsbelehrung:\nGegen diese Entscheidung des Schlichtungsausschusses kann innerhalb eines Monats nach\nBekanntgabe Klage beim Sozialgericht Berlin, Invalidenstr. 52, 10557 Berlin, schriftlich oder\nzu Protokoll des Urkundsbeamten der Geschäftsstelle erhoben werden.\nSiegburg, 06.09.2023\nDr. Franz Metzger\nVorsitzender des Schlichtungsausschusses nach § 19 KHG","pdfFile":"pdf/2023-08-09_S20210008_Entscheidung_S20210008-(Berechnung-der-Dauer-einer-kontinuierlichen-Dialyse)-06.09.2023.pdf-(54,16-k.pdf","codes":{"icd":[],"ops":["8-853","8-854","8-855","8-857","8-85a"],"dkr":[]},"category":"regular"},{"decisionDate":"2024-07-30","publicationDate":"2024-08-27","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/entscheidungen-des-schlichtungsausschusses","id":"S20240001","categoryLabel":"Schlichtungsverfahren nach § 19 KHG","title":"Entscheidung_S20240001 (Kodierung patientenindividuell angefertigter Beckenteilersatz) 27.08.2024.pdf (49,99 kB)","sourceURL":"https://www.g-drg.de/content/download/13936/file/Entscheidung_S20240001%20%28Kodierung%20patientenindividuell%20angefertigter%20Beckenteilersatz%29%2027.08.2024.pdf","keywords":"Entscheidung_S20240001 (Kodierung patientenindividuell angefertigter Beckenteilersatz) 27.08.2024.pdf (49,99 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n30.07.2024\nhat der Schlichtungsausschuss nach § 19 KHG über den Antrag S20240001 „Kodierung\npatientenindividuell angefertigter Beckenteilersatz“ der Orthopädischen Klinik Volmarstein\nwie folgt entschieden:\nEntscheidung S20240001\nKodierung patientenindividuell angefertigter Beckenteilersatz:\nDie Implantation eines individuell angefertigten metallischen Knochenersatzes am Becken\nist mit dem Kode 5-785.4d Implantation von alloplastischem Knochenersatz: Metallischer\nKnochenersatz: Becken zu kodieren. Ein zusätzlicher Kode ist zur Abbildung dieses\nOperationsschrittes nicht erforderlich.\nDer Kode 5-829.m Andere gelenkplastische Eingriffe: Implantation von oder (Teil - )Wechsel\nin ein patientenindividuell hergestelltes Implantat bei knöcherner Defektsituation oder\nangeborener oder erworbener Deformität ist nur bei zusätzlicher patientenindividueller\nendoprothetischer Versorgung zu verwenden.\nBegründung:\nIm vorliegenden Schlichtungsverfahren war die Frage zu beantworten, ob bei der\nImplantation eines patientenindividuell angefertigten Beckenteilersatzes neben dem Kode\n5-785.4d Implantation von alloplastischem Knochenersatz: Metallischer Knochenersatz,\nBecken auch der Kode 5-829.m Andere gelenkplastische Eingriffe: Implantation von oder\n(Teil - )Wechsel in ein patientenindividuell hergestelltes Implantat bei knöcherner\nDefektsituat ion oder angeborener oder erworbener Deformität angegeben werden kann\num abzubilden, dass es sich um einen patientenindividuellen Beckenteilersatz gehandelt\nhat.\nDem Antrag zugrunde lag eine Fallkonstellation mit Implantation eines\npatientenindividuellen (präoperativ anhand von CT-Aufnahmen des Beckens angefertigtes,\nspeziell auf den Defekt zugeschnittenes Implantat), metallischen Beckenteilersatzes zur\nHerstellung eines tragfähigen Implantatlagers. Dieses ermöglichte die Implantation der\neigentlichen, pfannenseitig zementierten Hüft-Totalendoprothese.\nNeben der oben dargestellten Fragestellung war daher im Verfahren auch die Frage zu\nklären, wie der beschriebene Beckenteilersatz zu kodieren ist. Es wurde herausgearbeitet,\ndass für die Implantation eines patientenindividuell angefertigten Beckenteilersatzes nur\nder Schlüssel 5-785.4d zu verwenden ist, da das beschriebene Implantat keine\ngelenkbildende Komponente enthielt und es sich daher nicht um einen endoprothetischen\n\nGelenk- und Knochenersatz im Sinne des Kapitels 5-82 Endoprothetischer Gelenk - und\nKnochenersatz (gelenkplastischer Eingriff) handelte. Dieser Sachverhalt wird mit den Sätzen\n1 und 2 des Schlichtungsergebnisses zum Ausdruck gebracht.\nEine differenzierte Darstellung der patientenindividuellen Anfertigung des\nBeckenteilersatzes ist in der aktuellen Version des OPS nicht möglich. Der letzte Satz des\nSchlichtungsergebnisses dient daher der Klarstellung, dass der vom Antragsteller hierfür\nvorgeschlagene Kode 5-829.m für die oben dargestellte Fallkonstellation nicht verwendet\nwerden kann. Dieser Kode ist nur dann zu verwenden, wenn ein zusätzlicher\ngelenkplastischer Eingriff (oder ein eigenständiger gelenkplastischer Eingriff) mit den in\ndiesem Kode beschriebenen Merkmalen durchgeführt wird.\nDarüber hinaus wurde im Verfahren festgehalten, dass der aktuelle OPS hinsichtlich des zu\nkodierenden Eingriffs gegebenenfalls mehrdeutig und unvollständig ist. Daher wird die\nFachgesellschaft ausdrücklich darum gebeten, eine Überarbeitung für den OPS ab der\nVersion 2026 vorzuschlagen.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.10.2024 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 27.08.2024 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nRechtsbehelfsbelehrung:\nGegen diese Entscheidung des Schlichtungsausschusses kann innerhalb eines Monats nach\nBekanntgabe Klage beim Sozialgericht Berlin, Invalidenstr. 52, 10557 Berlin, schriftlich oder\nzu Protokoll des Urkundsbeamten der Geschäftsstelle erhoben werden.\nSiegburg, 27.08.2024\nDr. Franz Metzger\nVorsitzender des Schlichtungsausschusses nach § 19 KHG","pdfFile":"pdf/2024-07-30_S20240001_Entscheidung_S20240001-(Kodierung-patientenindividuell-angefertigter-Beckenteilersatz)-27.08.2024.pd.pdf","codes":{"icd":[],"ops":["5-785.4d","5-829.m","5-82"],"dkr":[]},"category":"regular"},{"decisionDate":"2024-12-11","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/entscheidungen-des-schlichtungsausschusses","id":"S20240003","categoryLabel":"Schlichtungsverfahren nach § 19 KHG","title":"Entscheidung_S20240003 (Wie wird eine vorliegende Infektion (z B Erysipel) mit Bakteri&auml;mie verschl&uuml;sselt) 21 01 2025.pdf (65,97 kB)","sourceURL":"https://www.g-drg.de/content/download/16289/file/Entscheidung_S20240003%20%28Wie%20wird%20eine%20vorliegende%20Infektion%20%28z%20B%20%20Erysipel%29%20mit%20Bakteri%C3%A4mie%20verschl%C3%BCsselt%29%2021%2001%202025.pdf","keywords":"Entscheidung_S20240003 (Wie wird eine vorliegende Infektion (z B Erysipel) mit Bakteri&auml;mie verschl&uuml;sselt) 21 01 2025.pdf (65,97 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n11.12.2024\nhat der Schlichtungsausschuss nach § 19 KHG über den Antrag S20240003 „Kodierung einer\nBakteriämie: Wie wird eine vorliegende Infektion (z.B. Erysipel) mit Bakteriämie\nverschlüsselt?“ des Klinikums Fulda gAG wie folgt entschieden:\nEntscheidung S20240003\nKodierung einer Bakteriämie: Wie wird eine vorliegende Infektion (z.B. Erysipel) mit\nBakteriämie verschlüsselt?:\nBei Vorliegen einer Bakteriämie in Zusammenhang mit einer spezifischen Infektion (z. B.\neinem Harnwegsinfekt) wird nur die zugrunde liegende Infektion verschlüsselt.\nEine isolierte Bakteriämie ohne Infektfokus ist mit einem Kode aus\nA49.- Bakterielle Infektion nicht näher bezeichneter Lokalisation\nzu kodieren.\nBegründung:\nDer Schlichtungsausschuss hatte die Frage zu entscheiden, ob eine Bakteriämie, die in\ndirektem Zusammenhang mit einer vorliegenden Infektion steht, mit einem Kode aus A49.-\nBakterielle Infektion nicht näher bezeichneter Lokalisation zusätzlich zu der vorliegenden\nInfektion kodiert werden kann.\nIn der Abwägung der vorgetragenen Argumente  von denen jedes für sich gesehen\nnachvollziehbar und begründet war  und der anzuwendenden Kodierrichtlinien, ist die\nMehrheit des Schlichtungsausschusses zu dem Ergebnis gekommen die Kodierung einer\nBakteriämie mit einem Kode aus A49.- auf die Fälle zu beschränken, bei denen die\nBakteriämie nicht auf einen gleichzeitig bestehenden Infektfokus zurückzuführen ist.\nDer erste Satz der Entscheidung ist so zu verstehen, dass hier ein enger zeitlicher und\ninhaltlicher Zusammenhang zur Infektion bestehen muss. Somit ist es nicht ausgeschlossen,\ndass bei einem Fall beide Kodierungen erfolgen können, wenn zwei unterschiedliche\nSachverhalte, die medizinisch zu trennen sind, bestehen.\nIn der Zusammenschau war unter anderem relevant, dass der bis einschließlich 2024 zu\nberücksichtigende Absatz „Bakteriämie“ der DKR 0103w Bakteriämie, Sepsis und\nNeutropenie zur Abgrenzung der Kodierung einer Bakteriämie zur Sepsis gedacht war und\ndamit nicht als Legitimation zu verstehen war, bei Nachweis bestimmter Erreger in einer\n\nBlutkultur – ohne Anzeichen einer Sepsis – zu einer spezifischen Infektion auch eine\nBakteriämie mit einem Kode aus A49.- zusätzlich zu kodieren.\nDie getroffene Regelung steht auch im Einklang mit den Hinweisen zur\nDoppelklassifizierung unter Ziffer „2.“ der DKR D012v Mehrfachkodierung . Auch\nmaßgeblich waren die Vorgaben der Kodierrichtlinie D013c Im Systematischen Verzeichnis\nverwendete formale Vereinbarungen , Absatz „Ohne nähere Angabe „o.n.A.““. Diesen\nwurde dahingehend Rechnung getragen, dass keine Kodes mit Infektionen nicht näher\nbezeichneter Lokalisation mit Kodes zu kombinieren sind, die eine Lokalisation der\nInfektion beinhalten.\nEs wäre wünschenswert zu überprüfen, ob die spezifische Kodierung einer\n„Blutstrominfektion“, welche die ICD-11 vorsieht, vorab in die ICD-10-GM übernommen\nwerden kann.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen\nKrankenhäuser, die Krankenkassen und die Medizinischen Dienste für die Erstellung oder\nPrüfung von Krankenhausabrechnungen für Patientinnen und Patienten, die ab dem\n01.03.2025 in das Krankenhaus aufgenommen werden und für die\nKrankenhausabrechnungen, die am 21.01.2025 bereits Gegenstand einer Prüfung durch den\nMedizinischen Dienst nach § 275 Absatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch\nsind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und\nein Vorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nRechtsbehelfsbelehrung:\nGegen diese Entscheidung des Schlichtungsausschusses kann innerhalb eines Monats nach\nBekanntgabe Klage beim Sozialgericht Berlin, Invalidenstr. 52, 10557 Berlin, schriftlich oder\nzu Protokoll des Urkundsbeamten der Geschäftsstelle erhoben werden.\nSiegburg, 21.01.2025\nDr. Franz Metzger\nVorsitzender des Schlichtungsausschusses nach § 19 KHG","pdfFile":"pdf/2024-12-11_S20240003_Entscheidung_S20240003-(Wie-wird-eine-vorliegende-Infektion-(z-B-Erysipel)-mit-Bakteri&auml;mie-vers.pdf","codes":{"icd":["A49"],"ops":[],"dkr":["D012v","D013c"]},"category":"regular"},{"decisionDate":"2025-10-08","publicationDate":"2025-11-05","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/entscheidungen-des-schlichtungsausschusses","id":"S20250001","categoryLabel":"Schlichtungsverfahren nach § 19 KHG","title":"Entscheidung_S20250001 (Klarstellung zu DKR0401 Hypoglyk&auml;mie als Komplikation mitz&auml;hlen oder nicht) 05.11.2025.pdf (50,25 kB)","sourceURL":"https://www.g-drg.de/content/download/17365/file/Entscheidung_S20250001%20%28Klarstellung%20zu%20DKR0401%20Hypoglyk%C3%A4mie%20als%20Komplikation%20mitz%C3%A4hlen%20oder%20nicht%29%2005.11.2025.pdf","keywords":"Entscheidung_S20250001 (Klarstellung zu DKR0401 Hypoglyk&auml;mie als Komplikation mitz&auml;hlen oder nicht) 05.11.2025.pdf (50,25 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n08.10.2025\nhat der Schlichtungsausschuss nach § 19 KHG über den Antrag S20250001 „Klarstellung zu\nDKR0401: Hypoglykämie als Komplikation mitzählen oder nicht?“ des Städtischen Klinikums\nDresden wie folgt entschieden:\nEntscheidung S20250001\nKlarstellung zu DKR0401: Hypoglykämie als Komplikation mitzählen oder nicht?:\nEine Hypoglykämie ist bei der Anwendung der Kodes E10-14.6- (vierte Stelle .6- Mit sonstigen\nnäher bezeichneten Komplikationen ) und E10-14.7- (vierte Stelle .7- Mit multiplen\nKomplikationen ) als zu zählende Komplikation eines Diabetes mellitus nur dann für diesen\nstationären Aufenthalt zu berücksichtigen, wenn:\n• ein Hypoglykämisches Koma bei Diabetes mellitus gemäß U69.73! vorliegt.\nDer Schweregrad einer Hypoglykämie wird unabhängig davon durch die Schlüsselnummern\nU69.70!-U69.73! zusätzlich angegeben.\nBegründung:\nDer Schlichtungsausschuss hatte die Frage zu entscheiden, ob Hypoglykämien bei Patienten\nmit Diabetes mellitus als Komplikation mitzuzählen und damit an der vierten Stelle der ICD-\n10-GM (E10 bis E14 Diabetes mellitus ) entsprechend zu kodieren sind.\nHintergrund der getroffenen Entscheidung war die Überzeugung des\nSchlichtungsausschusses, dass nicht jede Hypoglykämie behandlungsbedürftig ist und einen\nMehraufwand verursacht. Einigkeit bestand darin, dass ein hypoglykämisches Koma\nregelhaft zu einem entsprechenden Ressourcenverbrauch führt und die Berücksichtigung im\nG-DRG-System somit sachgerecht erscheint. Daher ist nur eine Hypoglykämie in Verbindung\nmit einem hypoglykämischen Koma (entsprechend dem Kode U69.73! Hypoglykämisches\nKoma bei Diabetes mellitus ) als relevante Komplikation bei der Zählung von Komplikationen\neines Diabetes mellitus zu werten und bei den Kodes aus E10-E14 an der vierten Stelle „.6“\noder „.7“ als zu zählende Komplikation zu berücksichtigen.\nEs ist auch darauf hinzuweisen, dass der zweite Satz nicht so zu verstehen ist, dass eine\nzusätzliche Kodierung nur auf die Schlüsselnummern U69.70!-U69.73! beschränkt ist. Gemäß\nder Kodierrichtlinie D012 Mehrfachkodierung gehören die Diagnosen aus dem Kodebereich\nU69.7-! Sekundäre Schlüsselnummern zur Angabe des Schweregrades einer Hypoglykämie,\ndes Vorliegens einer Hypoglykämiewahrnehmungsstörung oder einer Insulinresistenz zu den\n\nobligat anzugebenden Ausrufezeichenkodes (siehe Tabelle 2 der DKR D012). Somit ist auch\ndas Vorliegen einer Hypoglykämiewahrnehmungsstörung oder einer Insulinresistenz\n(U69.74! bzw. U69.75!) zu kodieren, was zukünftig Analysen zur möglichst genauen\nAufwandsabgrenzung ermöglicht.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen Krankenhäuser,\ndie Krankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.01.2026 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n05.11.2025 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und ein\nVorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\nRechtsbehelfsbelehrung:\nGegen diese Entscheidung des Schlichtungsausschusses kann innerhalb eines Monats nach\nBekanntgabe Klage beim Sozialgericht Berlin, Invalidenstr. 52, 10557 Berlin, schriftlich oder\nzu Protokoll des Urkundsbeamten der Geschäftsstelle erhoben werden.\nSiegburg, 05.11.2025\nDr. Franz Metzger\nVorsitzender des Schlichtungsausschusses nach § 19 KHG","pdfFile":"pdf/2025-10-08_S20250001_Entscheidung_S20250001-(Klarstellung-zu-DKR0401-Hypoglyk&auml;mie-als-Komplikation-mitz&auml;hlen-od.pdf","codes":{"icd":["E10","U69.73","U69.70","E14","U69.7","U69.74","U69.75"],"ops":[],"dkr":["D012"]},"category":"regular"},{"decisionDate":"2026-07-01","publicationDate":"2026-07-29","sourcePage":"https://www.g-drg.de/schlichtungsausschuss-nach-19-khg/entscheidungen-des-schlichtungsausschusses","id":"S20260001","categoryLabel":"Schlichtungsverfahren nach § 19 KHG","title":"Entscheidung_S20260001 (Kl&auml;rung Kodierung und Abrechnung des OPS-8-98f.) 29.07.2026.pdf (72,34 kB)","sourceURL":"https://www.g-drg.de/content/download/19020/file/Entscheidung_S20260001%20%28Kl%C3%A4rung%20Kodierung%20und%20Abrechnung%20des%20OPS-8-98f.%29%2029.07.2026.pdf","keywords":"Entscheidung_S20260001 (Kl&auml;rung Kodierung und Abrechnung des OPS-8-98f.) 29.07.2026.pdf (72,34 kB)","fullText":"Institut für das Entgeltsystem im Krankenhaus GmbH\nInstitutsträger: Deutsche Krankenhausgesellschaft • GKV-Spitzenverband • Verband der privaten Krankenversicherung\nGeschäftsstelle des Schlichtungsausschusses nach § 19 KHG\nIn dem Schlichtungsverfahren vom\n01.07.2026\nhat der Schlichtungsausschuss nach § 19 KHG über den Antrag S20260001 „Klärung\nKodierung und Abrechnung des OPS-8-98f.*“ des KRH Klinikums Region Hannover wie folgt\nentschieden:\nEntscheidung S20260001\nKlärung Kodierung und Abrechnung des OPS-8-98f.*:\nWird im Rahmen einer aufwendigen intensivmedizinischen Komplexbehandlung (OPS 8-98f)\ninnerhalb der ersten 13 Tage der Behandlung auf der Intensivstation das Mindestmerkmal\nder täglichen Visite durch einen Facharzt mit der Zusatzbezeichnung Intensivmedizin (die\nBehandlungsleitung oder ein anderer Facharzt mit der Zusatzbezeichnung Intensivmedizin)\nnicht dokumentiert, kann ein Kode aus 8-98f Aufwendige intensivmedizinische\nKomplexbehandlung (Basisprozedur) nicht kodiert werden.\nNach einer Aufenthaltsdauer von 13 Tagen auf der Intensivstation darf das Mindestmerkmal\nder täglichen Visite durch einen Facharzt mit der Zusatzbezeichnung Intensivmedizin\nmaximal einmal alle angefangenen 28 Tage, gerechnet vom Beginn des Aufenthaltes auf der\nIntensivstation, nicht dokumentiert sein. Zusätzlich darf zu keinem Zeitpunkt an zwei\naufeinanderfolgenden Tagen dieses Mindestmerkmal nicht dokumentiert worden sein. Die\nBehandlungstage auf der Intensivstation, an welchen keine Visite durch einen Facharzt mit\nder Zusatzbezeichnung Intensivmedizin dokumentiert wurde, dürfen in diesem Fall nicht für\ndie Zählung der Aufwandspunkte herangezogen werden. Wird diese Regelung nicht\neingehalten, ist der Kodebereich 8-98f Aufwendige intensivmedizinische\nKomplexbehandlung (Basisprozedur) für die gesamte Verweildauer auf der Intensivstation\nnicht anwendbar.\nBegründung:\nMit der vorliegenden Entscheidung wurde durch den Schlichtungsausschuss definiert, in\nwelchen Fallkonstellationen die fehlende Dokumentation des Mindestmerkmals der\ntäglichen Visite durch einen Facharzt mit der Zusatzbezeichnung Intensivmedizin (…) dazu\nführt, dass eine aufwendige intensivmedizinische Komplexbehandlung (OPS 8-98f) für die\ngesamte Verweildauer auf der Intensivstation nicht angegeben werden kann. Dem\nSchlichtungsausschuss war dabei die Einhaltung dieses Mindestmerkmals und somit die\nAbgrenzung der Kodierung der aufwendigen intensivmedizinischen Komplexbehandlung\n(OPS 8-98f) zur Kodierung der intensivmedizinischen Komplexbehandlung (OPS 8-980) sehr\nwichtig.\n\nEs ist in Einzelfällen möglich, dass an einzelnen Tagen aufgrund besonderer Umstände die\ntägliche Visite von einem Facharzt mit der Zusatzbezeichnung Intensivmedizin (…) nicht\ndurchgeführt werden konnte oder nicht dokumentiert wurde. Das komplette Wegfallen der\nKodierung der aufwendigen intensivmedizinischen Komplexbehandlung (OPS 8-98f) für die\ngesamte Aufenthaltsdauer auf der Intensivstation erschien für einen solchen Ausnahmefall\nnicht verhältnismäßig.\nDaher wurde die Regelung, in welchen Konstellationen die fehlende Dokumentation des\nMindestmerkmals der täglichen Visite durch einen Facharzt mit der Zusatzbezeichnung\nIntensivmedizin (…) nicht zum Wegfallen der Anwendbarkeit des Kodes (OPS 8-98f) führt,\nsehr eng gefasst und auf Ausnahmefälle begrenzt.\nDa zu Beginn einer intensivmedizinischen Behandlung die enge Betreuung mit fachärztlicher\nExpertise essenziell erschien, wurde ein Zeitraum von 13 Kalendertagen, gemessen ab dem\nAufnahmetag auf die Intensivstation (bei mehreren Intensivaufenthalten gemessen ab dem\nersten Aufenthalt auf der Intensivstation), festgelegt, an denen eine tägliche Visite durch\neinen Facharzt mit der Zusatzbezeichnung Intensivmedizin (…) durchgehend dokumentiert\nsein muss. Der Begriff der Dokumentation bezieht sich auf den überprüfbaren Nachweis in\nder Krankenakte.\nAb dem 14. Kalendertag darf in jedem Intervall von 28 angefangenen Kalendertagen,\ngemessen ab dem Aufnahmetag auf die Intensivstation (bei mehreren Intensivaufenthalten\ngemessen ab dem ersten Aufenthalt auf der Intensivstation), an jeweils einem Tag die\nDokumentation der täglichen Visite durch einen Facharzt mit der Zusatzbezeichnung\nIntensivmedizin (…) fehlen, ohne dass die Anwendbarkeit eines Kodes aus 8-98f Aufwendige\nintensivmedizinische Komplexbehandlung (Basisprozedur) wegfällt. Wichtig ist hierbei, dass\ndieses nicht an zwei aufeinanderfolgenden Tagen (z.B. 28. und 29. Kalendertag ab\nAufnahme) erfolgen darf, um zu vermeiden, dass an einem Wochenende keine Visite erfolgt.\nDie fehlende Dokumentation der Visite durch einen Facharzt mit der Zusatzbezeichnung\nIntensivmedizin (…) führt aber innerhalb des oben festgelegten Rahmens immer dazu, dass\nfür diesen Tag keine Aufwandspunkte für die aufwendige intensivmedizinische\nKomplexbehandlung gezählt werden können.\nGültigkeit:\nDie Entscheidungen des Schlichtungsausschusses gelten für die zugelassenen Krankenhäuser,\ndie Krankenkassen und die Medizinischen Dienste für die Erstellung oder Prüfung von\nKrankenhausabrechnungen für Patientinnen und Patienten, die ab dem 01.09.2026 in das\nKrankenhaus aufgenommen werden und für die Krankenhausabrechnungen, die am\n29.07.2026 bereits Gegenstand einer Prüfung durch den Medizinischen Dienst nach § 275\nAbsatz 1 Nummer 1 des Fünften Buches Sozialgesetzbuch sind.\nVorsorglich weisen wir darauf hin, dass eine Klage gegen die Entscheidungen des\nSchlichtungsausschusses nach § 19 Abs. 7 S. 3 KHG keine aufschiebende Wirkung hat und ein\nVorverfahren gemäß § 19 Abs. 7 S. 2 KHG nicht stattfindet.\n\nRechtsbehelfsbelehrung:\nGegen diese Entscheidung des Schlichtungsausschusses kann innerhalb eines Monats nach\nBekanntgabe Klage beim Landessozialgericht Berlin-Brandenburg, Försterweg 2 - 6,\n14482 Potsdam, schriftlich oder zu Protokoll des Urkundsbeamten der Geschäftsstelle\nerhoben werden.\nSiegburg, 29.07.2026\nDr. Franz Metzger\nVorsitzender des Schlichtungsausschusses nach § 19 KHG","pdfFile":"pdf/2026-07-01_S20260001_Entscheidung_S20260001-(Kl&auml;rung-Kodierung-und-Abrechnung-des-OPS-8-98f.)-29.07.2026.pdf-(72,34-.pdf","codes":{"icd":[],"ops":["8-98f","8-980"],"dkr":[]},"category":"regular"}];
